{"command":"cat > /tmp/sim/h2.py <<'EOF'
class RustHeap:
    def __init__(self, le):
        self.data=[]; self.le=le
    def push(self, x):
        self.data.append(x); self.sift_up(0, len(self.data)-1)
    def sift_up(self, start, pos):
        d=self.data; elt=d[pos]
        while pos>start:
            parent=(pos-1)//2
            if self.le(elt, d[parent]): break
            d[pos]=d[parent]; pos=parent
        d[pos]=elt
    def pop(self):
        d=self.data
        if not d: return None
        item=d.pop()
        if d:
            item, d[0] = d[0], item
            self.sift_down_to_bottom(0)
        return item
    def sift_down_to_bottom(self, pos):
        d=self.data; end=len(d); start=pos; elt=d[pos]
        child=2*pos+1
        while child <= end-2:
            if self.le(d[child], d[child+1]): child+=1
            d[pos]=d[child]; pos=child; child=2*pos+1
        if child==end-1:
            d[pos]=d[child]; pos=child
        d[pos]=elt
        self.sift_up(start,pos)
import sys
n=int(sys.argv[1]); pops=int(sys.argv[2])
