    Spec { long: "only-folders", short: Some('f'), kind: ArgKind::Flag },
    Spec { long: "no-only-folders", short: Some('F'), kind: ArgKind::Flag },
    Spec { long: "show-root-fs", short: None, kind: ArgKind::Flag },
    Spec { long: "max-depth", short: None, kind: ArgKind::Value("MAX_DEPTH") },
    Spec { long: "show-git-info", short: Some('g'), kind: ArgKind::Flag },
    Spec { long: "no-show-git-info", short: Some('G'), kind: ArgKind::Flag },
    Spec { long: "git-status", short: None, kind: ArgKind::Flag },
    Spec { long: "hidden", short: Some('h'), kind: ArgKind::Flag },
    Spec { long: "no-hidden", short: Some('H'), kind: ArgKind::Flag },
