    Spec { long: "no-git-ignored", short: Some('I'), kind: ArgKind::Flag },
    Spec { long: "permissions", short: Some('p'), kind: ArgKind::Flag },
    Spec { long: "no-permissions", short: Some('P'), kind: ArgKind::Flag },
