    Spec { long: "sort-by-date", short: None, kind: ArgKind::Flag },
    Spec { long: "sort-by-size", short: None, kind: ArgKind::Flag },
    Spec { long: "sort-by-type", short: None, kind: ArgKind::Flag },
    Spec { long: "no-tree", short: None, kind: ArgKind::Flag },
    Spec { long: "tree", short: None, kind: ArgKind::Flag },
