    Spec { long: "write-default-conf", short: None, kind: ArgKind::Value("path") },
    Spec { long: "send", short: None, kind: ArgKind::Value("socket") },
];

fn find_long(name: &str) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.long == name)
}
fn find_short(c: char) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.short == Some(c))
}

pub fn parse(argv: &[String]) -> Result<Args, CliError> {
    let bin_name = argv
        .first()
        .map(|s| {
            std::path::Path::new(s)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| s.clone())
        })
        .unwrap_or_else(|| "broot".to_string());
    let usage = |ctx: &str| format!("Usage: {} {} [ROOT]", bin_name, ctx);
    let mut args = Args::default();
    let mut i = 1;
    let mut only_positional = false;
    let mut root_set = false;
    while i < argv.len() {
        let a = &argv[i];
        i += 1;
        if only_positional || a == "-" || !a.starts_with('-') {
            if root_set {
                return Err(CliError {
                    message: format!(
                        "error: unexpected argument '{}' found\n\n{}",
                        a,
                        usage("[OPTIONS]")
                    ),
                });
            }
            args.root = Some(PathBuf::from(a));
            root_set = true;
            continue;
        }
        if a == "--" {
            only_positional = true;
            continue;
        }
        if let Some(long) = a.strip_prefix("--") {
            let (name, inline_value) = match long.find('=') {
                Some(p) => (&long[..p], Some(long[p + 1..].to_string())),
                None => (long, None),
            };
            let spec = match find_long(name) {
                Some(s) => s,
                None => {
                    return Err(CliError {
                        message: format!(
                            "error: unexpected argument '--{}' found\n\n  tip: to pass '--{}' as a value, use '-- --{}'\n\n{}",
                            name, name, name,
                            usage("[OPTIONS]")
                        ),
                    });
                }
            };
            match &spec.kind {
                ArgKind::Flag => {
                    if let Some(v) = inline_value {
                        return Err(CliError {
                            message: format!(
                                "error: unexpected value '{}' for '--{}' found; no more were expected\n\n{}",
                                v,
                                spec.long,
                                usage(&format!("--{}", spec.long))
                            ),
                        });
                    }
                    set_flag(&mut args, spec.long);
                }
                ArgKind::Value(vname) => {
                    let value = match inline_value {
                        Some(v) => v,
                        None => {
                            if i < argv.len() && !(argv[i].starts_with('-') && argv[i].len() > 1) {
                                let v = argv[i].clone();
                                i += 1;
                                v
                            } else {
                                return Err(CliError {
                                    message: format!(
                                        "error: a value is required for '--{} <{}>' but none was supplied",
                                        spec.long, vname
                                    ),
                                });
                            }
                        }
                    };
                    set_value(&mut args, spec.long, vname, value)?;
                }
            }
            continue;
        }
        // short flags cluster
        let chars: Vec<char> = a[1..].chars().collect();
        let mut j = 0;
        while j < chars.len() {
            let c = chars[j];
            j += 1;
            let spec = match find_short(c) {
                Some(s) => s,
                None => {
                    return Err(CliError {
                        message: format!(
                            "error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\n{}",
                            c, c, c,
                            usage("[OPTIONS]")
                        ),
                    });
                }
            };
            match &spec.kind {
                ArgKind::Flag => set_flag(&mut args, spec.long),
                ArgKind::Value(vname) => {
                    let rest: String = chars[j..].iter().collect();
                    let value = if !rest.is_empty() {
                        let r = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                        j = chars.len();
                        r
                    } else if i < argv.len() && !(argv[i].starts_with('-') && argv[i].len() > 1) {
                        let v = argv[i].clone();
                        i += 1;
                        v
                    } else {
                        return Err(CliError {
                            message: format!(
                                "error: a value is required for '--{} <{}>' but none was supplied",
                                spec.long, vname
                            ),
                        });
                    };
                    set_value(&mut args, spec.long, vname, value)?;
                }
            }
        }
    }
    Ok(args)
}

fn set_flag(args: &mut Args, long: &str) {
    match long {
        "help" => args.help = true,
        "version" => args.version = true,
        "dates" => args.dates = true,
        "no-dates" => args.no_dates = true,
        "only-folders" => args.only_folders = true,
        "no-only-folders" => args.no_only_folders = true,
        "show-root-fs" => args.show_root_fs = true,
        "show-git-info" => args.show_git_info = true,
        "no-show-git-info" => args.no_show_git_info = true,
        "git-status" => args.git_status = true,
        "hidden" => args.hidden = true,
        "no-hidden" => args.no_hidden = true,
        "git-ignored" => args.git_ignored = true,
        "no-git-ignored" => args.no_git_ignored = true,
        "permissions" => args.permissions = true,
        "no-permissions" => args.no_permissions = true,
        "sizes" => args.sizes = true,
        "no-sizes" => args.no_sizes = true,
        "sort-by-count" => args.sort_by_count = true,
        "sort-by-date" => args.sort_by_date = true,
        "sort-by-size" => args.sort_by_size = true,
        "sort-by-type" => args.sort_by_type = true,
        "no-tree" => args.no_tree = true,
        "tree" => args.tree = true,
        "sort-by-type-dirs-first" => args.sort_by_type_dirs_first = true,
        "sort-by-type-dirs-last" => args.sort_by_type_dirs_last = true,
        "no-sort" => args.no_sort = true,
        "whale-spotting" => args.whale_spotting = true,
        "no-whale-spotting" => args.no_whale_spotting = true,
        "trim-root" => args.trim_root = true,
        "no-trim-root" => args.no_trim_root = true,
        "install" => args.install = true,
        "listen-auto" => args.listen_auto = true,
        "get-root" => args.get_root = true,
        _ => {}
    }
}

fn set_value(args: &mut Args, long: &str, vname: &str, value: String) -> Result<(), CliError> {
    match long {
        "conf" => args.conf = Some(value),
        "max-depth" => match value.parse::<usize>() {
            Ok(v) => args.max_depth = Some(v),
            Err(e) => {
                return Err(CliError {
                    message: format!(
                        "error: invalid value '{}' for '--{} <{}>': {}",
                        value, long, vname, e
                    ),
                })
            }
        },
        "outcmd" => args.outcmd = Some(PathBuf::from(value)),
        "verb-output" => args.verb_output = Some(PathBuf::from(value)),
        "cmd" => args.cmd = Some(value),
        "color" => {
            if !["auto", "yes", "no"].contains(&value.as_str()) {
                return Err(CliError {
                    message: format!(
                        "error: invalid value '{}' for '--color <color>'\n  [possible values: auto, yes, no]",
                        value
                    ),
                });
            }
            args.color = Some(value);
        }
        "height" => match value.parse::<u16>() {
            Ok(v) => args.height = Some(v),
            Err(e) => {
                return Err(CliError {
                    message: format!(
                        "error: invalid value '{}' for '--height <height>': {}",
                        value, e
                    ),
                })
            }
        },
        "set-install-state" => {
            if !["undefined", "refused", "installed"].contains(&value.as_str()) {
                return Err(CliError {
                    message: format!(
                        "error: invalid value '{}' for '--set-install-state <state>'\n  [possible values: undefined, refused, installed]",
                        value
                    ),
                });
            }
            args.set_install_state = Some(value);
        }
        "print-shell-function" => args.print_shell_function = Some(value),
        "listen" => args.listen = Some(value),
        "write-default-conf" => args.write_default_conf = Some(PathBuf::from(value)),
        "send" => args.send = Some(value),
        _ => {}
    }
    Ok(())
}
EOF
echo done"}

