//! A small Hjson parser (superset of JSON with comments, quoteless strings, optional commas)

use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

impl Value {
    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Object(entries) => entries.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::String(s) => Some(s),
            _ => None,
        }
    }
    /// string representation of scalar values (strings, numbers, bools)
    pub fn to_string_value(&self) -> Option<String> {
        match self {
            Value::String(s) => Some(s.clone()),
            Value::Number(n) => {
                if n.fract() == 0.0 {
                    Some(format!("{}", *n as i64))
                } else {
                    Some(format!("{}", n))
                }
            }
            Value::Bool(b) => Some(b.to_string()),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            Value::String(s) => match s.as_str() {
                "true" | "yes" => Some(true),
                "false" | "no" => Some(false),
                _ => None,
            },
            _ => None,
        }
    }
    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Number(n) => Some(*n),
            Value::String(s) => s.trim().parse().ok(),
            _ => None,
        }
    }
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Array(a) => Some(a),
            _ => None,
        }
    }
    pub fn as_object(&self) -> Option<&Vec<(String, Value)>> {
        match self {
            Value::Object(o) => Some(o),
            _ => None,
        }
    }
    pub fn to_map(&self) -> BTreeMap<String, Value> {
        let mut m = BTreeMap::new();
        if let Value::Object(o) = self {
            for (k, v) in o {
                m.insert(k.clone(), v.clone());
            }
        }
        m
    }
}

pub struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    _src: &'a str,
}

#[derive(Debug)]
pub struct ParseError {
    pub message: String,
    pub line: usize,
    pub col: usize,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} at line {} col {}", self.message, self.line, self.col)
    }
}

type PResult<T> = Result<T, ParseError>;

pub fn parse(src: &str) -> PResult<Value> {
    let mut p = Parser {
        chars: src.chars().collect(),
        pos: 0,
        _src: src,
    };
    p.skip_ws_and_comments();
    let v = match p.peek() {
        Some('{') => p.parse_object(true)?,
        Some('[') => p.parse_array()?,
        None => Value::Object(vec![]),
        _ => p.parse_object(false)?,
    };
    p.skip_ws_and_comments();
    if p.pos < p.chars.len() {
        return Err(p.error("unexpected trailing content"));
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }
    fn error(&self, msg: &str) -> ParseError {
        let mut line = 1;
        let mut col = 1;
        for (i, c) in self.chars.iter().enumerate() {
            if i >= self.pos {
                break;
            }
            if *c == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        ParseError {
            message: msg.to_string(),
            line,
            col,
        }
    }
    fn skip_ws_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => self.pos += 1,
                Some('#') => self.skip_line(),
                Some('/') if self.peek_at(1) == Some('/') => self.skip_line(),
                Some('/') if self.peek_at(1) == Some('*') => {
                    self.pos += 2;
                    while self.pos < self.chars.len() {
                        if self.peek() == Some('*') && self.peek_at(1) == Some('/') {
                            self.pos += 2;
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => break,
            }
        }
    }
    /// skip whitespace but not newlines, and no comments
    fn skip_inline_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }
    fn skip_line(&mut self) {
        while let Some(c) = self.peek() {
            self.pos += 1;
            if c == '\n' {
                break;
            }
        }
    }
    fn parse_object(&mut self, braced: bool) -> PResult<Value> {
        if braced {
            self.pos += 1; // {
        }
        let mut entries = Vec::new();
        loop {
            self.skip_ws_and_comments();
            match self.peek() {
                None => {
                    if braced {
                        return Err(self.error("unterminated object"));
                    }
                    break;
                }
                Some('}') => {
                    if braced {
                        self.pos += 1;
                        break;
                    } else {
                        return Err(self.error("unexpected '}'"));
                    }
                }
                Some(',') => {
                    self.pos += 1;
                    continue;
                }
                _ => {}
            }
            let key = self.parse_key()?;
            self.skip_ws_and_comments();
            if self.peek() != Some(':') {
                return Err(self.error("expected ':'"));
            }
            self.pos += 1;
            self.skip_ws_and_comments();
            let value = self.parse_value()?;
            entries.push((key, value));
            // optional comma
            self.skip_inline_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            }
        }
        Ok(Value::Object(entries))
    }
    fn parse_key(&mut self) -> PResult<String> {
        match self.peek() {
            Some('"') | Some('\'') => self.parse_quoted_string(),
            _ => {
                let mut key = String::new();
                while let Some(c) = self.peek() {
                    if c.is_whitespace() || ",:[]{}\"'".contains(c) {
                        break;
                    }
                    key.push(c);
                    self.pos += 1;
                }
                if key.is_empty() {
                    return Err(self.error("expected a key"));
                }
                Ok(key)
            }
        }
    }
    fn parse_array(&mut self) -> PResult<Value> {
        self.pos += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws_and_comments();
            match self.peek() {
                None => return Err(self.error("unterminated array")),
                Some(']') => {
                    self.pos += 1;
                    break;
                }
                Some(',') => {
                    self.pos += 1;
                    continue;
                }
                _ => {}
            }
            let v = self.parse_value()?;
            items.push(v);
            self.skip_inline_ws();
            if self.peek() == Some(',') {
                self.pos += 1;
            }
        }
        Ok(Value::Array(items))
    }
    fn parse_value(&mut self) -> PResult<Value> {
        match self.peek() {
            None => Err(self.error("expected a value")),
            Some('{') => self.parse_object(true),
            Some('[') => self.parse_array(),
            Some('\'') if self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') => {
                self.parse_multiline_string()
            }
            Some('"') | Some('\'') => Ok(Value::String(self.parse_quoted_string()?)),
            _ => self.parse_quoteless(),
        }
    }
    fn parse_quoted_string(&mut self) -> PResult<String> {
        let quote = self.peek().unwrap();
        self.pos += 1;
        let mut s = String::new();
        loop {
            match self.peek() {
                None => return Err(self.error("unterminated string")),
                Some(c) if c == quote => {
                    self.pos += 1;
                    break;
                }
                Some('\\') => {
                    self.pos += 1;
                    match self.peek() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{8}'),
                        Some('f') => s.push('\u{c}'),
                        Some('/') => s.push('/'),
                        Some('\\') => s.push('\\'),
                        Some('"') => s.push('"'),
                        Some('\'') => s.push('\''),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                self.pos += 1;
                                let d = self
                                    .peek()
                                    .and_then(|c| c.to_digit(16))
                                    .ok_or_else(|| self.error("bad unicode escape"))?;
                                code = code * 16 + d;
                            }
                            if let Some(c) = char::from_u32(code) {
                                s.push(c);
                            }
                        }
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return Err(self.error("unterminated string")),
                    }
                    self.pos += 1;
                }
                Some(c) => {
                    s.push(c);
                    self.pos += 1;
                }
            }
        }
        Ok(s)
    }
    fn parse_multiline_string(&mut self) -> PResult<Value> {
        // compute indentation of the opening line
        let mut indent = 0;
        let mut i = self.pos;
        while i > 0 && self.chars[i - 1] != '\n' {
            i -= 1;
        }
        while i < self.pos && (self.chars[i] == ' ' || self.chars[i] == '\t') {
            indent += 1;
            i += 1;
        }
        self.pos += 3;
        // skip to end of line
        self.skip_inline_ws();
        if self.peek() == Some('\n') {
            self.pos += 1;
        }
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        let mut at_line_start = true;
        let mut skipped = 0;
        loop {
            match self.peek() {
                None => return Err(self.error("unterminated multiline string")),
                Some('\'') if self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') => {
                    self.pos += 3;
                    lines.push(cur);
                    break;
                }
                Some('\n') => {
                    lines.push(std::mem::take(&mut cur));
                    at_line_start = true;
                    skipped = 0;
                    self.pos += 1;
                }
                Some(c) => {
                    if at_line_start && (c == ' ' || c == '\t') && skipped < indent {
                        skipped += 1;
                        self.pos += 1;
                        continue;
                    }
                    at_line_start = false;
                    cur.push(c);
                    self.pos += 1;
                }
            }
        }
        // last line (containing the closing quotes) : if only whitespace, drop it
        if let Some(last) = lines.last() {
            if last.trim().is_empty() {
                lines.pop();
            }
        }
        Ok(Value::String(lines.join("\n")))
    }
    fn parse_quoteless(&mut self) -> PResult<Value> {
        // read to end of line
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c == '\n' || c == '\r' {
                break;
            }
            self.pos += 1;
        }
        let raw: String = self.chars[start..self.pos].iter().collect();
        let text = raw.trim();
        // a possible non-string value is terminated by , or ] or } or comment
        let mut candidate_end = text.len();
        for (i, c) in text.char_indices() {
            if c == ',' || c == ']' || c == '}' || c == '#' {
                candidate_end = i;
                break;
            }
            if c == '/' && text[i..].starts_with("//") {
                candidate_end = i;
                break;
            }
        }
        let candidate = text[..candidate_end].trim();
        let scalar = match candidate {
            "true" => Some(Value::Bool(true)),
            "false" => Some(Value::Bool(false)),
            "null" => Some(Value::Null),
            _ => {
                if is_json_number(candidate) {
                    candidate.parse::<f64>().ok().map(Value::Number)
                } else {
                    None
                }
            }
        };
        if let Some(v) = scalar {
            if candidate_end < text.len() {
                // put back the remaining chars (,] etc.)
                let consumed = raw.find(candidate).unwrap_or(0) + candidate.len();
                self.pos = start + consumed;
            }
            return Ok(v);
        }
        // quoteless string: may need to stop at ] or } when inside an array or object on same line ?
        // Hjson spec: quoteless strings run to end of line, but a trailing ',' is not significant
        // We handle the common case `[ a, b ]` written on one line: not supported by Hjson either.
        let mut s = text.to_string();
        // Hjson: a quoteless string can't be followed by a comment but we strip nothing.
        if s.ends_with(',') && !s.ends_with("\\,") {
            // not part of spec; keep as is
        }
        // handle `}` or `]` ending the line when the value is on the same line as the closing bracket
        // e.g. `{ show: always }` -> value "always" then '}' on same line
        if let Some(idx) = find_unquoted_closer(&s) {
            let before = s[..idx].trim_end().to_string();
            let consumed = raw.find(&before).unwrap_or(0) + before.len();
            self.pos = start + consumed;
            s = before;
        }
        Ok(Value::String(s))
    }
}

fn find_unquoted_closer(s: &str) -> Option<usize> {
    // find a '}' or ']' or ',' that terminates a value written on the same line as its container end
    // only consider when followed by only whitespace/closers/comma
    let bytes: Vec<char> = s.chars().collect();
    for (i, c) in bytes.iter().enumerate() {
        if *c == '}' || *c == ']' || *c == ',' {
            let rest: String = bytes[i..].iter().collect();
            if rest.chars().all(|c| c == '}' || c == ']' || c == ',' || c.is_whitespace()) {
                let byte_idx = s.char_indices().nth(i).map(|(b, _)| b).unwrap_or(s.len());
                return Some(byte_idx);
            }
        }
    }
    None
}

fn is_json_number(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let mut chars = s.chars().peekable();
    if chars.peek() == Some(&'-') {
        chars.next();
    }
    let mut digits = 0;
    while let Some(c) = chars.peek() {
        if c.is_ascii_digit() {
            digits += 1;
            chars.next();
        } else {
            break;
        }
    }
    if digits == 0 {
        return false;
    }
    if chars.peek() == Some(&'.') {
        chars.next();
        let mut d = 0;
        while let Some(c) = chars.peek() {
            if c.is_ascii_digit() {
                d += 1;
                chars.next();
            } else {
                break;
            }
        }
        if d == 0 {
            return false;
        }
    }
    if matches!(chars.peek(), Some('e') | Some('E')) {
        chars.next();
        if matches!(chars.peek(), Some('+') | Some('-')) {
            chars.next();
        }
        let mut d = 0;
        while let Some(c) = chars.peek() {
            if c.is_ascii_digit() {
                d += 1;
                chars.next();
            } else {
                break;
            }
        }
        if d == 0 {
            return false;
        }
    }
    chars.next().is_none()
}
