//! Skin: colors and styles of the screen parts

use crossterm::style::{Attribute, Color};
use std::collections::HashMap;

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub attrs: Vec<Attribute>,
}

impl Style {
    pub fn new(fg: Option<Color>, bg: Option<Color>) -> Self {
        Style { fg, bg, attrs: vec![] }
    }
    pub fn with_attr(mut self, a: Attribute) -> Self {
        self.attrs.push(a);
        self
    }
    pub fn has_attr(&self, a: Attribute) -> bool {
        self.attrs.contains(&a)
    }
    /// style composition: self's defined parts over the other's
    pub fn over(&self, base: &Style) -> Style {
        Style {
            fg: self.fg.or(base.fg),
            bg: self.bg.or(base.bg),
            attrs: {
                let mut v = base.attrs.clone();
                for a in &self.attrs {
                    if !v.contains(a) {
                        v.push(*a);
                    }
                }
                v
            },
        }
    }
}

#[derive(Debug, Clone)]
pub struct StyleEntry {
    pub focused: Style,
    pub unfocused: Style,
}

impl StyleEntry {
    pub fn get(&self, focused: bool) -> &Style {
        if focused {
            &self.focused
        } else {
            &self.unfocused
        }
    }
}

pub fn parse_color(s: &str) -> Result<Option<Color>, String> {
    let s = s.trim();
    let lower = s.to_lowercase();
    if lower == "none" {
        return Ok(None);
    }
    if let Some(inner) = lower.strip_prefix("gray(").or_else(|| lower.strip_prefix("grey(")) {
        let inner = inner.trim_end_matches(')').trim();
        let level: u8 = inner.parse().map_err(|_| format!("bad gray level: {}", s))?;
        if level > 23 {
            return Err(format!("gray level too high: {}", level));
        }
        return Ok(Some(Color::AnsiValue(232 + level)));
    }
    if let Some(inner) = lower.strip_prefix("ansi(") {
        let inner = inner.trim_end_matches(')').trim();
        let v: u8 = inner.parse().map_err(|_| format!("bad ansi value: {}", s))?;
        return Ok(Some(Color::AnsiValue(v)));
    }
    if let Some(inner) = lower.strip_prefix("rgb(") {
        let inner = inner.trim_end_matches(')');
        let parts: Vec<&str> = inner.split(',').map(|p| p.trim()).collect();
        if parts.len() != 3 {
            return Err(format!("bad rgb color: {}", s));
        }
        let r: u8 = parts[0].parse().map_err(|_| format!("bad rgb: {}", s))?;
        let g: u8 = parts[1].parse().map_err(|_| format!("bad rgb: {}", s))?;
        let b: u8 = parts[2].parse().map_err(|_| format!("bad rgb: {}", s))?;
        return Ok(Some(Color::Rgb { r, g, b }));
    }
    if let Some(hex) = lower.strip_prefix('#') {
        let hex = hex.trim();
        let (r, g, b) = match hex.len() {
            3 => {
                let v: Vec<u8> = hex
                    .chars()
                    .map(|c| c.to_digit(16).map(|d| (d * 17) as u8))
                    .collect::<Option<Vec<u8>>>()
                    .ok_or_else(|| format!("bad hex color: {}", s))?;
                (v[0], v[1], v[2])
            }
            6 => {
                let p = |i: usize| u8::from_str_radix(&hex[i..i + 2], 16).map_err(|_| format!("bad hex color: {}", s));
                (p(0)?, p(2)?, p(4)?)
            }
            _ => return Err(format!("bad hex color: {}", s)),
        };
        return Ok(Some(Color::Rgb { r, g, b }));
    }
    let c = match lower.as_str() {
        "black" => Color::Black,
        "darkgrey" | "darkgray" => Color::DarkGrey,
        "red" => Color::Red,
        "darkred" => Color::DarkRed,
        "green" => Color::Green,
        "darkgreen" => Color::DarkGreen,
        "yellow" => Color::Yellow,
        "darkyellow" => Color::DarkYellow,
        "blue" => Color::Blue,
        "darkblue" => Color::DarkBlue,
        "magenta" => Color::Magenta,
        "darkmagenta" => Color::DarkMagenta,
        "cyan" => Color::Cyan,
        "darkcyan" => Color::DarkCyan,
        "white" => Color::White,
        "grey" | "gray" => Color::Grey,
        "reset" => Color::Reset,
        _ => return Err(format!("unknown color: {}", s)),
    };
    Ok(Some(c))
}

fn parse_attr(s: &str) -> Result<Attribute, String> {
    Ok(match s.to_lowercase().as_str() {
        "bold" => Attribute::Bold,
        "crossedout" => Attribute::CrossedOut,
        "dim" => Attribute::Dim,
        "italic" => Attribute::Italic,
        "overlined" => Attribute::OverLined,
        "reverse" => Attribute::Reverse,
        "underlined" => Attribute::Underlined,
        "slowblink" => Attribute::SlowBlink,
        "rapidblink" => Attribute::RapidBlink,
        _ => return Err(format!("unknown attribute: {}", s)),
    })
}

/// parse "fg bg attr attr" (the tokens may be fewer)
pub fn parse_style(s: &str) -> Result<Style, String> {
    let tokens = tokenize(s);
    let mut style = Style::default();
    let mut idx = 0;
    if idx < tokens.len() {
        style.fg = parse_color(&tokens[idx])?;
        idx += 1;
    }
    if idx < tokens.len() {
        // second token: a color (or an attribute if the entry is shortened)
        match parse_color(&tokens[idx]) {
            Ok(c) => {
                style.bg = c;
                idx += 1;
            }
            Err(_) => {}
        }
    }
    while idx < tokens.len() {
        style.attrs.push(parse_attr(&tokens[idx])?);
        idx += 1;
    }
    Ok(style)
}

fn tokenize(s: &str) -> Vec<String> {
    // split on whitespace but keep parenthesis groups together (rgb(1, 2, 3))
    let mut tokens = Vec::new();
    let mut cur = String::new();
    let mut depth = 0;
    for c in s.chars() {
        match c {
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                cur.push(c);
            }
            c if c.is_whitespace() && depth <= 0 => {
                if !cur.is_empty() {
                    tokens.push(std::mem::take(&mut cur));
                }
            }
            _ => cur.push(c),
        }
    }
    if !cur.is_empty() {
        tokens.push(cur);
    }
    tokens
}

pub fn parse_entry(s: &str) -> Result<StyleEntry, String> {
    let mut parts = s.splitn(2, '/');
    let focused = parse_style(parts.next().unwrap_or(""))?;
    let unfocused = match parts.next() {
        Some(u) => parse_style(u)?,
        None => focused.clone(),
    };
    Ok(StyleEntry { focused, unfocused })
}

