    }

    fn read_file(&mut self, path: &Path, depth: usize) {
        if depth > 10 {
            return;
        }
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                self.errors.push(format!("{}: {}", path.display(), e));
                return;
            }
        };
        self.files.push(path.to_path_buf());
        let value = match hjson::parse(&content) {
            Ok(v) => v,
            Err(e) => {
                self.errors.push(format!("Invalid configuration file {}: {}", path.display(), e));
                return;
            }
        };
        self.apply_value(&value, path, depth);
    }

    fn apply_value(&mut self, v: &Value, path: &Path, depth: usize) {
        if let Some(s) = v.get("default_flags").and_then(|v| v.to_string_value()) {
            self.default_flags = Some(s);
        }
        if let Some(b) = v.get("show_selection_mark").and_then(|v| v.as_bool()) {
