                            "hide" => sp.show = Some("never".to_string()),
                            "enter" => sp.list = Some("always".to_string()),
                            _ => {}
                        }
                    }
                    Value::Object(_) => {
                        sp.show = sv.get("show").and_then(|x| x.to_string_value());
                        sp.list = sv.get("list").and_then(|x| x.to_string_value());
                        sp.sum = sv.get("sum").and_then(|x| x.to_string_value());
                    }
                    _ => {}
                }
                self.special_paths.push(sp);
            }
        }
        if let Some(o) = v.get("search_modes").and_then(|v| v.as_object()) {
            for (k, sv) in o {
                if let Some(s) = sv.to_string_value() {
                    self.search_modes.insert(k.clone(), s);
                }
            }
        }
        if let Some(o) = v.get("ext_colors").and_then(|v| v.as_object()) {
            for (k, sv) in o {
