fn parse_verb_conf(v: &Value) -> Option<VerbConf> {
    let obj = v.as_object()?;
    let _ = obj;
    let mut vc = VerbConf::default();
    vc.name = v.get("name").and_then(|x| x.to_string_value());
    vc.invocation = v.get("invocation").and_then(|x| x.to_string_value());
    vc.internal = v.get("internal").and_then(|x| x.to_string_value());
    match v.get("external") {
        Some(Value::Array(a)) => {
            vc.external = Some(a.iter().filter_map(|x| x.to_string_value()).collect());
        }
        Some(Value::String(s)) => {
            vc.external = Some(vec![s.clone()]);
            vc.external_is_string = true;
        }
        _ => {}
    }
    vc.cmd = v.get("cmd").and_then(|x| x.to_string_value());
    match v.get("execution") {
        Some(Value::Array(a)) => {
            let parts: Vec<String> = a.iter().filter_map(|x| x.to_string_value()).collect();
            vc.execution = Some(parts.join(" "));
            vc.external = Some(parts);
        }
        Some(Value::String(s)) => vc.execution = Some(s.clone()),
        _ => {}
    }
    if let Some(k) = v.get("key").and_then(|x| x.to_string_value()) {
        vc.keys.push(k);
    }
    if let Some(a) = v.get("keys").and_then(|x| x.as_array()) {
        for k in a {
            if let Some(s) = k.to_string_value() {
                vc.keys.push(s);
            }
        }
    }
    vc.shortcut = v.get("shortcut").and_then(|x| x.to_string_value());
    vc.leave_broot = v.get("leave_broot").and_then(|x| x.as_bool());
    vc.from_shell = v.get("from_shell").and_then(|x| x.as_bool());
    vc.apply_to = v.get("apply_to").and_then(|x| x.to_string_value());
    vc.extensions = v
        .get("extensions")
        .and_then(|x| x.as_array())
        .map(|a| a.iter().filter_map(|x| x.to_string_value()).collect());
    vc.set_working_dir = v.get("set_working_dir").and_then(|x| x.as_bool());
    vc.working_dir = v.get("working_dir").and_then(|x| x.to_string_value());
    vc.auto_exec = v.get("auto_exec").and_then(|x| x.as_bool());
    vc.switch_terminal = v.get("switch_terminal").and_then(|x| x.as_bool());
    vc.description = v.get("description").and_then(|x| x.to_string_value());
    vc.panels = v
        .get("panels")
        .and_then(|x| x.as_array())
        .map(|a| a.iter().filter_map(|x| x.to_string_value()).collect());
    vc.cmd_separator = v.get("cmd_separator").and_then(|x| x.to_string_value());
    Some(vc)
}
