//! Search patterns: fuzzy, regex, exact, tokens, content, and composites

use regex::Regex;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SearchKind {
    Fuzzy,
    Regex,
    Exact,
    Tokens,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SearchObject {
    Name,
    Path,
    Content,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct SearchMode {
    pub kind: SearchKind,
    pub object: SearchObject,
}

impl SearchMode {
    pub const FUZZY_PATH: SearchMode = SearchMode { kind: SearchKind::Fuzzy, object: SearchObject::Path };
    pub const REGEX_NAME: SearchMode = SearchMode { kind: SearchKind::Regex, object: SearchObject::Name };

    /// parse a mode prefix (the letters before the slash)
    pub fn from_prefix(prefix: &str) -> Option<SearchMode> {
        let mut kind: Option<SearchKind> = None;
        let mut object: Option<SearchObject> = None;
        for c in prefix.chars() {
            match c {
                'f' => kind = Some(SearchKind::Fuzzy),
                'r' => kind = Some(SearchKind::Regex),
                'e' => kind = Some(SearchKind::Exact),
                't' => kind = Some(SearchKind::Tokens),
                'n' => object = Some(SearchObject::Name),
                'p' => object = Some(SearchObject::Path),
                'c' => object = Some(SearchObject::Content),
                _ => return None,
            }
        }
        Some(match (kind, object) {
            (None, None) => SearchMode::REGEX_NAME,
            (Some(k), None) => SearchMode {
                kind: k,
                object: if k == SearchKind::Tokens { SearchObject::Path } else { SearchObject::Name },
            },
            (None, Some(o)) => SearchMode {
                kind: if o == SearchObject::Content { SearchKind::Exact } else { SearchKind::Fuzzy },
                object: o,
            },
            (Some(k), Some(o)) => SearchMode { kind: k, object: o },
        })
    }

    /// the name used in the help and config ("fuzzy name", etc.)
    pub fn name(self) -> String {
        format!("{} {}", match self.kind {
            SearchKind::Fuzzy => "fuzzy",
            SearchKind::Regex => "regex",
            SearchKind::Exact => "exact",
            SearchKind::Tokens => "tokens",
        }, match self.object {
            SearchObject::Name => "name",
            SearchObject::Path => "path",
            SearchObject::Content => "content",
        })
    }

    pub fn from_name(s: &str) -> Option<SearchMode> {
        let s = s.trim().to_lowercase();
        let mut parts = s.split_whitespace();
        let k = match parts.next()? {
            "fuzzy" => SearchKind::Fuzzy,
            "regex" => SearchKind::Regex,
            "exact" => SearchKind::Exact,
            "tokens" => SearchKind::Tokens,
            _ => return None,
        };
        let o = match parts.next()? {
            "name" => SearchObject::Name,
            "path" => SearchObject::Path,
            "content" => SearchObject::Content,
            _ => return None,
        };
        Some(SearchMode { kind: k, object: o })
    }
}

/// a match: score and positions of matching chars
#[derive(Debug, Clone, PartialEq)]
pub struct NameMatch {
    pub score: i32,
    pub pos: Vec<usize>, // indexes of matching chars in the candidate
}

/// simple diacritics removal + lowercasing
pub fn lower_lay_char(c: char) -> char {
    let c = match c {
        'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' | 'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => 'a',
        'Ç' | 'ç' => 'c',
        'È' | 'É' | 'Ê' | 'Ë' | 'è' | 'é' | 'ê' | 'ë' => 'e',
        'Ì' | 'Í' | 'Î' | 'Ï' | 'ì' | 'í' | 'î' | 'ï' => 'i',
        'Ñ' | 'ñ' => 'n',
        'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'Ø' => 'o',
        'Ù' | 'Ú' | 'Û' | 'Ü' | 'ù' | 'ú' | 'û' | 'ü' => 'u',
        'Ý' | 'ý' | 'ÿ' => 'y',
        _ => c,
    };
    c.to_lowercase().next().unwrap_or(c)
}

// weights used in match score computing
const BONUS_MATCH: i32 = 50_000;
const BONUS_EXACT: i32 = 1_000;
const BONUS_START: i32 = 10;
const BONUS_START_WORD: i32 = 5;
const BONUS_CANDIDATE_LENGTH: i32 = -1; // per char
const BONUS_LENGTH: i32 = -10; // per char of length of the match
const BONUS_NB_HOLES: i32 = -30;
const BONUS_SINGLED_CHAR: i32 = -15;

fn is_word_separator(c: char) -> bool {
    matches!(c, '_' | ' ' | '-')
}

#[derive(Debug, Clone)]
pub struct FuzzyPattern {
    chars: Vec<char>,
    max_nb_holes: usize,
}

impl FuzzyPattern {
    pub fn new(pat: &str) -> FuzzyPattern {
        let chars: Vec<char> = pat.chars().map(lower_lay_char).collect();
        let max_nb_holes = match chars.len() {
            0 | 1 => 0,
            2 => 1,
            n => std::cmp::max(2, n / 2),
        };
        FuzzyPattern { chars, max_nb_holes }
    }
    pub fn is_empty(&self) -> bool {
        self.chars.is_empty()
    }
    fn match_starting_at_index(&self, cand_chars: &[char], start_idx: usize) -> Option<NameMatch> {
        if cand_chars[start_idx] != self.chars[0] {
            return None;
        }
        let mut pos: Vec<usize> = Vec::with_capacity(self.chars.len());
        let mut nb_holes = 0;
        let mut nb_singled_chars = 0;
        let mut cand_idx = start_idx;
        pos.push(cand_idx);
        let mut previous_was_hole = false;
        for pat_idx in 1..self.chars.len() {
            let pat_char = self.chars[pat_idx];
            cand_idx += 1;
            if cand_idx >= cand_chars.len() {
                return None;
            }
            if cand_chars[cand_idx] != pat_char {
                // a hole
                nb_holes += 1;
                if nb_holes > self.max_nb_holes {
                    return None;
                }
                loop {
                    cand_idx += 1;
                    if cand_idx >= cand_chars.len() {
                        return None;
                    }
                    if cand_chars[cand_idx] == pat_char {
                        break;
                    }
                }
                if previous_was_hole && pat_idx > 1 {
                    // the previous matched char was isolated (hole before and after)
                    nb_singled_chars += 1;
                }
                previous_was_hole = true;
            } else {
                previous_was_hole = false;
            }
            pos.push(cand_idx);
        }
        let mut score = BONUS_MATCH;
        score += BONUS_CANDIDATE_LENGTH * (cand_chars.len() as i32);
        score += BONUS_SINGLED_CHAR * (nb_singled_chars as i32);
        score += BONUS_NB_HOLES * (nb_holes as i32);
        let match_len = (cand_idx - start_idx) as i32 + 1;
        score += BONUS_LENGTH * match_len;
        if start_idx == 0 {
            score += BONUS_START + BONUS_START_WORD;
            if cand_chars.len() == self.chars.len() {
                score += BONUS_EXACT;
            }
        } else {
            let previous = cand_chars[start_idx - 1];
            if is_word_separator(previous) {
                score += BONUS_START_WORD;
                if cand_chars.len() - start_idx == self.chars.len() {
                    score += BONUS_EXACT;
                }
            }
        }
        Some(NameMatch { score, pos })
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        if self.chars.is_empty() {
            return None;
        }
        let cand_chars: Vec<char> = candidate.chars().map(lower_lay_char).collect();
        if cand_chars.len() < self.chars.len() {
            return None;
        }
        let mut best: Option<NameMatch> = None;
        let n = cand_chars.len() - self.chars.len();
        for start_idx in 0..=n {
            if let Some(m) = self.match_starting_at_index(&cand_chars, start_idx) {
                if best.as_ref().map_or(true, |b| m.score > b.score) {
                    best = Some(m);
                }
            }
        }
        best
    }
    pub fn score_of(&self, candidate: &str) -> Option<i32> {
        self.find(candidate).map(|m| m.score)
    }
}

#[derive(Debug, Clone)]
pub struct ExactPattern {
    pub needle: String,
    chars_count: usize,
}

impl ExactPattern {
    pub fn new(pat: &str) -> ExactPattern {
        ExactPattern {
            needle: pat.to_string(),
            chars_count: pat.chars().count(),
        }
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        if self.needle.is_empty() {
            return None;
        }
        let byte_idx = candidate.find(&self.needle)?;
        let char_idx = candidate[..byte_idx].chars().count();
        let pos: Vec<usize> = (char_idx..char_idx + self.chars_count).collect();
        let cand_len = candidate.chars().count() as i32;
        let mut score = BONUS_MATCH + BONUS_CANDIDATE_LENGTH * cand_len + BONUS_LENGTH * (self.chars_count as i32);
        if char_idx == 0 {
            score += BONUS_START + BONUS_START_WORD;
            if cand_len as usize == self.chars_count {
                score += BONUS_EXACT;
            }
        } else {
            let prev = candidate[..byte_idx].chars().last().unwrap();
            if is_word_separator(prev) {
                score += BONUS_START_WORD;
                if cand_len as usize - char_idx == self.chars_count {
                    score += BONUS_EXACT;
                }
            }
        }
        Some(NameMatch { score, pos })
    }
    pub fn score_of(&self, candidate: &str) -> Option<i32> {
        self.find(candidate).map(|m| m.score)
    }
}

#[derive(Debug, Clone)]
pub struct RegexPattern {
    pub rex: Regex,
    pub flags: String,
}

impl RegexPattern {
    pub fn new(pat: &str, flags: &str) -> Result<RegexPattern, String> {
        let mut builder = regex::RegexBuilder::new(pat);
        for c in flags.chars() {
            match c {
                'i' => {
                    builder.case_insensitive(true);
                }
                'm' => {
                    builder.multi_line(true);
                }
                's' => {
                    builder.dot_matches_new_line(true);
                }
                'U' => {
                    builder.swap_greed(true);
                }
                'u' => {
                    builder.unicode(true);
                }
                'x' => {
                    builder.ignore_whitespace(true);
                }
                _ => return Err(format!("unknown regex flag: {}", c)),
            }
        }
        let rex = builder.build().map_err(|e| format!("{}", e))?;
        Ok(RegexPattern { rex, flags: flags.to_string() })
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        let m = self.rex.find(candidate)?;
        let start_char = candidate[..m.start()].chars().count();
        let len_chars = candidate[m.start()..m.end()].chars().count();
        let pos: Vec<usize> = (start_char..start_char + len_chars).collect();
        let score = BONUS_MATCH - (candidate.chars().count() as i32) + if m.start() == 0 { BONUS_START } else { 0 };
        Some(NameMatch { score, pos })
    }
    pub fn score_of(&self, candidate: &str) -> Option<i32> {
        self.find(candidate).map(|m| m.score)
    }
}

#[derive(Debug, Clone)]
pub struct TokensPattern {
    tokens: Vec<Vec<char>>,
}

impl TokensPattern {
    pub fn new(pat: &str) -> TokensPattern {
        let tokens: Vec<Vec<char>> = pat
            .split(',')
            .filter(|t| !t.is_empty())
            .map(|t| t.chars().map(lower_lay_char).collect())
            .collect();
        TokensPattern { tokens }
    }
    pub fn is_empty(&self) -> bool {
        self.tokens.is_empty()
    }
    pub fn find(&self, candidate: &str) -> Option<NameMatch> {
        if self.tokens.is_empty() {
            return None;
        }
        let cand: Vec<char> = candidate.chars().map(lower_lay_char).collect();
        let mut pos: Vec<usize> = Vec::new();
        for token in &self.tokens {
            if token.len() > cand.len() {
                return None;
            }
            let mut found = None;
            for i in 0..=(cand.len() - token.len()) {
                if cand[i..i + token.len()] == token[..] {
                    found = Some(i);
                    break;
                }
            }
            let i = found?;
            for p in i..i + token.len() {
                if !pos.contains(&p) {
                    pos.push(p);
                }
            }
        }
        pos.sort_unstable();
        let score = BONUS_MATCH + BONUS_CANDIDATE_LENGTH * (cand.len() as i32) + BONUS_LENGTH * (pos.len() as i32);
        Some(NameMatch { score, pos })
    }
    pub fn score_of(&self, candidate: &str) -> Option<i32> {
        self.find(candidate).map(|m| m.score)
    }
}

#[derive(Debug, Clone)]
pub enum ContentMatcher {
    Exact(String),
    Regex(Regex),
}

#[derive(Debug, Clone)]
pub struct ContentPattern {
    pub matcher: ContentMatcher,
    pub max_file_size: u64,
    pub display: String,
}

/// result of a content search in a file
#[derive(Debug, Clone)]
pub struct ContentMatch {
    pub extract: String,
    pub needle_start: usize, // char index in extract
    pub needle_end: usize,
}

impl ContentPattern {
    pub fn score_of(&self, path: &Path) -> Option<i32> {
        let found = self.get_match(path)?;
        let _ = found;
        Some(1)
    }
    pub fn is_empty(&self) -> bool {
        match &self.matcher {
            ContentMatcher::Exact(s) => s.is_empty(),
            ContentMatcher::Regex(_) => false,
        }
    }
    /// find the first match in the file (if the file is a reasonable text file)
    pub fn get_match(&self, path: &Path) -> Option<ContentMatch> {
        let md = std::fs::metadata(path).ok()?;
        if !md.is_file() || md.len() > self.max_file_size {
            return None;
        }
        let bytes = std::fs::read(path).ok()?;
        // consider it binary if there's a NUL in the first bytes
        let probe = &bytes[..bytes.len().min(1024)];
        if probe.contains(&0) {
            return None;
        }
        match &self.matcher {
            ContentMatcher::Exact(needle) => {
                if needle.is_empty() {
                    return None;
                }
                let nb = needle.as_bytes();
                let idx = find_bytes(&bytes, nb)?;
                Some(extract_around(&bytes, idx, idx + nb.len()))
            }
            ContentMatcher::Regex(rex) => {
                let text = String::from_utf8_lossy(&bytes);
                let m = rex.find(&text)?;
                // map to byte offsets in lossy text; good enough for extract
                let tb = text.as_bytes();
                Some(extract_around(tb, m.start(), m.end()))
            }
        }
    }
}

fn find_bytes(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || hay.len() < needle.len() {
        return None;
    }
    hay.windows(needle.len()).position(|w| w == needle)
}

fn extract_around(bytes: &[u8], start: usize, end: usize) -> ContentMatch {
    // the extract is the line containing the match, limited in size
    let mut ls = start;
    while ls > 0 && bytes[ls - 1] != b'\n' && start - ls < 40 {
        ls -= 1;
    }
    let mut le = end;
    while le < bytes.len() && bytes[le] != b'\n' && le - end < 60 {
        le += 1;
    }
    let extract_bytes = &bytes[ls..le];
    let extract = String::from_utf8_lossy(extract_bytes).to_string();
    let needle_start = String::from_utf8_lossy(&bytes[ls..start]).chars().count();
    let needle_end = needle_start + String::from_utf8_lossy(&bytes[start..end]).chars().count();
    ContentMatch {
        extract: extract.replace('\t', " ").trim_start().to_string(),
        needle_start: {
            let trimmed = extract.len() - extract.trim_start().len();
            let trimmed_chars = extract[..trimmed].chars().count();
            needle_start.saturating_sub(trimmed_chars)
        },
        needle_end: {
            let trimmed = extract.len() - extract.trim_start().len();
            let trimmed_chars = extract[..trimmed].chars().count();
            needle_end.saturating_sub(trimmed_chars)
        },
    }
}

#[derive(Debug, Clone)]
pub enum PatternOp {
    And,
    Or,
}

#[derive(Debug, Clone)]
pub enum Pattern {
    None,
    Fuzzy(FuzzyPattern, SearchObject),
    Regex(RegexPattern, SearchObject),
    Exact(ExactPattern, SearchObject),
    Tokens(TokensPattern, SearchObject),
    Content(ContentPattern),
    Not(Box<Pattern>),
    Composite(Box<Pattern>, PatternOp, Box<Pattern>),
}

/// what is needed to evaluate a pattern against a file
pub struct Candidate<'a> {
    pub name: &'a str,
    pub subpath: &'a str,
    pub path: &'a Path,
    pub regular_file: bool,
}

impl Pattern {
    pub fn is_some(&self) -> bool {
        !matches!(self, Pattern::None)
    }
    pub fn is_none(&self) -> bool {
        matches!(self, Pattern::None)
    }
    pub fn is_empty(&self) -> bool {
        match self {
            Pattern::None => true,
            Pattern::Fuzzy(f, _) => f.is_empty(),
            Pattern::Tokens(t, _) => t.is_empty(),
            Pattern::Exact(e, _) => e.needle.is_empty(),
            Pattern::Content(c) => c.is_empty(),
            _ => false,
        }
    }
    /// whether the pattern needs the file content
    pub fn has_content_search(&self) -> bool {
        match self {
            Pattern::Content(_) => true,
            Pattern::Not(p) => p.has_content_search(),
            Pattern::Composite(a, _, b) => a.has_content_search() || b.has_content_search(),
            _ => false,
        }
    }
    pub fn has_real_scores(&self) -> bool {
        match self {
            Pattern::None => false,
            Pattern::Fuzzy(..) | Pattern::Tokens(..) | Pattern::Exact(..) | Pattern::Regex(..) => true,
            Pattern::Content(_) => false,
            Pattern::Not(_) => false,
            Pattern::Composite(a, _, b) => a.has_real_scores() || b.has_real_scores(),
        }
    }
    /// the object searched by the first (leftmost) elementary pattern, used for display
    pub fn object(&self) -> Option<SearchObject> {
        match self {
            Pattern::None => None,
            Pattern::Fuzzy(_, o) | Pattern::Regex(_, o) | Pattern::Exact(_, o) | Pattern::Tokens(_, o) => Some(*o),
            Pattern::Content(_) => Some(SearchObject::Content),
            Pattern::Not(p) => p.object(),
            Pattern::Composite(a, _, b) => a.object().or_else(|| b.object()),
        }
    }
    /// whether paths are displayed as subpaths (any elementary pattern on paths)
    pub fn searches_paths(&self) -> bool {
        match self {
            Pattern::None => false,
            Pattern::Fuzzy(_, o) | Pattern::Regex(_, o) | Pattern::Exact(_, o) | Pattern::Tokens(_, o) => *o == SearchObject::Path,
            Pattern::Content(_) => false,
            Pattern::Not(p) => p.searches_paths(),
            Pattern::Composite(a, _, b) => a.searches_paths() || b.searches_paths(),
        }
    }
    pub fn score_of(&self, c: &Candidate) -> Option<i32> {
        match self {
            Pattern::None => Some(0),
            Pattern::Fuzzy(p, o) => p.score_of(obj_str(c, *o)),
            Pattern::Regex(p, o) => p.score_of(obj_str(c, *o)),
            Pattern::Exact(p, o) => p.score_of(obj_str(c, *o)),
            Pattern::Tokens(p, o) => p.score_of(obj_str(c, *o)),
            Pattern::Content(p) => {
                if c.regular_file {
                    p.score_of(c.path)
                } else {
                    None
                }
            }
            Pattern::Not(p) => {
                if p.score_of(c).is_some() {
                    None
                } else {
                    Some(1)
                }
            }
            Pattern::Composite(a, op, b) => match op {
                PatternOp::And => {
                    let sa = a.score_of(c)?;
                    let sb = b.score_of(c)?;
                    Some(sa + sb)
                }
                PatternOp::Or => match (a.score_of(c), b.score_of(c)) {
                    (None, None) => None,
                    (Some(s), None) | (None, Some(s)) => Some(s),
                    (Some(sa), Some(sb)) => Some(sa.max(sb)),
                },
            },
        }
    }
    /// the match on the name or subpath, for highlighting
    pub fn search_string(&self, candidate: &str, object: SearchObject) -> Option<NameMatch> {
        match self {
            Pattern::None => None,
            Pattern::Fuzzy(p, o) if *o == object => p.find(candidate),
            Pattern::Regex(p, o) if *o == object => p.find(candidate),
            Pattern::Exact(p, o) if *o == object => p.find(candidate),
            Pattern::Tokens(p, o) if *o == object => p.find(candidate),
            Pattern::Not(_) => None,
            Pattern::Composite(a, _, b) => a.search_string(candidate, object).or_else(|| b.search_string(candidate, object)),
            _ => None,
        }
    }
    pub fn content_pattern(&self) -> Option<&ContentPattern> {
        match self {
            Pattern::Content(c) => Some(c),
            Pattern::Composite(a, _, b) => a.content_pattern().or_else(|| b.content_pattern()),
            Pattern::Not(_) => None,
            _ => None,
        }
    }
}

fn obj_str<'a>(c: &'a Candidate, o: SearchObject) -> &'a str {
    match o {
        SearchObject::Name => c.name,
        SearchObject::Path => c.subpath,
        SearchObject::Content => c.name,
    }
}

/// An elementary pattern part as written by the user
#[derive(Debug, Clone, PartialEq)]
pub struct PatternPart {
    pub mode_prefix: Option<String>, // None if no slash at all
    pub core: String,
    pub flags: String,
}

#[derive(Debug, Clone, PartialEq)]
pub enum PatternExpr {
    Part(PatternPart),
    Not(Box<PatternExpr>),
    And(Box<PatternExpr>, Box<PatternExpr>),
    Or(Box<PatternExpr>, Box<PatternExpr>),
}

/// the result of parsing the input: a pattern expression and the verb invocation part
#[derive(Debug, Clone, Default)]
pub struct ParsedInput {
    pub pattern_raw: String,
    pub pattern: Option<PatternExpr>,
    pub pattern_error: Option<String>,
    pub verb: Option<VerbInvocationRaw>,
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct VerbInvocationRaw {
    pub name: String,
    pub args: Option<String>,
    pub bang: bool,
}

/// Parse the whole input
pub fn parse_input(input: &str) -> ParsedInput {
    let chars: Vec<char> = input.chars().collect();
    let mut parser = InputParser { chars: &chars, pos: 0 };
    let (expr, err) = match parser.parse_expr(0) {
        Ok(e) => (e, None),
        Err(e) => (None, Some(e)),
    };
    let pattern_raw: String = chars[..parser.pos.min(chars.len())].iter().collect();
    // verb part
    let mut verb = None;
    if parser.pos < chars.len() {
        let c = chars[parser.pos];
        if c == ' ' || c == ':' {
            let rest: String = chars[parser.pos + 1..].iter().collect();
            verb = Some(parse_verb_invocation(&rest));
        }
    }
    ParsedInput {
        pattern_raw,
        pattern: expr,
        pattern_error: err,
        verb,
    }
}

pub fn parse_verb_invocation(s: &str) -> VerbInvocationRaw {
    let s = s.trim_start();
    let mut bang = false;
    let mut s = s.to_string();
    if s.starts_with('!') {
        bang = true;
        s = s[1..].to_string();
    }
    let (name, args) = match s.find(' ') {
        Some(i) => (s[..i].to_string(), Some(s[i + 1..].to_string())),
        None => (s.clone(), None),
    };
    let mut name = name;
    if name.ends_with('!') {
        bang = true;
        name.pop();
    }
    VerbInvocationRaw { name, args, bang }
}

struct InputParser<'a> {
    chars: &'a [char],
    pos: usize,
}

impl<'a> InputParser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    /// parse an expression; stops at space, colon, or unbalanced ')'
    fn parse_expr(&mut self, depth: usize) -> Result<Option<PatternExpr>, String> {
        let mut left: Option<PatternExpr> = None;
        let mut pending_op: Option<char> = None;
        let mut negate = false;
        loop {
            match self.peek() {
                None => break,
                Some(' ') | Some(':') => break,
                Some('!') => {
                    negate = !negate;
                    self.pos += 1;
                }
                Some('(') => {
                    self.pos += 1;
                    let inner = self.parse_expr(depth + 1)?;
                    if self.peek() == Some(')') {
                        self.pos += 1;
                    }
                    let mut e = inner;
                    if negate {
                        if let Some(ie) = e {
                            e = Some(PatternExpr::Not(Box::new(ie)));
                        }
                        negate = false;
                    }
                    left = combine(left, pending_op.take(), e);
                }
                Some(')') => {
                    if depth > 0 {
                        break;
                    }
                    // stray closing paren: ignore it
                    self.pos += 1;
                }
                Some('&') | Some('|') => {
                    let op = self.peek().unwrap();
                    self.pos += 1;
                    pending_op = Some(op);
                }
                Some(_) => {
                    let part = self.parse_part()?;
                    let mut e = Some(PatternExpr::Part(part));
                    if negate {
                        e = Some(PatternExpr::Not(Box::new(e.unwrap())));
                        negate = false;
                    }
                    left = combine(left, pending_op.take(), e);
                }
            }
        }
        Ok(left)
    }
    fn parse_part(&mut self) -> Result<PatternPart, String> {
        // read the mode prefix: letters until '/'
        let start = self.pos;
        let mut mode_prefix: Option<String> = None;
        {
            let mut i = self.pos;
            let mut letters = String::new();
            while let Some(&c) = self.chars.get(i) {
                if c.is_ascii_alphabetic() {
                    letters.push(c);
                    i += 1;
                } else {
                    break;
                }
            }
            if self.chars.get(i) == Some(&'/') && SearchMode::from_prefix(&letters).is_some() {
                mode_prefix = Some(letters);
                self.pos = i + 1;
            }
        }
        let mut core = String::new();
        let mut flags = String::new();
        if mode_prefix.is_some() {
            // the core ends at an unescaped '/', ' ' or ':'
            let mut closed = false;
            while let Some(c) = self.peek() {
                match c {
                    '\\' => {
                        self.pos += 1;
                        match self.peek() {
                            Some(n) => {
                                if n == '/' || n == ' ' || n == ':' || n == '\\' {
                                    core.push(n);
                                } else {
                                    core.push('\\');
                                    core.push(n);
                                }
                                self.pos += 1;
                            }
                            None => core.push('\\'),
                        }
                    }
                    '/' => {
                        self.pos += 1;
                        closed = true;
                        break;
                    }
                    ' ' | ':' => break,
                    _ => {
                        core.push(c);
                        self.pos += 1;
                    }
                }
            }
            if closed {
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphabetic() {
                        flags.push(c);
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
            }
        } else {
            let _ = start;
            while let Some(c) = self.peek() {
                match c {
                    '\\' => {
                        self.pos += 1;
                        match self.peek() {
                            Some(n) => {
                                core.push(n);
                                self.pos += 1;
                            }
                            None => core.push('\\'),
                        }
                    }
                    ' ' | ':' | '&' | '|' | ')' | '(' => break,
                    _ => {
                        core.push(c);
                        self.pos += 1;
                    }
                }
            }
        }
        Ok(PatternPart { mode_prefix, core, flags })
    }
}

fn combine(left: Option<PatternExpr>, op: Option<char>, right: Option<PatternExpr>) -> Option<PatternExpr> {
    match (left, right) {
        (None, r) => r,
        (l, None) => l,
        (Some(l), Some(r)) => match op {
            Some('|') => Some(PatternExpr::Or(Box::new(l), Box::new(r))),
            _ => Some(PatternExpr::And(Box::new(l), Box::new(r))),
        },
    }
}

/// Build the pattern from the expression
pub struct PatternBuilder<'a> {
    pub search_modes: &'a std::collections::HashMap<String, String>,
    pub content_max_size: u64,
}

impl<'a> PatternBuilder<'a> {
    pub fn mode_for_prefix(&self, prefix: &Option<String>) -> Result<SearchMode, String> {
        // configured search modes override
        let key = match prefix {
            None => "<empty>".to_string(),
            Some(p) => format!("{}/", p),
        };
        if let Some(name) = self.search_modes.get(&key) {
            if let Some(m) = SearchMode::from_name(name) {
                return Ok(m);
            }
        }
        match prefix {
            None => Ok(SearchMode::FUZZY_PATH),
            Some(p) => SearchMode::from_prefix(p).ok_or_else(|| format!("unknown search mode: {}", p)),
        }
    }
    pub fn build(&self, expr: &Option<PatternExpr>) -> Result<Pattern, String> {
        match expr {
            None => Ok(Pattern::None),
            Some(e) => self.build_expr(e),
        }
    }
    fn build_expr(&self, e: &PatternExpr) -> Result<Pattern, String> {
        match e {
            PatternExpr::Part(part) => self.build_part(part),
            PatternExpr::Not(inner) => Ok(Pattern::Not(Box::new(self.build_expr(inner)?))),
            PatternExpr::And(a, b) => Ok(Pattern::Composite(
                Box::new(self.build_expr(a)?),
                PatternOp::And,
                Box::new(self.build_expr(b)?),
            )),
            PatternExpr::Or(a, b) => Ok(Pattern::Composite(
                Box::new(self.build_expr(a)?),
                PatternOp::Or,
                Box::new(self.build_expr(b)?),
            )),
        }
    }
    fn build_part(&self, part: &PatternPart) -> Result<Pattern, String> {
        let mode = self.mode_for_prefix(&part.mode_prefix)?;
        if part.core.is_empty() {
            return Ok(Pattern::None);
        }
        Ok(match (mode.kind, mode.object) {
            (SearchKind::Fuzzy, SearchObject::Content) | (SearchKind::Exact, SearchObject::Content) | (SearchKind::Tokens, SearchObject::Content) => {
                Pattern::Content(ContentPattern {
                    matcher: ContentMatcher::Exact(part.core.clone()),
                    max_file_size: self.content_max_size,
                    display: part.core.clone(),
                })
            }
            (SearchKind::Regex, SearchObject::Content) => {
                let rp = RegexPattern::new(&part.core, &part.flags)?;
                Pattern::Content(ContentPattern {
                    matcher: ContentMatcher::Regex(rp.rex),
                    max_file_size: self.content_max_size,
                    display: part.core.clone(),
                })
            }
            (SearchKind::Fuzzy, o) => Pattern::Fuzzy(FuzzyPattern::new(&part.core), o),
            (SearchKind::Regex, o) => Pattern::Regex(RegexPattern::new(&part.core, &part.flags)?, o),
            (SearchKind::Exact, o) => Pattern::Exact(ExactPattern::new(&part.core), o),
            (SearchKind::Tokens, o) => Pattern::Tokens(TokensPattern::new(&part.core), o),
        })
    }
}
