    map.insert(gid, name.clone());
    name
}

/// the 9 chars permission string, like "rwxr_xr_x"
pub fn mode_string(mode: u32) -> String {
    let mut s = String::with_capacity(9);
    let bits = [
        (0o400, 'r'), (0o200, 'w'), (0o100, 'x'),
        (0o040, 'r'), (0o020, 'w'), (0o010, 'x'),
        (0o004, 'r'), (0o002, 'w'), (0o001, 'x'),
    ];
    for (bit, c) in bits {
        if mode & bit != 0 {
            s.push(c);
        } else {
            s.push('_');
        }
    }
    s
}

/// format a size in at most 4 chars, with decimal units
pub fn fit_4(size: u64) -> String {
    if size < 10_000 {
        return size.to_string();
    }
    let units = ['K', 'M', 'G', 'T', 'P'];
    let mut v = size as f64;
    let mut unit = ' ';
    for u in units {
        v /= 1000.0;
        unit = u;
        if v < 1000.0 {
            break;
        }
    }
    if v < 10.0 {
        let s = format!("{:.1}{}", v, unit);
        if s.len() <= 4 {
            return s;
        }
    }
    format!("{}{}", v.round() as u64, unit)
}

/// the fs info (statvfs) for the root
pub struct FsInfo {
    pub fs_type: String,
    pub size: u64,
    pub used: u64,
    pub available: u64,
}

pub fn fs_info(path: &Path) -> Option<FsInfo> {
    use std::os::unix::ffi::OsStrExt;
    let c = std::ffi::CString::new(path.as_os_str().as_bytes()).ok()?;
    let mut st: libc::statvfs = unsafe { std::mem::zeroed() };
    let r = unsafe { libc::statvfs(c.as_ptr(), &mut st) };
    if r != 0 {
        return None;
    }
    let frsize = if st.f_frsize > 0 { st.f_frsize as u64 } else { st.f_bsize as u64 };
    let size = st.f_blocks as u64 * frsize;
    let available = st.f_bavail as u64 * frsize;
    let free = st.f_bfree as u64 * frsize;
    let used = size.saturating_sub(free);
    let fs_type = fs_type_of(path).unwrap_or_default();
    Some(FsInfo { fs_type, size, used, available })
}

/// find the filesystem type by reading /proc/mounts and finding the longest matching mount point
fn fs_type_of(path: &Path) -> Option<String> {
    let canon = std::fs::canonicalize(path).ok()?;
    let mounts = std::fs::read_to_string("/proc/mounts").ok()?;
    let mut best: Option<(usize, String)> = None;
    for line in mounts.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 3 {
            continue;
        }
        let mp = parts[1].replace("\\040", " ");
        let mpp = Path::new(&mp);
        if canon.starts_with(mpp) {
            let l = mp.len();
            if best.as_ref().map_or(true, |(bl, _)| l >= *bl) {
                best = Some((l, parts[2].to_string()));
            }
        }
    }
    best.map(|(_, t)| t)
}
