impl LineGitStatus {
    pub fn from_status(s: Status) -> Option<LineGitStatus> {
        if s.is_conflicted() {
            Some(LineGitStatus::Conflicted)
        } else if s.is_wt_new() || s.is_index_new() {
            Some(LineGitStatus::New)
        } else if s.is_wt_modified() || s.is_index_modified() || s.is_wt_typechange() || s.is_index_typechange() {
