        } else if s.is_wt_deleted() || s.is_index_deleted() || s.is_wt_renamed() || s.is_index_renamed() {
            Some(LineGitStatus::Other)
        } else if s.is_empty() {
            Some(LineGitStatus::Current)
        } else {
            Some(LineGitStatus::Other)
        }
    }
    pub fn char(self) -> char {
        match self {
            LineGitStatus::Current => ' ',
            LineGitStatus::Modified => 'M',
            LineGitStatus::New => 'N',
            LineGitStatus::Ignored => 'I',
            LineGitStatus::Conflicted => 'C',
            LineGitStatus::Other => '?',
        }
    }
    pub fn skin_key(self) -> &'static str {
        match self {
            LineGitStatus::Current => "git_status_current",
            LineGitStatus::Modified => "git_status_modified",
            LineGitStatus::New => "git_status_new",
            LineGitStatus::Ignored => "git_status_ignored",
            LineGitStatus::Conflicted => "git_status_conflicted",
            LineGitStatus::Other => "git_status_other",
        }
    }
}

/// statuses of the files of a repo
pub struct TreeGitStatus {
    pub current_branch_name: Option<String>,
    pub insertions: usize,
    pub deletions: usize,
    pub statuses: HashMap<PathBuf, LineGitStatus>,
}

impl TreeGitStatus {
    pub fn from(repo: &GitRepo) -> Option<TreeGitStatus> {
        let current_branch_name = repo
            .repo
            .head()
            .ok()
            .and_then(|h| h.shorthand().map(|s| s.to_string()));
        let (insertions, deletions) = {
            let mut ins = 0;
            let mut del = 0;
            // diff between HEAD tree (if any) and the working dir, with index
            let head_tree = repo.repo.head().ok().and_then(|h| h.peel_to_tree().ok());
            let diff = repo.repo.diff_tree_to_workdir_with_index(head_tree.as_ref(), None);
            if let Ok(diff) = diff {
                if let Ok(stats) = diff.stats() {
                    ins = stats.insertions();
                    del = stats.deletions();
                }
            }
            (ins, del)
        };
        let mut statuses = HashMap::new();
        let mut opts = StatusOptions::new();
        opts.include_untracked(true)
            .recurse_untracked_dirs(true)
            .include_ignored(false)
            .include_unmodified(false)
            .exclude_submodules(true);
        if let Ok(sts) = repo.repo.statuses(Some(&mut opts)) {
            for entry in sts.iter() {
                if let Some(p) = entry.path() {
                    if let Some(st) = LineGitStatus::from_status(entry.status()) {
                        statuses.insert(repo.workdir.join(p), st);
                    }
                }
            }
        }
        Some(TreeGitStatus {
            current_branch_name,
            insertions,
            deletions,
            statuses,
        })
    }
    pub fn status_of(&self, path: &Path) -> Option<LineGitStatus> {
        self.statuses.get(path).copied()
    }
}
