}

/// a very simple glob matcher (supports * and ? and leading ~)
#[derive(Debug, Clone)]
pub struct GlobPattern {
    pub source: String,
    rex: regex::Regex,
}

impl GlobPattern {
    pub fn new(src: &str) -> Option<GlobPattern> {
        let mut s = src.to_string();
        if s.starts_with("~/") || s == "~" {
            let home = crate::conf::home_dir();
            s = format!("{}{}", home.display(), &s[1..]);
        }
        let mut rex = String::from("^");
        for c in s.chars() {
            match c {
                '*' => rex.push_str(".*"),
                '?' => rex.push('.'),
                c => rex.push_str(&regex::escape(&c.to_string())),
            }
        }
        rex.push('$');
        let rex = regex::Regex::new(&rex).ok()?;
        Some(GlobPattern { source: src.to_string(), rex })
    }
    pub fn matches(&self, path: &Path) -> bool {
        let s = path.to_string_lossy();
        if self.rex.is_match(&s) {
            return true;
        }
        // also try on the file name only when the pattern has no slash
        if !self.source.contains('/') {
            if let Some(name) = path.file_name() {
                return self.rex.is_match(&name.to_string_lossy());
            }
        }
        false
    }
}

