impl TreeOptions {
    pub fn needs_sum(&self) -> bool {
        self.show_sizes || self.show_dates || self.show_counts || self.sort != Sort::None
    }
    pub fn without_pattern(&self) -> TreeOptions {
        let mut o = self.clone();
        o.pattern = Pattern::None;
        o.pattern_raw.clear();
        o
    }
    pub fn apply_flags(&mut self, flags: &str) -> Result<(), String> {
        let mut chars = flags.chars().peekable();
        if chars.peek() == Some(&'-') {
            chars.next();
        }
        for c in chars {
            match c {
                'd' => self.show_dates = true,
                'D' => self.show_dates = false,
                'f' => self.only_folders = true,
                'F' => self.only_folders = false,
                'g' => self.show_git_file_info = true,
                'G' => self.show_git_file_info = false,
                'h' => self.show_hidden = true,
                'H' => self.show_hidden = false,
                'i' => self.respect_git_ignore = false,
                'I' => self.respect_git_ignore = true,
                'p' => self.show_permissions = true,
                'P' => self.show_permissions = false,
                's' => self.show_sizes = true,
                'S' => self.show_sizes = false,
                't' => self.trim_root = true,
                'T' => self.trim_root = false,
                'w' => {
                    self.show_hidden = true;
                    self.respect_git_ignore = false;
                    self.sort = Sort::Size;
                    self.show_sizes = true;
                    self.show_root_fs = true;
                }
                'W' => {
                    self.show_hidden = false;
                    self.respect_git_ignore = true;
                    self.sort = Sort::None;
                    self.show_sizes = false;
                }
                _ => return Err(format!("unknown flag: {}", c)),
            }
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum TreeLineType {
    File,
    Dir,
    SymLink { direct_target: String, final_is_dir: bool, final_target: PathBuf },
