    Pruning,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct FileSum {
    pub size: u64,
    pub count: usize,
    pub modified: i64, // seconds since epoch
    pub sparse: bool,
}

#[derive(Debug, Clone)]
pub struct TreeLine {
    pub bid: usize,
    pub parent_bid: Option<usize>,
    pub left_branches: Vec<bool>,
    pub depth: u16,
    pub path: PathBuf,
    pub subpath: String,
    pub name: String,
    pub line_type: TreeLineType,
    pub has_error: bool,
    pub nb_kept_children: usize,
    pub unlisted: usize,
    pub score: i32,
    pub direct_match: bool,
    pub sum: Option<FileSum>,
    pub metadata: Option<Metadata>,
    pub git_status: Option<LineGitStatus>,
}

impl TreeLine {
    pub fn is_dir(&self) -> bool {
        match &self.line_type {
            TreeLineType::Dir => true,
            TreeLineType::SymLink { final_is_dir, .. } => *final_is_dir,
            _ => false,
        }
    }
    pub fn is_real_dir(&self) -> bool {
        matches!(self.line_type, TreeLineType::Dir)
    }
    pub fn is_selectable(&self) -> bool {
        !matches!(self.line_type, TreeLineType::Pruning)
    }
    pub fn is_pruning(&self) -> bool {
        matches!(self.line_type, TreeLineType::Pruning)
    }
    pub fn is_exe(&self) -> bool {
        match &self.metadata {
            Some(md) => {
                md.is_file() && (md.mode() & 0o111) != 0
            }
            None => false,
        }
    }
    pub fn is_of_kind(&self, kind: &str) -> bool {
        match kind {
            "any" => true,
            "file" => !self.is_dir() && !self.is_pruning(),
            "directory" => self.is_dir(),
            "text_file" => !self.is_dir() && !self.is_pruning() && is_text_file(&self.path),
            "binary_file" => !self.is_dir() && !self.is_pruning() && !is_text_file(&self.path),
            _ => true,
        }
    }
}

pub fn is_text_file(path: &Path) -> bool {
    let mut buf = [0u8; 1024];
    match std::fs::File::open(path) {
        Ok(mut f) => {
            use std::io::Read;
            match f.read(&mut buf) {
                Ok(n) => {
                    if n == 0 {
                        return true;
                    }
                    !buf[..n].contains(&0)
                }
                Err(_) => false,
            }
        }
        Err(_) => false,
    }
}

/// compare two names the broot way: case insensitive, then case sensitive
pub fn compare_names(a: &str, b: &str) -> Ordering {
    let la = a.to_lowercase();
    let lb = b.to_lowercase();
    match la.cmp(&lb) {
        Ordering::Equal => a.cmp(b),
        o => o,
    }
}

pub fn compare_paths(a: &Path, b: &Path) -> Ordering {
    let ca: Vec<String> = a.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    let cb: Vec<String> = b.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    for i in 0..ca.len().min(cb.len()) {
        match compare_names(&ca[i], &cb[i]) {
            Ordering::Equal => {}
            o => return o,
        }
    }
    ca.len().cmp(&cb.len())
}

