pub struct TreeBuilder<'a> {
    options: TreeOptions,
    targeted_size: usize,
    blines: Vec<BLine>,
    root_id: usize,
    git_repo: Option<&'a GitRepo>,
    report: BuildReport,
    total_search: bool,
    deadline: Option<Instant>,
    git_status: Option<&'a TreeGitStatus>,
}

pub struct BuildContext<'a> {
    pub git_repo: Option<&'a GitRepo>,
    pub git_status: Option<&'a TreeGitStatus>,
}

impl<'a> TreeBuilder<'a> {
    pub fn new(root: PathBuf, options: TreeOptions, targeted_size: usize, ctx: &BuildContext<'a>) -> std::io::Result<TreeBuilder<'a>> {
        let md = std::fs::metadata(&root)?;
        let name = root
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| root.to_string_lossy().to_string());
        let root_bline = BLine {
            parent_id: None,
            path: root.clone(),
            depth: 0,
            name,
            subpath: String::new(),
            file_type: if md.is_dir() { FileKind::Dir } else { FileKind::File },
            metadata: Some(md),
            children: None,
            next_child_idx: 0,
            has_error: false,
            has_match: true,
            direct_match: false,
            score: 0,
            nb_kept_children: 0,
            can_enter: true,
            special_sum_never: false,
        };
        Ok(TreeBuilder {
            options,
            targeted_size,
            blines: vec![root_bline],
            root_id: 0,
            git_repo: ctx.git_repo,
            report: BuildReport::default(),
            total_search: true,
            deadline: None,
            git_status: ctx.git_status,
        })
    }

    fn special_mode(&self, path: &Path, what: u8) -> SpecialHandlingMode {
        let mut mode = SpecialHandlingMode::Default;
        for sp in &self.options.special_paths {
            if sp.pattern.matches(path) {
                let m = match what {
                    0 => sp.show,
                    1 => sp.list,
                    _ => sp.sum,
                };
                if m != SpecialHandlingMode::Default {
                    mode = m;
                }
            }
        }
        mode
    }

    /// load the children of a directory bline
    fn load_children(&mut self, bid: usize) {
        let (dir_path, depth, parent_subpath, parent_has_match) = {
            let b = &self.blines[bid];
            (b.path.clone(), b.depth, b.subpath.clone(), b.has_match)
        };
        let _ = parent_has_match;
        let read = match std::fs::read_dir(&dir_path) {
            Ok(r) => r,
            Err(_) => {
                self.blines[bid].has_error = true;
                self.blines[bid].children = Some(Vec::new());
                self.report.error_count += 1;
                return;
            }
        };
        struct Entry {
            name: String,
            path: PathBuf,
            md: Metadata,
            kind: FileKind,
        }
        let mut entries: Vec<Entry> = Vec::new();
        for e in read {
            let e = match e {
                Ok(e) => e,
                Err(_) => {
                    self.report.error_count += 1;
                    continue;
                }
            };
            let name = e.file_name().to_string_lossy().to_string();
            let path = e.path();
            let md = match std::fs::symlink_metadata(&path) {
                Ok(md) => md,
                Err(_) => {
                    self.report.error_count += 1;
                    continue;
                }
            };
            let kind = if md.file_type().is_symlink() {
                FileKind::SymLink
            } else if md.is_dir() {
                FileKind::Dir
            } else {
                FileKind::File
            };
            let show_mode = self.special_mode(&path, 0);
            if show_mode == SpecialHandlingMode::Never {
                continue;
            }
            if name.starts_with('.') && !self.options.show_hidden && show_mode != SpecialHandlingMode::Always {
                self.report.hidden_count += 1;
                continue;
            }
            if self.options.respect_git_ignore {
                if let Some(repo) = self.git_repo {
                    if show_mode != SpecialHandlingMode::Always && repo.is_ignored(&path) {
                        self.report.ignored_count += 1;
                        continue;
                    }
                }
            }
            if self.options.only_folders && kind != FileKind::Dir {
                // symlinks to dirs are kept
                if kind == FileKind::SymLink {
                    match std::fs::metadata(&path) {
                        Ok(m) if m.is_dir() => {}
                        _ => continue,
                    }
                } else {
                    continue;
                }
            }
            if self.options.filter_by_git_status && kind != FileKind::Dir {
                let ok = self
                    .git_status
                    .map(|gs| gs.status_of(&path).map_or(false, |s| s != LineGitStatus::Current && s != LineGitStatus::Ignored))
                    .unwrap_or(false);
                if !ok {
                    continue;
                }
            }
            entries.push(Entry { name, path, md, kind });
        }
        entries.sort_by(|a, b| compare_names(&a.name, &b.name));
        let mut children: Vec<usize> = Vec::new();
        for e in entries {
            let subpath = if parent_subpath.is_empty() {
                e.name.clone()
            } else {
                format!("{}/{}", parent_subpath, e.name)
            };
            let list_mode = self.special_mode(&e.path, 1);
            let can_enter = match e.kind {
                FileKind::Dir => {
                    list_mode != SpecialHandlingMode::Never
                        && self.options.max_depth.map_or(true, |md| (depth as usize + 1) < md)
                }
                FileKind::SymLink => list_mode == SpecialHandlingMode::Always && std::fs::metadata(&e.path).map(|m| m.is_dir()).unwrap_or(false),
                FileKind::File => false,
            };
            let (has_match, direct_match, score) = if self.options.pattern.is_some() {
                let regular_file = e.kind == FileKind::File;
                let cand = Candidate {
                    name: &e.name,
                    subpath: &subpath,
                    path: &e.path,
                    regular_file,
                };
                match self.options.pattern.score_of(&cand) {
                    Some(s) => (true, true, s - (depth as i32 + 1)),
                    None => (false, false, 0),
                }
            } else {
                (true, false, 10000 - (depth as i32 + 1))
            };
            if !has_match && !can_enter {
                continue;
            }
            let special_sum_never = self.special_mode(&e.path, 2) == SpecialHandlingMode::Never;
            let id = self.blines.len();
            self.blines.push(BLine {
                parent_id: Some(bid),
                path: e.path,
                depth: depth + 1,
                name: e.name,
                subpath,
                file_type: e.kind,
                metadata: Some(e.md),
                children: None,
                next_child_idx: 0,
                has_error: false,
                has_match,
                direct_match,
                score,
                nb_kept_children: 0,
                can_enter,
                special_sum_never,
            });
            children.push(id);
        }
        self.blines[bid].children = Some(children);
    }

    fn next_child(&mut self, parent_id: usize) -> Option<usize> {
        let bline = &mut self.blines[parent_id];
        if let Some(children) = &bline.children {
            if bline.next_child_idx < children.len() {
                let next = children[bline.next_child_idx];
                bline.next_child_idx += 1;
                Some(next)
            } else {
                None
            }
        } else {
            None
        }
    }

    /// make the ancestors of a matching line visible, returning the number of newly visible lines
    fn ensure_ancestors_match(&mut self, id: usize) -> usize {
        let mut n = 0;
        let mut cur = self.blines[id].parent_id;
        while let Some(pid) = cur {
            if self.blines[pid].has_match {
                break;
            }
            self.blines[pid].has_match = true;
            n += 1;
            cur = self.blines[pid].parent_id;
        }
        n
    }

    fn gather_lines(&mut self, total_search: bool) -> Vec<usize> {
        let mut out_blines: Vec<usize> = Vec::new();
        let start = Instant::now();
        let not_long = Duration::from_millis(600);
        out_blines.push(self.root_id);
        let mut nb_lines_ok = 1usize;
        let mut open_dirs: VecDeque<usize> = VecDeque::new();
        let mut next_level_dirs: Vec<usize> = Vec::new();
        let has_pattern = self.options.pattern.is_some();
        let optimal_size = if self.options.pattern.has_real_scores() {
            10 * self.targeted_size
        } else {
            self.targeted_size
        };
        self.load_children(self.root_id);
        open_dirs.push_back(self.root_id);
        loop {
            if !total_search {
                let too_many = if has_pattern {
                    nb_lines_ok >= optimal_size
                } else {
                    nb_lines_ok > optimal_size
                };
                if too_many || (nb_lines_ok >= self.targeted_size && start.elapsed() > not_long) {
                    self.total_search = false;
                    break;
                }
            }
            if let Some(deadline) = self.deadline {
                if Instant::now() > deadline {
                    self.total_search = false;
                    break;
                }
            }
            if let Some(open_dir_id) = open_dirs.pop_front() {
                if let Some(child_id) = self.next_child(open_dir_id) {
                    open_dirs.push_back(open_dir_id);
                    let (child_has_match, child_can_enter) = {
                        let c = &self.blines[child_id];
                        (c.has_match, c.can_enter)
                    };
                    if child_has_match {
                        nb_lines_ok += 1;
                        nb_lines_ok += self.ensure_ancestors_match(child_id);
                    }
                    if child_can_enter {
                        next_level_dirs.push(child_id);
                    }
                    out_blines.push(child_id);
                }
            } else {
                // this depth is finished, we must go deeper
                if next_level_dirs.is_empty() {
                    break;
                }
                for next_level_dir_id in next_level_dirs.drain(..) {
                    self.load_children(next_level_dir_id);
                    open_dirs.push_back(next_level_dir_id);
                }
            }
        }
        out_blines
    }

    fn trim_excess(&mut self, out_blines: &[usize]) {
        let mut count = 1;
        let trim_root = self.options.trim_root && !self.options.sort.prevent_deep_display();
        for id in out_blines[1..].iter() {
            if self.blines[*id].has_match {
                count += 1;
                let parent_id = self.blines[*id].parent_id.unwrap();
                self.blines[parent_id].nb_kept_children += 1;
            }
        }
        let mut remove_queue: BinaryHeap<SortableBId> = BinaryHeap::new();
        for id in out_blines[1..].iter() {
            let bline = &self.blines[*id];
            if bline.has_match && bline.nb_kept_children == 0 && (bline.depth > 1 || trim_root) {
                remove_queue.push(SortableBId { id: *id, score: bline.score });
            }
        }
        while count > self.targeted_size {
            if let Some(sli) = remove_queue.pop() {
                self.blines[sli.id].has_match = false;
                let parent_id = self.blines[sli.id].parent_id.unwrap();
                let parent = &mut self.blines[parent_id];
                parent.nb_kept_children -= 1;
                parent.next_child_idx = parent.next_child_idx.saturating_sub(1);
                if parent.nb_kept_children == 0 && (parent.depth > 1 || trim_root) {
                    remove_queue.push(SortableBId { id: parent_id, score: parent.score });
                }
                count -= 1;
            } else {
                break;
            }
        }
    }

    pub fn build(mut self, total_search: bool, deadline: Option<Instant>) -> Tree {
        self.deadline = deadline;
        let out_blines = self.gather_lines(total_search);
        if !self.total_search || self.options.pattern.is_none() {
            self.trim_excess(&out_blines);
        }
        self.take(&out_blines)
    }

    fn take(mut self, out_blines: &[usize]) -> Tree {
        let mut lines: Vec<TreeLine> = Vec::new();
        let mut best_bid: Option<usize> = None;
        let mut best_score = 0;
        for id in out_blines.iter() {
            if self.blines[*id].has_match {
                // we need to count the children, so we load them
                if self.blines[*id].file_type == FileKind::Dir && self.blines[*id].children.is_none() && self.blines[*id].can_enter {
                    self.load_children(*id);
                }
                let b = &self.blines[*id];
                if b.direct_match && b.score > best_score {
                    best_score = b.score;
                    best_bid = Some(*id);
                }
                let unlisted = match &b.children {
                    Some(children) => children.len().saturating_sub(b.next_child_idx),
                    None => {
                        if b.file_type == FileKind::Dir && *id != self.root_id {
                            // not loaded: we don't know; mark as unlisted if the dir is not empty
                            match std::fs::read_dir(&b.path) {
                                Ok(mut rd) => {
                                    if rd.next().is_some() {
                                        1
                                    } else {
                                        0
                                    }
                                }
                                Err(_) => 0,
                            }
                        } else {
                            0
                        }
                    }
                };
                let line_type = match b.file_type {
                    FileKind::Dir => TreeLineType::Dir,
                    FileKind::File => TreeLineType::File,
                    FileKind::SymLink => match std::fs::read_link(&b.path) {
                        Ok(target) => {
                            let direct_target = target.to_string_lossy().to_string();
                            let final_target = if target.is_absolute() {
                                target.clone()
                            } else {
                                b.path.parent().map(|p| p.join(&target)).unwrap_or(target.clone())
                            };
                            match std::fs::metadata(&b.path) {
                                Ok(md) => TreeLineType::SymLink {
                                    direct_target,
                                    final_is_dir: md.is_dir(),
                                    final_target: normalize_path(&final_target),
                                },
                                Err(_) => TreeLineType::BrokenSymLink(direct_target),
                            }
                        }
                        Err(_) => TreeLineType::BrokenSymLink(String::new()),
                    },
                };
                let git_status = self.git_status.and_then(|gs| gs.status_of(&b.path));
                lines.push(TreeLine {
                    bid: *id,
                    parent_bid: b.parent_id,
                    left_branches: vec![false; b.depth as usize],
                    depth: b.depth,
                    path: b.path.clone(),
                    subpath: b.subpath.clone(),
                    name: b.name.clone(),
                    line_type,
                    has_error: b.has_error,
                    nb_kept_children: b.nb_kept_children.max(0) as usize,
                    unlisted,
                    score: b.score,
                    direct_match: b.direct_match,
                    sum: None,
                    metadata: b.metadata.clone(),
                    git_status,
                });
            }
        }
        let mut tree = Tree {
            lines,
            selection: 0,
            options: self.options,
            scroll: 0,
            total_search: self.total_search,
            git_status: None,
            build_report: self.report,
            fs_info: None,
        };
        tree.after_lines_changed(best_bid);
        tree
    }
}

pub fn normalize_path(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in path.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            c => out.push(c.as_os_str()),
        }
    }
    out
}

impl Tree {
    /// sort the lines, compute the branches, convert pruned children
    pub fn after_lines_changed(&mut self, best_bid: Option<usize>) {
        if self.lines.len() > 1 {
            let tail = &mut self.lines[1..];
            tail.sort_by(|a, b| compare_paths(&a.path, &b.path));
        }
        for line in self.lines.iter_mut() {
            for b in line.left_branches.iter_mut() {
                *b = false;
            }
        }
        let best_index = best_bid.and_then(|bid| self.lines.iter().position(|l| l.bid == bid));
        let mut last_parent_index: usize = self.lines.len() + 1;
        for end_index in (1..self.lines.len()).rev() {
            let depth = (self.lines[end_index].depth - 1) as usize;
            let parent_bid = self.lines[end_index].parent_bid;
            let parent_index = {
                let mut index = end_index;
                loop {
                    if index == 0 {
                        break;
                    }
                    index -= 1;
                    if Some(self.lines[index].bid) == parent_bid {
                        break;
                    }
                }
                index
            };
            if parent_index != last_parent_index {
                // the line at end_index is the last listed child of the line at parent_index
                let unlisted = self.lines[parent_index].unlisted;
                if unlisted > 0 && self.lines[end_index].nb_kept_children == 0 {
                    if best_index == Some(end_index) {
                        // we don't prune the best match
                    } else {
                        self.lines[end_index].line_type = TreeLineType::Pruning;
                        self.lines[end_index].unlisted = unlisted + 1;
                        self.lines[end_index].name = format!("{} unlisted", unlisted + 1);
                        self.lines[end_index].subpath = self.lines[end_index].name.clone();
                        self.lines[parent_index].unlisted = 0;
                    }
                }
                last_parent_index = parent_index;
            }
            for i in parent_index + 1..end_index {
                if depth < self.lines[i].left_branches.len() {
                    self.lines[i].left_branches[depth] = true;
                }
            }
            if depth < self.lines[end_index].left_branches.len() {
                // we mark the line as the last of its depth: left_branches[depth] stays false
            }
        }
        // selection
        if let Some(bi) = best_index {
            self.selection = bi;
        } else if self.options.pattern.is_some() {
            // select the first matching line
            self.selection = 0;
            for (i, line) in self.lines.iter().enumerate() {
                if i > 0 && line.direct_match {
                    self.selection = i;
                    break;
                }
            }
        } else {
            self.selection = 0;
        }
    }

    pub fn has_branch(&self, line_index: usize, depth: usize) -> bool {
        if line_index >= self.lines.len() {
            return false;
        }
        let line = &self.lines[line_index];
        depth < line.left_branches.len() && line.left_branches[depth]
    }

    pub fn root(&self) -> &Path {
        &self.lines[0].path
    }

    pub fn selected_line(&self) -> &TreeLine {
        &self.lines[self.selection]
    }

    pub fn move_selection(&mut self, dy: i32, page_height: usize, cycle: bool) {
        let len = self.lines.len() as i32;
        if len <= 1 {
            return;
        }
        let mut sel = self.selection as i32;
        for _ in 0..dy.abs() {
            loop {
                sel += dy.signum();
                if sel < 0 {
                    if cycle {
                        sel = len - 1;
                    } else {
                        sel = 0;
                        break;
                    }
                } else if sel >= len {
                    if cycle {
                        sel = 0;
                    } else {
                        sel = len - 1;
                        break;
                    }
                }
                if self.lines[sel as usize].is_selectable() {
                    break;
                }
            }
        }
        self.selection = sel as usize;
        self.make_selection_visible(page_height);
    }

    pub fn try_scroll(&mut self, dy: i32, page_height: usize) {
        let max_scroll = self.lines.len().saturating_sub(page_height);
        let new_scroll = (self.scroll as i32 + dy).clamp(0, max_scroll as i32) as usize;
        self.scroll = new_scroll;
        // keep the selection visible
        if self.selection > 0 {
            if self.selection < self.scroll + 1 {
                self.selection = self.scroll + 1;
                while self.selection < self.lines.len() && !self.lines[self.selection].is_selectable() {
                    self.selection += 1;
                }
            } else if self.selection >= self.scroll + page_height {
                self.selection = (self.scroll + page_height).saturating_sub(1);
                while self.selection > 0 && !self.lines[self.selection].is_selectable() {
                    self.selection -= 1;
                }
            }
        }
    }

    pub fn make_selection_visible(&mut self, page_height: usize) {
        if page_height == 0 {
            return;
        }
        if self.selection == 0 {
            // root is always visible
            return;
        }
        // lines 1.. are scrolled; the root is at the top
        if self.selection < self.scroll + 1 {
            self.scroll = self.selection - 1;
        } else if self.selection >= self.scroll + page_height {
            self.scroll = self.selection + 1 - page_height;
        }
        let max_scroll = self.lines.len().saturating_sub(page_height);
        if self.scroll > max_scroll {
            self.scroll = max_scroll;
        }
    }

    pub fn select_first(&mut self) {
        self.selection = 0;
        for i in 1..self.lines.len() {
            if self.lines[i].is_selectable() {
                self.selection = i;
                break;
            }
        }
        self.scroll = 0;
    }
    pub fn select_last(&mut self, page_height: usize) {
        for i in (0..self.lines.len()).rev() {
            if self.lines[i].is_selectable() {
                self.selection = i;
                break;
            }
        }
        self.make_selection_visible(page_height);
    }

    pub fn try_select_path(&mut self, path: &Path) -> bool {
        for (i, line) in self.lines.iter().enumerate() {
            if line.path == path && line.is_selectable() {
                self.selection = i;
                return true;
            }
        }
        false
    }

    pub fn try_select_best_match(&mut self) {
        let mut best_score = 0;
        for (i, line) in self.lines.iter().enumerate() {
            if line.direct_match && line.score > best_score {
                best_score = line.score;
                self.selection = i;
            }
        }
    }

    /// select the next (or previous) matching line
    pub fn try_select_next_match(&mut self, dir: i32, page_height: usize) -> bool {
        let len = self.lines.len();
        if len == 0 {
            return false;
        }
        let mut i = self.selection;
        for _ in 0..len {
            i = ((i as i32 + dir).rem_euclid(len as i32)) as usize;
            let line = &self.lines[i];
            if line.direct_match && line.is_selectable() {
                self.selection = i;
                self.make_selection_visible(page_height);
                return true;
            }
        }
        false
    }

    pub fn try_select_next_dir(&mut self, dir: i32, page_height: usize) -> bool {
        let len = self.lines.len();
        let mut i = self.selection;
        for _ in 0..len {
            i = ((i as i32 + dir).rem_euclid(len as i32)) as usize;
            if self.lines[i].is_dir() && self.lines[i].is_selectable() {
                self.selection = i;
                self.make_selection_visible(page_height);
                return true;
            }
        }
        false
    }

    pub fn try_select_same_depth(&mut self, dir: i32, page_height: usize) -> bool {
        let len = self.lines.len();
        let depth = self.lines[self.selection].depth;
        let mut i = self.selection;
        for _ in 0..len {
            i = ((i as i32 + dir).rem_euclid(len as i32)) as usize;
            if self.lines[i].depth == depth && self.lines[i].is_selectable() {
                self.selection = i;
                self.make_selection_visible(page_height);
                return true;
            }
        }
        false
    }

    pub fn has_dir_missing_sum(&self) -> bool {
        self.options.needs_sum()
            && self.lines.iter().skip(1).any(|l| l.is_real_dir() && l.sum.is_none())
    }

    /// compute the sums (sizes, counts, dates) of the lines
    pub fn fetch_file_sums(&mut self) {
        let special: Vec<GlobPattern> = self
            .options
            .special_paths
            .iter()
            .filter(|sp| sp.sum == SpecialHandlingMode::Never)
            .map(|sp| sp.pattern.clone())
            .collect();
        for i in 0..self.lines.len() {
            if self.lines[i].sum.is_some() {
                continue;
            }
            let path = self.lines[i].path.clone();
            let sum = match &self.lines[i].line_type {
                TreeLineType::Dir => Some(dir_sum(&path, &special)),
                TreeLineType::Pruning => None,
                _ => self.lines[i].metadata.as_ref().map(file_sum),
            };
            self.lines[i].sum = sum;
        }
    }

    /// sort the lines according to the sort option (only one level is displayed)
    pub fn sort_lines(&mut self) {
        match self.options.sort {
            Sort::None => {}
            Sort::Count => {
                let tail = &mut self.lines[1..];
                tail.sort_by(|a, b| {
                    let ca = a.sum.map(|s| s.count).unwrap_or(0);
                    let cb = b.sum.map(|s| s.count).unwrap_or(0);
                    cb.cmp(&ca).then_with(|| compare_paths(&a.path, &b.path))
                });
            }
            Sort::Date => {
                let tail = &mut self.lines[1..];
                tail.sort_by(|a, b| {
                    let da = a.sum.map(|s| s.modified).unwrap_or(0);
                    let db = b.sum.map(|s| s.modified).unwrap_or(0);
                    db.cmp(&da).then_with(|| compare_paths(&a.path, &b.path))
                });
            }
            Sort::Size => {
                let tail = &mut self.lines[1..];
                tail.sort_by(|a, b| {
                    let sa = a.sum.map(|s| s.size).unwrap_or(0);
                    let sb = b.sum.map(|s| s.size).unwrap_or(0);
                    sb.cmp(&sa).then_with(|| compare_paths(&a.path, &b.path))
                });
            }
            Sort::TypeDirsFirst => {
                let tail = &mut self.lines[1..];
                tail.sort_by(|a, b| {
                    b.is_dir().cmp(&a.is_dir()).then_with(|| compare_paths(&a.path, &b.path))
                });
            }
            Sort::TypeDirsLast => {
                let tail = &mut self.lines[1..];
                tail.sort_by(|a, b| {
                    a.is_dir().cmp(&b.is_dir()).then_with(|| compare_paths(&a.path, &b.path))
                });
            }
        }
    }

    pub fn total_size(&self) -> u64 {
        self.lines.get(0).and_then(|l| l.sum).map(|s| s.size).unwrap_or(0)
    }
}

pub fn file_sum(md: &Metadata) -> FileSum {
    FileSum {
        size: file_info::disk_size(md),
        count: 1,
        modified: md.mtime(),
        sparse: file_info::is_sparse(md),
    }
}

pub fn dir_sum(path: &Path, special_never: &[GlobPattern]) -> FileSum {
    let mut sum = FileSum::default();
    if let Ok(md) = std::fs::symlink_metadata(path) {
        sum.size += file_info::disk_size(&md);
        sum.modified = md.mtime();
    }
    let mut stack: Vec<PathBuf> = vec![path.to_path_buf()];
    let mut visited = 0usize;
    while let Some(dir) = stack.pop() {
        let rd = match std::fs::read_dir(&dir) {
            Ok(rd) => rd,
            Err(_) => continue,
        };
        for e in rd.flatten() {
            let p = e.path();
            let md = match std::fs::symlink_metadata(&p) {
                Ok(md) => md,
                Err(_) => continue,
            };
            visited += 1;
            if visited > 2_000_000 {
                return sum;
            }
            if md.file_type().is_symlink() {
                sum.count += 1;
                sum.size += file_info::disk_size(&md);
                if md.mtime() > sum.modified {
                    sum.modified = md.mtime();
                }
            } else if md.is_dir() {
                sum.size += file_info::disk_size(&md);
                if md.mtime() > sum.modified {
                    sum.modified = md.mtime();
                }
                if !special_never.iter().any(|g| g.matches(&p)) {
                    stack.push(p);
                }
            } else {
                sum.count += 1;
                sum.size += file_info::disk_size(&md);
                if file_info::is_sparse(&md) {
                    sum.sparse = true;
                }
                if md.mtime() > sum.modified {
                    sum.modified = md.mtime();
                }
            }
        }
    }
    sum
}
