//! Verbs: builtins and configured ones

use crate::conf::VerbConf;
use crate::keys::{self, KeyCombination};

#[derive(Debug, Clone, PartialEq)]
pub enum Execution {
    Internal { name: String, bang: bool, arg: Option<String> },
    External { parts: Vec<String> },
    Sequence { sequence: String, separator: Option<String> },
}

#[derive(Debug, Clone)]
pub struct Verb {
    pub name: String,
    pub shortcut: Option<String>,
    pub keys: Vec<KeyCombination>,
    pub key_names: Vec<String>, // as displayed
    pub description: String,
    pub execution: Execution,
    pub args_pattern: Option<String>, // eg "{subpath}" or "{newpath:path-from-parent}"
    pub leave_broot: bool,
    pub from_shell: bool,
    pub apply_to: Option<String>,
    pub extensions: Option<Vec<String>>,
    pub set_working_dir: bool,
    pub working_dir: Option<String>,
    pub auto_exec: bool,
    pub switch_terminal: bool,
    pub panels: Option<Vec<String>>,
    pub is_builtin: bool,
    pub hidden: bool, // not shown in help
}

impl Verb {
    pub fn needs_arg(&self) -> bool {
        self.args_pattern.is_some()
    }
    /// the invocation as displayed in status: "name {args}"
    pub fn invocation_display(&self, typed_name: &str) -> String {
        match &self.args_pattern {
            Some(p) => format!("{} {}", typed_name, strip_arg_types(p)),
            None => typed_name.to_string(),
        }
    }
    pub fn arg_names(&self) -> Vec<(String, String)> {
        // returns (name, type) pairs from the args pattern
        let mut v = Vec::new();
        if let Some(p) = &self.args_pattern {
            let mut rest = p.as_str();
            while let Some(s) = rest.find('{') {
                if let Some(e) = rest[s..].find('}') {
                    let inner = &rest[s + 1..s + e];
                    let (n, t) = match inner.find(':') {
                        Some(i) => (inner[..i].to_string(), inner[i + 1..].to_string()),
                        None => (inner.to_string(), String::new()),
                    };
                    v.push((n, t));
                    rest = &rest[s + e + 1..];
                } else {
                    break;
                }
            }
        }
        v
    }
    pub fn matches_prefix(&self, prefix: &str) -> bool {
        self.name.starts_with(prefix) || self.shortcut.as_deref().map_or(false, |s| s.starts_with(prefix))
    }
    pub fn is_exact(&self, name: &str) -> bool {
        self.name == name || self.shortcut.as_deref() == Some(name)
    }
}

pub fn strip_arg_types(p: &str) -> String {
    let mut out = String::new();
    let mut rest = p;
    while let Some(s) = rest.find('{') {
        out.push_str(&rest[..s]);
        if let Some(e) = rest[s..].find('}') {
            let inner = &rest[s + 1..s + e];
            let name = match inner.find(':') {
                Some(i) => &inner[..i],
                None => inner,
            };
            out.push('{');
            out.push_str(name);
            out.push('}');
            rest = &rest[s + e + 1..];
        } else {
            out.push_str(&rest[s..]);
            rest = "";
            break;
        }
    }
    out.push_str(rest);
    out
}

fn kc(s: &str) -> Vec<KeyCombination> {
    s.split(',').filter(|s| !s.is_empty()).filter_map(|s| keys::parse_key(s.trim())).collect()
}

fn internal(name: &str, shortcut: Option<&str>, keys_str: &str, desc: &str) -> Verb {
    let keys = kc(keys_str);
    Verb {
        name: name.to_string(),
        shortcut: shortcut.map(|s| s.to_string()),
        key_names: keys.iter().map(keys::key_name).collect(),
        keys,
        description: desc.to_string(),
        execution: Execution::Internal { name: name.to_string(), bang: false, arg: None },
        args_pattern: None,
        leave_broot: false,
        from_shell: false,
        apply_to: None,
        extensions: None,
        set_working_dir: false,
        working_dir: None,
        auto_exec: true,
        switch_terminal: true,
        panels: None,
        is_builtin: true,
        hidden: false,
    }
}

fn internal_arg(name: &str, shortcut: Option<&str>, keys_str: &str, desc: &str, args: &str) -> Verb {
    let mut v = internal(name, shortcut, keys_str, desc);
    v.args_pattern = Some(args.to_string());
    v
}

fn internal_bang(name: &str, internal_name: &str, shortcut: Option<&str>, keys_str: &str, desc: &str, arg: Option<&str>) -> Verb {
    let mut v = internal(name, shortcut, keys_str, desc);
    v.execution = Execution::Internal { name: internal_name.to_string(), bang: false, arg: arg.map(|s| s.to_string()) };
    v
}

fn external(name: &str, shortcut: Option<&str>, keys_str: &str, exec: &str, leave: bool, from_shell: bool) -> Verb {
    let keys = kc(keys_str);
    let (invocation, args) = split_invocation(exec, name);
    let _ = invocation;
    Verb {
        name: name.to_string(),
        shortcut: shortcut.map(|s| s.to_string()),
        key_names: keys.iter().map(keys::key_name).collect(),
        keys,
        description: exec.to_string(),
        execution: Execution::External { parts: shell_split(exec) },
        args_pattern: args,
        leave_broot: leave,
        from_shell,
        apply_to: None,
        extensions: None,
        set_working_dir: false,
        working_dir: None,
        auto_exec: true,
        switch_terminal: true,
        panels: None,
        is_builtin: true,
        hidden: false,
    }
}

/// for builtin externals: args are the {name} groups which aren't selection based
fn split_invocation(exec: &str, _name: &str) -> (String, Option<String>) {
    let mut args: Vec<String> = Vec::new();
    let mut rest = exec;
    while let Some(s) = rest.find('{') {
        if let Some(e) = rest[s..].find('}') {
            let inner = &rest[s + 1..s + e];
            let n = inner.split(':').next().unwrap_or("");
            if !is_selection_group(n) {
                args.push(format!("{{{}}}", inner));
            }
            rest = &rest[s + e + 1..];
        } else {
            break;
        }
    }
    (String::new(), if args.is_empty() { None } else { Some(args.join(" ")) })
}

pub fn is_selection_group(name: &str) -> bool {
