        "file" | "file-name" | "file-extension" | "file-stem" | "file-dot-extension" | "line" | "parent" | "directory"
            | "other-panel-file" | "other-panel-parent" | "other-panel-directory" | "root" | "initial-root"
            | "git-root" | "git-name" | "file-git-relative" | "server-name"
    )
}

/// split a command string into parts, respecting quotes
pub fn shell_split(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut cur = String::new();
    let mut in_quote: Option<char> = None;
    let mut has_token = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match in_quote {
            Some(q) => {
                if c == q {
                    in_quote = None;
                } else if c == '\\' && q == '"' {
                    if let Some(n) = chars.next() {
                        cur.push(n);
                    }
                } else {
                    cur.push(c);
                }
            }
            None => match c {
                '"' | '\'' => {
                    in_quote = Some(c);
                    has_token = true;
                }
                '\\' => {
                    if let Some(n) = chars.next() {
                        cur.push(n);
                        has_token = true;
                    }
                }
                c if c.is_whitespace() => {
                    if has_token || !cur.is_empty() {
                        parts.push(std::mem::take(&mut cur));
                        has_token = false;
                    }
                }
                _ => {
                    cur.push(c);
                    has_token = true;
                }
            },
        }
    }
    if has_token || !cur.is_empty() {
        parts.push(cur);
    }
    parts
}

