/// build a verb from its configuration
pub fn verb_from_conf(vc: &VerbConf) -> Result<Verb, String> {
    let mut invocation = vc.invocation.clone();
    if invocation.is_none() {
        if let Some(n) = &vc.name {
            invocation = Some(n.clone());
        }
    }
    let (name, args_pattern) = match &invocation {
        Some(inv) => {
            let inv = inv.trim();
            match inv.find(' ') {
                Some(i) => (inv[..i].to_string(), Some(inv[i + 1..].trim().to_string())),
                None => (inv.to_string(), None),
            }
        }
        None => (String::new(), None),
    };
    let keys: Vec<KeyCombination> = vc
        .keys
        .iter()
        .filter_map(|k| keys::parse_key(k))
        .collect();
    if name.is_empty() && keys.is_empty() {
        return Err("verb must have an invocation or a key".to_string());
    }
    let (execution, description) = if let Some(internal) = &vc.internal {
        let (n, bang, arg) = parse_internal_string(internal);
        let desc = vc.description.clone().unwrap_or_else(|| internal.clone());
        (Execution::Internal { name: n, bang, arg }, desc)
    } else if let Some(cmd) = &vc.cmd {
        let desc = vc.description.clone().unwrap_or_else(|| cmd.clone());
        (
            Execution::Sequence { sequence: cmd.clone(), separator: vc.cmd_separator.clone() },
            desc,
        )
    } else if let Some(ext) = &vc.external {
        let parts = if vc.external_is_string { shell_split(&ext[0]) } else { ext.clone() };
        let desc = vc.description.clone().unwrap_or_else(|| ext.join(" "));
        (Execution::External { parts }, desc)
    } else if let Some(exec) = &vc.execution {
        let exec_t = exec.trim();
        if exec_t.starts_with(':') {
            let (n, bang, arg) = parse_internal_string(exec_t);
            let desc = vc.description.clone().unwrap_or_else(|| exec_t.to_string());
            (Execution::Internal { name: n, bang, arg }, desc)
        } else {
            let desc = vc.description.clone().unwrap_or_else(|| exec_t.to_string());
            (Execution::External { parts: shell_split(exec_t) }, desc)
        }
    } else {
        return Err(format!("verb {} has no execution", name));
    };
    let key_names = keys.iter().map(keys::key_name).collect();
    let leave_broot = vc.leave_broot.unwrap_or(match &execution {
        Execution::Internal { .. } => false,
        _ => true,
    });
    Ok(Verb {
        name,
        shortcut: vc.shortcut.clone(),
        keys,
        key_names,
        description,
        execution,
        args_pattern,
        leave_broot,
        from_shell: vc.from_shell.unwrap_or(false),
        apply_to: vc.apply_to.clone(),
        extensions: vc.extensions.clone(),
        set_working_dir: vc.set_working_dir.unwrap_or(false),
        working_dir: vc.working_dir.clone(),
        auto_exec: vc.auto_exec.unwrap_or(true),
        switch_terminal: vc.switch_terminal.unwrap_or(true),
        panels: vc.panels.clone(),
        is_builtin: false,
        hidden: false,
    })
}

/// parse ":focus ~/dev" or "focus" into (name, bang, arg)
pub fn parse_internal_string(s: &str) -> (String, bool, Option<String>) {
    let s = s.trim();
    let s = s.strip_prefix(':').unwrap_or(s).trim_start();
    let mut bang = false;
    let mut s = s.to_string();
    if s.starts_with('!') {
        bang = true;
        s = s[1..].to_string();
    }
    let (mut name, arg) = match s.find(' ') {
        Some(i) => (s[..i].to_string(), Some(s[i + 1..].trim().to_string()).filter(|a| !a.is_empty())),
        None => (s.clone(), None),
    };
    if name.ends_with('!') {
        bang = true;
        name.pop();
    }
    (name, bang, arg)
}

pub struct VerbStore {
    pub verbs: Vec<Verb>,
}

pub enum VerbSearch<'a> {
    None,
    One(&'a Verb),
    Several(Vec<&'a Verb>),
}

impl VerbStore {
    pub fn new(conf_verbs: &[VerbConf]) -> VerbStore {
        let mut verbs = Vec::new();
        for vc in conf_verbs {
            match verb_from_conf(vc) {
                Ok(v) => verbs.push(v),
                Err(_) => {}
            }
        }
        verbs.extend(builtin_verbs());
        VerbStore { verbs }
    }

    /// search the verbs matching a typed prefix, filtering with a predicate (applicability)
    pub fn search<'a, F: Fn(&Verb) -> bool>(&'a self, prefix: &str, applicable: F) -> VerbSearch<'a> {
        // exact match first
        let exact: Vec<&Verb> = self
            .verbs
            .iter()
            .filter(|v| !v.hidden && !v.name.is_empty() && v.is_exact(prefix) && applicable(v))
            .collect();
        if let Some(v) = exact.first() {
            return VerbSearch::One(v);
        }
        let found: Vec<&Verb> = self
            .verbs
            .iter()
            .filter(|v| !v.hidden && !v.name.is_empty() && v.matches_prefix(prefix) && applicable(v))
            .collect();
        match found.len() {
            0 => VerbSearch::None,
            1 => VerbSearch::One(found[0]),
            _ => VerbSearch::Several(found),
        }
    }

    pub fn find_by_key<F: Fn(&Verb) -> bool>(&self, key: &KeyCombination, applicable: F) -> Option<&Verb> {
        self.verbs.iter().find(|v| v.keys.iter().any(|k| k == key) && applicable(v))
    }

    pub fn find_internal(&self, name: &str) -> Option<&Verb> {
        self.verbs.iter().find(|v| v.name == name)
    }
}
EOF
