//! The input field at the bottom of a panel

use crate::screen::{self, write_styled};
use crate::skin::Skin;
use crossterm::style::Attribute;
use std::io::Write;

#[derive(Debug, Clone, Default)]
pub struct InputField {
    pub chars: Vec<char>,
    pub cursor: usize, // position in chars
    pub focused: bool,
}

impl InputField {
    pub fn new() -> Self {
        InputField { chars: Vec::new(), cursor: 0, focused: true }
    }
    pub fn content(&self) -> String {
        self.chars.iter().collect()
    }
    pub fn is_empty(&self) -> bool {
        self.chars.is_empty()
    }
    pub fn set_content(&mut self, s: &str) {
        self.chars = s.chars().collect();
        self.cursor = self.chars.len();
    }
    pub fn clear(&mut self) {
        self.chars.clear();
        self.cursor = 0;
    }
    pub fn insert_char(&mut self, c: char) {
        self.chars.insert(self.cursor, c);
        self.cursor += 1;
    }
    pub fn insert_str(&mut self, s: &str) {
        for c in s.chars() {
            self.insert_char(c);
        }
    }
    pub fn del_char_left(&mut self) -> bool {
        if self.cursor > 0 {
            self.cursor -= 1;
            self.chars.remove(self.cursor);
            true
        } else {
            false
        }
    }
    pub fn del_char_below(&mut self) -> bool {
        if self.cursor < self.chars.len() {
            self.chars.remove(self.cursor);
            true
        } else {
            false
        }
    }
    pub fn del_word_left(&mut self) -> bool {
        if self.cursor == 0 {
            return false;
        }
        let mut i = self.cursor;
        while i > 0 && self.chars[i - 1] == ' ' {
            i -= 1;
        }
        while i > 0 && self.chars[i - 1] != ' ' {
            i -= 1;
        }
        self.chars.drain(i..self.cursor);
        self.cursor = i;
        true
    }
    pub fn del_word_right(&mut self) -> bool {
        if self.cursor >= self.chars.len() {
            return false;
        }
        let mut i = self.cursor;
        while i < self.chars.len() && self.chars[i] != ' ' {
            i += 1;
        }
        while i < self.chars.len() && self.chars[i] == ' ' {
            i += 1;
        }
        self.chars.drain(self.cursor..i);
        true
    }
    pub fn move_left(&mut self) -> bool {
        if self.cursor > 0 {
            self.cursor -= 1;
            true
        } else {
            false
        }
    }
    pub fn move_right(&mut self) -> bool {
        if self.cursor < self.chars.len() {
            self.cursor += 1;
            true
        } else {
            false
        }
    }
    pub fn move_to_start(&mut self) {
        self.cursor = 0;
    }
    pub fn move_to_end(&mut self) {
        self.cursor = self.chars.len();
    }
    pub fn move_word_left(&mut self) {
        let mut i = self.cursor;
        while i > 0 && self.chars[i - 1] == ' ' {
            i -= 1;
        }
        while i > 0 && self.chars[i - 1] != ' ' {
            i -= 1;
        }
        self.cursor = i;
    }
    pub fn move_word_right(&mut self) {
        let mut i = self.cursor;
        while i < self.chars.len() && self.chars[i] != ' ' {
            i += 1;
        }
        while i < self.chars.len() && self.chars[i] == ' ' {
            i += 1;
        }
        self.cursor = i;
    }

    /// draw the input field in the given area (x, y, width)
    pub fn display<W: Write>(&self, w: &mut W, skin: &Skin, x: u16, y: u16, width: usize) -> std::io::Result<()> {
        screen::goto(w, x, y)?;
        let style = skin.style("input");
        let mut cursor_style = style.clone();
        cursor_style.attrs.push(Attribute::Reverse);
        // scroll so that the cursor is visible
        let mut start = 0;
        if self.cursor >= width {
            start = self.cursor + 1 - width;
        }
        let mut col = 0;
        let mut i = start;
        while col < width {
            if i < self.chars.len() {
                let c = self.chars[i];
                let cw = screen::char_width(c).max(1);
                if col + cw > width {
                    break;
                }
                let s = c.to_string();
                if i == self.cursor && self.focused {
                    write_styled(w, &cursor_style, &s)?;
                } else {
                    write_styled(w, &style, &s)?;
                }
                col += cw;
            } else {
                if i == self.cursor && self.focused {
                    write_styled(w, &cursor_style, " ")?;
                } else {
                    write_styled(w, &style, " ")?;
                }
                col += 1;
            }
            i += 1;
        }
        Ok(())
    }
}
