//! Status line: a message (with simple markdown) displayed above the input

use crate::screen::{self, write_styled};
use crate::skin::{Skin, Style};
use std::io::Write;

#[derive(Debug, Clone, PartialEq)]
pub struct Status {
    pub message: String, // markdown: *italic*, **bold**, `code`
    pub error: bool,
}

impl Status {
    pub fn from_message(message: impl Into<String>) -> Status {
        Status { message: message.into(), error: false }
    }
    pub fn from_error(message: impl Into<String>) -> Status {
        Status { message: message.into(), error: true }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MdStyle {
    Normal,
    Italic,
    Bold,
    Code,
}

#[derive(Debug, Clone)]
pub struct Compound {
    pub text: String,
    pub style: MdStyle,
}

/// parse a simple inline markdown line into compounds
pub fn parse_md_line(s: &str) -> Vec<Compound> {
    let mut compounds = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let mut cur = String::new();
    let mut style = MdStyle::Normal;
    let mut i = 0;
    let flush = |cur: &mut String, style: MdStyle, compounds: &mut Vec<Compound>| {
        if !cur.is_empty() {
            compounds.push(Compound { text: std::mem::take(cur), style });
        }
    };
    while i < chars.len() {
        let c = chars[i];
        match c {
            '`' => {
                flush(&mut cur, style, &mut compounds);
                if style == MdStyle::Code {
                    style = MdStyle::Normal;
                } else {
                    style = MdStyle::Code;
                }
                i += 1;
            }
            '*' if style != MdStyle::Code => {
                flush(&mut cur, style, &mut compounds);
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    style = if style == MdStyle::Bold { MdStyle::Normal } else { MdStyle::Bold };
                    i += 2;
                } else {
                    style = if style == MdStyle::Italic { MdStyle::Normal } else { MdStyle::Italic };
                    i += 1;
                }
            }
            '\\' if i + 1 < chars.len() && (chars[i + 1] == '*' || chars[i + 1] == '`') => {
                cur.push(chars[i + 1]);
                i += 2;
            }
            _ => {
                cur.push(c);
                i += 1;
            }
        }
    }
    flush(&mut cur, style, &mut compounds);
    compounds
}

pub fn compounds_width(compounds: &[Compound]) -> usize {
    compounds.iter().map(|c| screen::str_width(&c.text)).sum()
}

/// make the compounds fit in the given width by removing chars in the middle of long words
/// then cutting the end with an ellipsis
pub fn fit_compounds(compounds: &mut Vec<Compound>, width: usize) {
    let mut excess = compounds_width(compounds) as isize - width as isize;
    if excess <= 0 {
        return;
    }
    // phase 1: compress long words (longest first)
    loop {
        if excess <= 0 {
            break;
        }
        // find the longest word (sequence of non-space chars within a compound) not yet compressed
        let mut best: Option<(usize, usize, usize)> = None; // (compound idx, start char, len)
        for (ci, c) in compounds.iter().enumerate() {
            let chars: Vec<char> = c.text.chars().collect();
            let mut start = 0;
            while start < chars.len() {
                while start < chars.len() && chars[start] == ' ' {
                    start += 1;
                }
                let mut end = start;
                while end < chars.len() && chars[end] != ' ' {
                    end += 1;
                }
                let len = end - start;
                if len >= 6 && !chars[start..end].contains(&'…') {
                    if best.map_or(true, |(_, _, bl)| len > bl) {
                        best = Some((ci, start, len));
                    }
                }
                start = end;
            }
        }
        let (ci, start, len) = match best {
            Some(b) => b,
            None => break,
        };
        // we can save at most len - 3 chars
        let max_save = (len - 3) as isize;
        let save = excess.min(max_save);
        let remove = save as usize + 1;
        let keep = len - remove;
        let left = (keep + 1) / 2;
        let right = keep - left;
        let chars: Vec<char> = compounds[ci].text.chars().collect();
        let mut new_text = String::new();
        for (i, c) in chars.iter().enumerate() {
            if i < start + left || i >= start + len - right {
                new_text.push(*c);
            } else if i == start + left {
                new_text.push('…');
            }
        }
        compounds[ci].text = new_text;
        excess -= save;
    }
    if excess <= 0 {
        return;
    }
    // phase 2: cut the end
    let target = width.saturating_sub(1);
    let mut acc = 0;
    let mut cut_idx = None;
    for (ci, c) in compounds.iter_mut().enumerate() {
        let w = screen::str_width(&c.text);
        if acc + w > target {
            let (fitted, _) = screen::fit_str(&c.text, target - acc);
            c.text = fitted;
            c.text.push('…');
            cut_idx = Some(ci + 1);
            break;
        }
        acc += w;
    }
    if let Some(ci) = cut_idx {
        compounds.truncate(ci);
    }
}

pub fn write_status<W: Write>(
    w: &mut W,
    skin: &Skin,
    status: &Status,
    x: u16,
    y: u16,
    width: usize,
) -> std::io::Result<()> {
    screen::goto(w, x, y)?;
    let (normal, italic, bold, code) = if status.error {
        let e = skin.style("status_error");
        (e.clone(), e.clone(), e.clone(), e)
    } else {
        (
            skin.style("status_normal"),
            skin.style("status_italic"),
            skin.style("status_bold"),
            skin.style("status_code"),
        )
    };
    let mut compounds = parse_md_line(&status.message);
    let inner_width = width.saturating_sub(1);
    fit_compounds(&mut compounds, inner_width);
    write_styled(w, &normal, " ")?;
    let mut used = 1;
    for c in &compounds {
        let st: &Style = match c.style {
            MdStyle::Normal => &normal,
            MdStyle::Italic => &italic,
            MdStyle::Bold => &bold,
            MdStyle::Code => &code,
        };
        write_styled(w, st, &c.text)?;
        used += screen::str_width(&c.text);
    }
    if used < width {
        screen::write_spaces(w, &normal, width - used)?;
    }
    Ok(())
}
