actions.command:
cat > /workspace/src/displayable_tree.rs <<'EOF'
//! rendering of a tree

use crate::file_info;
use crate::pattern::SearchObject;
use crate::screen::{self, write_styled};
use crate::skin::{Skin, Style};
use crate::tree::{Col, Tree, TreeLine, TreeLineType};
use crossterm::style::{Color, SetBackgroundColor};
use crossterm::queue;
use std::io::Write;

pub struct DisplayableTree<'a> {
    pub tree: &'a Tree,
    pub skin: &'a Skin,
    pub area_x: u16,
    pub area_y: u16,
    pub width: usize,
    pub height: usize,
    pub in_app: bool, // false when printing
    pub ext_colors: &'a std::collections::HashMap<String, String>,
    pub show_scrollbar: bool,
}

struct ColWidths {
    owner: usize,
    group: usize,
    count: usize,
}

impl<'a> DisplayableTree<'a> {
    fn compute_widths(&self) -> ColWidths {
        let mut cw = ColWidths { owner: 0, group: 0, count: 1 };
        if self.tree.options.show_permissions {
            for line in &self.tree.lines {
                if let Some(md) = &line.metadata {
                    use std::os::unix::fs::MetadataExt;
                    cw.owner = cw.owner.max(file_info::user_name(md.uid()).chars().count());
                    cw.group = cw.group.max(file_info::group_name(md.gid()).chars().count());
                }
            }
        }
        if self.tree.options.show_counts {
            for line in &self.tree.lines {
                if let Some(s) = line.sum {
                    cw.count = cw.count.max(s.count.to_string().len());
                }
            }
        }
        cw
    }

    fn name_style(&self, line: &TreeLine) -> Style {
        match &line.line_type {
            TreeLineType::Dir => self.skin.style("directory"),
            TreeLineType::File => {
                if line.is_exe() {
                    self.skin.style("exe")
                } else {
                    // extension colors
                    if !self.ext_colors.is_empty() {
                        if let Some(ext) = line.path.extension() {
                            let ext = ext.to_string_lossy().to_lowercase();
                            if let Some(c) = self.ext_colors.get(&ext) {
                                if let Ok(Some(color)) = crate::skin::parse_color(c) {
                                    let mut st = self.skin.style("file");
                                    st.fg = Some(color);
                                    return st;
                                }
                            }
                        }
                    }
                    self.skin.style("file")
                }
            }
            TreeLineType::SymLink { .. } => self.skin.style("link"),
            TreeLineType::BrokenSymLink(_) => self.skin.style("link"),
            TreeLineType::Pruning => self.skin.style("pruning"),
        }
    }

    pub fn write<W: Write>(&self, w: &mut W) -> std::io::Result<()> {
        let tree = self.tree;
        let cw = self.compute_widths();
        let scrollbar = self.in_app && self.show_scrollbar && tree.lines.len() > self.height;
        let content_width = if scrollbar { self.width.saturating_sub(1) } else { self.width };
        let default_style = self.skin.style("default");
        // scrollbar computations
        let (sb_start, sb_end) = if scrollbar {
            let total = tree.lines.len() - 1; // scrolled lines
            let visible = self.height.saturating_sub(1);
            if total > 0 && visible > 0 {
                let thumb_len = ((visible * visible) as f64 / total as f64).ceil().max(1.0) as usize;
                let thumb_len = thumb_len.min(visible);
                let max_scroll = total.saturating_sub(visible);
                let start = if max_scroll == 0 {
                    0
                } else {
                    ((tree.scroll as f64 / max_scroll as f64) * (visible - thumb_len) as f64).round() as usize
                };
                (1 + start, 1 + start + thumb_len)
            } else {
                (0, 0)
            }
        } else {
            (0, 0)
        };
        for y in 0..self.height {
            if self.in_app {
                screen::goto(w, self.area_x, self.area_y + y as u16)?;
            }
            let line_index = if y == 0 { 0 } else { y + tree.scroll };
            let mut used = 0;
            let mut line_bg: Option<Color> = default_style.bg;
            if line_index < tree.lines.len() {
                let line = &tree.lines[line_index];
                let selected = self.in_app && line_index == tree.selection;
                if selected {
                    line_bg = self.skin.style("selected_line").bg.or(line_bg);
                }
                let base = Style { fg: default_style.fg, bg: line_bg, attrs: vec![] };
                let with_bg = |s: Style| -> Style {
                    let mut s = s;
                    if s.bg.is_none() {
                        s.bg = line_bg;
                    }
                    s
                };
                if line_index == 0 {
                    used += self.write_root_line(w, line, &base, &with_bg, content_width)?;
                } else {
                    for col in &tree.options.cols_order {
                        match col {
                            Col::Mark => {
                                if tree.options.show_selection_mark {
                                    let s = if selected { "▶" } else { " " };
                                    write_styled(w, &base, s)?;
                                    used += 1;
                                }
                            }
                            Col::Git => {
                                if tree.options.show_git_file_info {
                                    match line.git_status {
                                        Some(st) if !line.is_pruning() => {
                                            write_styled(w, &with_bg(self.skin.style(st.skin_key())), &st.char().to_string())?;
                                        }
                                        _ => {
                                            write_styled(w, &with_bg(self.skin.style("tree")), " ")?;
                                        }
                                    }
                                    used += 1;
                                }
                            }
                            Col::DeviceId => {
                                if tree.options.show_device_id {
                                    use std::os::unix::fs::MetadataExt;
                                    let s = match &line.metadata {
                                        Some(md) if !line.is_pruning() => {
                                            let dev = md.dev();
                                            let major = (dev >> 8) & 0xfff;
                                            let minor = (dev & 0xff) | ((dev >> 12) & 0xfff00);
                                            format!("{:>3}:{:<3}", major, minor)
                                        }
                                        _ => "       ".to_string(),
                                    };
                                    write_styled(w, &with_bg(self.skin.style("device_id_major")), &s)?;
                                    write_styled(w, &base, " ")?;
                                    used += s.chars().count() + 1;
                                }
                            }
                            Col::Size => {
                                if tree.options.show_sizes {
                                    used += self.write_size(w, line, &base, &with_bg)?;
                                }
                            }
                            Col::Permission => {
                                if tree.options.show_permissions {
                                    used += self.write_perms(w, line, &base, &with_bg, &cw)?;
                                }
                            }
                            Col::Date => {
                                if tree.options.show_dates {
                                    match line.sum {
                                        Some(sum) if !line.is_pruning() => {
                                            let s = format_date(sum.modified, &tree.options.date_time_format);
                                            write_styled(w, &with_bg(self.skin.style("dates")), &s)?;
                                            used += screen::str_width(&s);
                                        }
                                        _ => {
                                            let n = screen::str_width(&format_date(0, &tree.options.date_time_format));
                                            screen::write_spaces(w, &base, n)?;
                                            used += n;
                                        }
                                    }
                                    write_styled(w, &base, " ")?;
                                    used += 1;
                                }
                            }
                            Col::Count => {
                                if tree.options.show_counts {
                                    match line.sum {
                                        Some(sum) if !line.is_pruning() => {
                                            let s = format!("{:>w$}", sum.count, w = cw.count);
                                            write_styled(w, &with_bg(self.skin.style("count")), &s)?;
                                            used += cw.count;
                                        }
                                        _ => {
                                            screen::write_spaces(w, &base, cw.count)?;
                                            used += cw.count;
                                        }
                                    }
                                    write_styled(w, &base, " ")?;
                                    used += 1;
                                }
                            }
                            Col::Branch => {
                                let mut branch = String::new();
                                let depth = line.depth as usize;
                                for d in 0..depth {
                                    let last = d + 1 == depth;
                                    let has = tree.has_branch(line_index, d);
                                    branch.push_str(match (last, has) {
                                        (false, true) => "│  ",
                                        (false, false) => "   ",
                                        (true, true) => "├──",
                                        (true, false) => "└──",
                                    });
                                }
                                write_styled(w, &with_bg(self.skin.style("tree")), &branch)?;
                                used += screen::str_width(&branch);
                            }
                            Col::Name => {
                                let avail = content_width.saturating_sub(used);
                                used += self.write_name(w, line, &base, &with_bg, avail)?;
                            }
                        }
                    }
                }
                // padding
                if used < content_width {
                    screen::write_spaces(w, &base, content_width - used)?;
                }
                if self.in_app {
                    // nothing more
                } else {
                    queue!(w, SetBackgroundColor(Color::Reset))?;
                }
            } else {
                // empty line
                screen::write_spaces(w, &default_style, content_width)?;
            }
            if scrollbar {
                let in_thumb = y >= sb_start && y < sb_end && y > 0;
                let st = if in_thumb {
                    self.skin.style("scrollbar_thumb")
                } else {
                    self.skin.style("scrollbar_track")
                };
                if y == 0 {
                    write_styled(w, &default_style, " ")?;
                } else {
                    write_styled(w, &st, "▐")?;
                }
            }
            if !self.in_app {
                w.write_all(b"\r\n")?;
            } else {
                queue!(w, SetBackgroundColor(Color::Reset))?;
            }
        }
        Ok(())
    }

    fn write_root_line<W: Write, F: Fn(Style) -> Style>(
        &self,
        w: &mut W,
        line: &TreeLine,
        base: &Style,
        with_bg: &F,
        width: usize,
    ) -> std::io::Result<usize> {
        let tree = self.tree;
        let mut used = 0;
        let dir_style = with_bg(self.skin.style("directory"));
        if tree.options.show_sizes {
            match line.sum {
                Some(sum) => {
                    let s = format!("{:>4}", file_info::fit_4(sum.size));
                    write_styled(w, &dir_style, &s)?;
                }
                None => {
                    screen::write_spaces(w, base, 4)?;
                }
            }
            write_styled(w, base, " ")?;
            used += 5;
        }
        let path_str = line.path.to_string_lossy().to_string();
        let (fitted, fw) = screen::fit_str(&path_str, width.saturating_sub(used));
        write_styled(w, &dir_style, &fitted)?;
        used += fw;
        // git status
        if tree.options.show_git_file_info {
            if let Some(gs) = &tree.git_status {
                let branch = gs.current_branch_name.clone().unwrap_or_default();
                let s = format!(" ᚜ {} ", branch);
                write_styled(w, &with_bg(self.skin.style("git_branch")), &s)?;
                used += screen::str_width(&s);
                let ins = format!("+{}", gs.insertions);
                write_styled(w, &with_bg(self.skin.style("git_insertions")), &ins)?;
                used += ins.len();
                let del = format!("-{}", gs.deletions);
                write_styled(w, &with_bg(self.skin.style("git_deletions")), &del)?;
                used += del.len();
            }
        }
        // fs info
        if tree.options.show_root_fs || tree.options.show_sizes {
            if let Some(fs) = &tree.fs_info {
                if used + 30 <= width {
                    let s = format!("  {}", fs.fs_type);
                    write_styled(w, base, &s)?;
                    used += screen::str_width(&s);
                    let share = if fs.size > 0 { fs.used as f64 / fs.size as f64 } else { 0.0 };
                    let level = ((share * 10.0).floor() as usize).min(9);
                    let color_style = with_bg(self.skin.style(&format!("good_to_bad_{}", level)));
                    let used_s = format!(" {}", file_info::fit_4(fs.used));
                    write_styled(w, &color_style, &used_s)?;
                    used += used_s.len();
                    let total_s = format!("/{}", file_info::fit_4(fs.size));
                    write_styled(w, base, &total_s)?;
                    used += total_s.len();
                    write_styled(w, base, " ")?;
                    used += 1;
                    // bar of 9 chars
                    let bar_width = 9usize;
                    let filled = share * bar_width as f64;
                    let full = filled.floor() as usize;
                    let frac = filled - full as f64;
                    let mut bar = String::new();
                    for _ in 0..full {
                        bar.push('█');
                    }
                    if full < bar_width {
                        let eighths = (frac * 8.0).round() as usize;
                        let c = match eighths {
                            0 => ' ',
                            1 => '▏',
                            2 => '▎',
                            3 => '▍',
                            4 => '▌',
                            5 => '▋',
                            6 => '▊',
                            7 => '▉',
                            _ => '█',
                        };
                        bar.push(c);
                    }
                    while bar.chars().count() < bar_width {
                        bar.push(' ');
                    }
                    let mut bar_style = base.clone();
                    bar_style.bg = color_style.fg;
                    write_styled(w, &bar_style, &bar)?;
                    used += bar_width;
                    let pct = format!(" {:.0}%", share * 100.0);
                    write_styled(w, &color_style, &pct)?;
                    used += pct.len();
                }
            }
        }
        Ok(used)
    }

    fn write_size<W: Write, F: Fn(Style) -> Style>(
        &self,
        w: &mut W,
        line: &TreeLine,
        base: &Style,
        with_bg: &F,
    ) -> std::io::Result<usize> {
        match line.sum {
            Some(sum) if !line.is_pruning() => {
                let s = format!("{:>4}", file_info::fit_4(sum.size));
                let st = with_bg(self.name_style(line));
                write_styled(w, &st, &s)?;
                if sum.sparse {
                    write_styled(w, &with_bg(self.skin.style("sparse")), "s")?;
                } else {
                    write_styled(w, base, " ")?;
                }
            }
            _ => {
                screen::write_spaces(w, base, 5)?;
            }
        }
        Ok(5)
    }

    fn write_perms<W: Write, F: Fn(Style) -> Style>(
        &self,
        w: &mut W,
        line: &TreeLine,
        base: &Style,
        with_bg: &F,
        cw: &ColWidths,
    ) -> std::io::Result<usize> {
        use std::os::unix::fs::MetadataExt;
        let total = 9 + 1 + cw.owner + 1 + cw.group + 1;
        match &line.metadata {
            Some(md) if !line.is_pruning() => {
                let mode = file_info::mode_string(md.mode());
                let pr = with_bg(self.skin.style("perm_r"));
                let pw = with_bg(self.skin.style("perm_w"));
                let px = with_bg(self.skin.style("perm_x"));
                let p_ = with_bg(self.skin.style("perm__"));
                for c in mode.chars() {
                    let st = match c {
                        'r' => &pr,
                        'w' => &pw,
                        'x' => &px,
                        _ => &p_,
                    };
                    write_styled(w, st, &c.to_string())?;
                }
                let owner = file_info::user_name(md.uid());
                let group = file_info::group_name(md.gid());
                let os = format!(" {:<w$}", owner, w = cw.owner);
                write_styled(w, &with_bg(self.skin.style("owner")), &os)?;
                let gs = format!(" {:<w$}", group, w = cw.group);
                write_styled(w, &with_bg(self.skin.style("group")), &gs)?;
                write_styled(w, base, " ")?;
            }
            _ => {
                screen::write_spaces(w, base, total)?;
            }
        }
        Ok(total)
    }

    fn write_name<W: Write, F: Fn(Style) -> Style>(
        &self,
        w: &mut W,
        line: &TreeLine,
        base: &Style,
        with_bg: &F,
        avail: usize,
    ) -> std::io::Result<usize> {
        let tree = self.tree;
        let mut used = 0;
        let name_style = with_bg(self.name_style(line));
        let pattern = &tree.options.pattern;
        let searches_paths = pattern.searches_paths();
        if line.is_pruning() {
            let (s, sw) = screen::fit_str(&line.name, avail);
            write_styled(w, &name_style, &s)?;
            used += sw;
            if used < avail {
                write_styled(w, base, " ")?;
                used += 1;
            }
            return Ok(used);
        }
        let display_str: String = if searches_paths && !line.subpath.is_empty() {
            line.subpath.clone()
        } else {
            line.name.clone()
        };
        let name_start = if searches_paths {
            display_str.chars().count() - line.name.chars().count()
        } else {
            0
        };
        // matched positions
        let positions: Vec<usize> = if pattern.is_some() && line.direct_match {
            let object = if searches_paths { SearchObject::Path } else { SearchObject::Name };
            pattern
                .search_string(&display_str, object)
                .map(|m| m.pos)
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        let parent_style = with_bg(self.skin.style("parent"));
        let match_style = with_bg(self.skin.style("char_match"));
        let mut col = 0;
        for (i, c) in display_str.chars().enumerate() {
            let cw = screen::char_width(c);
            if col + cw > avail {
                break;
            }
            let st = if positions.contains(&i) {
                &match_style
            } else if i < name_start {
                &parent_style
            } else {
                &name_style
            };
            write_styled(w, st, &c.to_string())?;
            col += cw;
        }
        used += col;
        match &line.line_type {
            TreeLineType::Dir => {
                if line.unlisted > 0 && used + 2 <= avail {
                    write_styled(w, &name_style, " …")?;
                    used += 2;
                }
            }
            TreeLineType::SymLink { final_target, final_is_dir, .. } => {
                let arrow = " -> ";
                if used + arrow.len() < avail {
                    write_styled(w, &name_style, arrow)?;
                    used += arrow.len();
                    let target = final_target.to_string_lossy().to_string();
                    let (s, sw) = screen::fit_str(&target, avail - used);
                    let tst = if *final_is_dir {
                        with_bg(self.skin.style("directory"))
                    } else {
                        with_bg(self.skin.style("file"))
                    };
                    write_styled(w, &tst, &s)?;
                    used += sw;
                }
            }
            TreeLineType::BrokenSymLink(target) => {
                let arrow = " -> ";
                if used + arrow.len() < avail {
                    write_styled(w, &name_style, arrow)?;
                    used += arrow.len();
                    let (s, sw) = screen::fit_str(target, avail - used);
                    write_styled(w, &with_bg(self.skin.style("file_error")), &s)?;
                    used += sw;
                }
            }
            _ => {}
        }
        if line.has_error && used + 1 < avail {
            // nothing special
        }
        if used < avail {
            write_styled(w, base, " ")?;
            used += 1;
        }
        Ok(used)
    }
}

pub fn format_date(secs: i64, fmt: &str) -> String {
    use chrono::TimeZone;
    match chrono::Local.timestamp_opt(secs, 0) {
        chrono::LocalResult::Single(dt) => dt.format(fmt).to_string(),
        _ => String::new(),
    }
}
