                    .iter()
                    .map(|c| {
                        let t = c.trim();
                        let l = t.starts_with(':');
                        let r = t.ends_with(':');
                        match (l, r) {
                            (true, true) => Align::Center,
                            (false, true) => Align::Right,
                            _ => Align::Left,
                        }
                    })
                    .collect();
