        MdStyle::Bold => skin.style("help_bold"),
        MdStyle::Code => skin.style("help_code"),
    }
}

/// split compounds into words (keeping styles), for wrapping
fn wrap_compounds(compounds: &[Compound], skin: &Skin, width: usize) -> Vec<StyledLine> {
    // tokenize into (style, text) tokens where text is a word or spaces
    let mut tokens: Vec<(MdStyle, String)> = Vec::new();
    for c in compounds {
        let mut cur = String::new();
        let mut cur_is_space: Option<bool> = None;
        for ch in c.text.chars() {
            let is_space = ch == ' ';
            if cur_is_space.is_some() && cur_is_space != Some(is_space) {
                tokens.push((c.style, std::mem::take(&mut cur)));
            }
            cur_is_space = Some(is_space);
            cur.push(ch);
        }
        if !cur.is_empty() {
            tokens.push((c.style, cur));
        }
    }
    let mut lines: Vec<StyledLine> = Vec::new();
    let mut cur_line: Vec<(Style, String)> = Vec::new();
    let mut cur_w = 0;
    let width = width.max(1);
    for (st, text) in tokens {
        let w = screen::str_width(&text);
        let is_space = text.starts_with(' ');
        if cur_w + w > width {
            if is_space {
                // drop spaces at line end
                if cur_w > 0 {
                    lines.push(StyledLine { spans: std::mem::take(&mut cur_line) });
                    cur_w = 0;
                }
                continue;
            }
            if cur_w > 0 {
                lines.push(StyledLine { spans: std::mem::take(&mut cur_line) });
                cur_w = 0;
            }
            if w > width {
                // hard break
                let mut rest = text.as_str();
                while !rest.is_empty() {
                    let (part, pw) = screen::fit_str(rest, width - cur_w);
                    if part.is_empty() {
                        break;
                    }
                    rest = &rest[part.len()..];
                    cur_line.push((style_for(skin, st), part));
                    cur_w += pw;
                    if cur_w >= width && !rest.is_empty() {
                        lines.push(StyledLine { spans: std::mem::take(&mut cur_line) });
                        cur_w = 0;
                    }
                }
                continue;
            }
        }
        if cur_w == 0 && is_space {
            continue;
        }
        cur_line.push((style_for(skin, st), text));
        cur_w += w;
    }
    if !cur_line.is_empty() || lines.is_empty() {
        lines.push(StyledLine { spans: cur_line });
    }
    lines
}

fn pad_line(line: &mut StyledLine, skin: &Skin, width: usize, align: Align) {
    let w = line.width();
    if w >= width {
        return;
    }
    let normal = skin.style("help_paragraph");
    let missing = width - w;
    match align {
        Align::Left => line.spans.push((normal, " ".repeat(missing))),
        Align::Right => line.spans.insert(0, (normal, " ".repeat(missing))),
        Align::Center => {
            let left = missing / 2;
            let right = missing - left;
            line.spans.insert(0, (normal.clone(), " ".repeat(left)));
            line.spans.push((normal, " ".repeat(right)));
        }
    }
}

/// render the blocks into styled lines of the given width
pub fn render(blocks: &[Block], skin: &Skin, width: usize) -> Vec<StyledLine> {
    let mut out: Vec<StyledLine> = Vec::new();
    let text_width = width.saturating_sub(1).max(1);
    let normal = skin.style("help_paragraph");
    for block in blocks {
        match block {
            Block::Blank => {
                out.push(StyledLine { spans: vec![(normal.clone(), " ".repeat(width))] });
            }
            Block::Title(t) => {
                let mut st = skin.style("help_headers");
                st.attrs.push(Attribute::Bold);
                st.attrs.push(Attribute::Underlined);
                let mut line = StyledLine { spans: vec![(st, t.clone())] };
                pad_line(&mut line, skin, width, Align::Center);
                out.push(line);
            }
            Block::Header(t) => {
                let mut st = skin.style("help_headers");
                st.attrs.push(Attribute::Underlined);
                let mut line = StyledLine { spans: vec![(st, t.clone())] };
                pad_line(&mut line, skin, width, Align::Left);
                out.push(line);
            }
            Block::Paragraph(t) => {
                let compounds = parse_md_line(t);
                for mut line in wrap_compounds(&compounds, skin, text_width) {
                    pad_line(&mut line, skin, width, Align::Left);
                    out.push(line);
                }
            }
            Block::Bullet(t) => {
                let compounds = parse_md_line(t);
                let lines = wrap_compounds(&compounds, skin, text_width.saturating_sub(2));
                for (i, mut line) in lines.into_iter().enumerate() {
                    let prefix = if i == 0 { "• " } else { "  " };
                    line.spans.insert(0, (normal.clone(), prefix.to_string()));
                    pad_line(&mut line, skin, width, Align::Left);
                    out.push(line);
                }
            }
            Block::Table(table) => {
                render_table(table, skin, width, &mut out);
            }
        }
    }
    out
}

fn render_table(table: &Table, skin: &Skin, width: usize, out: &mut Vec<StyledLine>) {
    let nb_cols = table.rows.iter().map(|r| r.cells.len()).max().unwrap_or(0);
    if nb_cols == 0 {
        return;
    }
    let border = skin.style("help_table_border");
    let normal = skin.style("help_paragraph");
    // natural widths
    let cell_compounds: Vec<Vec<Vec<Compound>>> = table
        .rows
        .iter()
        .map(|r| (0..nb_cols).map(|i| parse_md_line(r.cells.get(i).map(|s| s.as_str()).unwrap_or(""))).collect())
        .collect();
    let mut widths: Vec<usize> = vec![0; nb_cols];
    for row in &cell_compounds {
        for (i, c) in row.iter().enumerate() {
            widths[i] = widths[i].max(crate::status::compounds_width(c));
        }
    }
    let avail = width.saturating_sub(1);
    let total = |ws: &Vec<usize>| ws.iter().sum::<usize>() + nb_cols + 1;
    while total(&widths) > avail {
        // reduce the widest column
        let (idx, _) = widths.iter().enumerate().max_by_key(|(i, w)| (**w, std::cmp::Reverse(*i))).unwrap();
        if widths[idx] <= 3 {
            break;
        }
        widths[idx] -= 1;
    }
    let table_width = total(&widths);
    let left_pad = if table_width < width { (width - table_width) / 2 } else { 0 };
    let right_pad = width.saturating_sub(left_pad + table_width);
    let mk = |spans: Vec<(Style, String)>| -> StyledLine {
        let mut v = Vec::new();
        if left_pad > 0 {
            v.push((normal.clone(), " ".repeat(left_pad)));
        }
        v.extend(spans);
        if right_pad > 0 {
            v.push((normal.clone(), " ".repeat(right_pad)));
        }
        StyledLine { spans: v }
    };
    let rule = |l: &str, m: &str, r: &str| -> StyledLine {
        let mut s = String::new();
        s.push_str(l);
        for (i, w) in widths.iter().enumerate() {
            s.push_str(&"─".repeat(*w));
            if i + 1 < nb_cols {
                s.push_str(m);
            }
        }
        s.push_str(r);
        mk(vec![(border.clone(), s)])
    };
    out.push(rule("┌", "┬", "┐"));
    for (ri, row) in table.rows.iter().enumerate() {
        // wrap each cell
        let wrapped: Vec<Vec<StyledLine>> = (0..nb_cols)
            .map(|i| wrap_compounds(&cell_compounds[ri][i], skin, widths[i]))
            .collect();
        let nb_lines = wrapped.iter().map(|w| w.len()).max().unwrap_or(1);
        for li in 0..nb_lines {
            let mut spans: Vec<(Style, String)> = vec![(border.clone(), "│".to_string())];
            for ci in 0..nb_cols {
                let align = row.aligns.get(ci).copied().unwrap_or(Align::Left);
                let mut line = wrapped[ci].get(li).cloned().unwrap_or(StyledLine { spans: vec![] });
                // ensure it's not wider than the column
                pad_line(&mut line, skin, widths[ci], align);
                spans.extend(line.spans);
                spans.push((border.clone(), "│".to_string()));
            }
            out.push(mk(spans));
        }
        if row.rule_after && ri + 1 < table.rows.len() {
            out.push(rule("├", "┼", "┤"));
        }
    }
    out.push(rule("└", "┴", "┘"));
}
