    md.push_str("## Configuration\n\n");
    md.push_str("Verbs, skin, and more, are configured in\n");
    if ctx.conf.files.is_empty() {
        md.push_str(&format!("* **{}**\n", ctx.config_dir.join("conf.hjson").display()));
    } else {
        for f in &ctx.conf.files {
            md.push_str(&format!("* **{}**\n", f.display()));
        }
    }
    md.push_str("(hit *enter* to open the main configuration file)\n\n");
    md.push_str("## Launch Arguments\n\n");
    md.push_str("Some options can be set on launch:\n");
    md.push_str("* `-h` or `--hidden` : show hidden files\n");
    md.push_str("* `-i` : show files which are normally hidden due to .gitignore rules\n");
    md.push_str("* `-d` or `--dates` : display last modified dates\n");
    md.push_str("* `-w` : whale-spotting mode\n");
    md.push_str(" (for the complete list, run `broot --help`)\n\n");
    md.push_str("## Flags\n\n");
    md.push_str("Flags are displayed at bottom right:\n");
    md.push_str("* `h:y` or `h:n` : whether hidden files are shown\n");
    md.push_str("* `gi:y`, `gi:n` : whether gitignore rules are active or not\n\n");
    md.push_str("## Special Features\n\n");
    md.push_str("This release was compiled with those optional features enabled:\n");
    md.push_str("* **permissions:** allow showing file mode, owner and group\n");
    md
}
