    let git_status = if options.show_git_file_info || options.filter_by_git_status {
        git_repo.and_then(TreeGitStatus::from)
    } else {
        None
    };
    let ctx = BuildContext {
        git_repo,
        git_status: git_status.as_ref(),
    };
    let needs_sum = options.needs_sum();
    let show_fs = options.show_root_fs || options.show_sizes;
    let sort_prevents = options.sort.prevent_deep_display();
    let mut opts = options;
    if sort_prevents || !opts.show_tree {
        opts.max_depth = Some(1);
    }
    let builder = TreeBuilder::new(root.to_path_buf(), opts, page_height.max(1), &ctx)?;
    let mut tree = builder.build(total_search, None);
    tree.git_status = git_status;
    if needs_sum {
        tree.fetch_file_sums();
        tree.sort_lines();
        if tree.options.sort.prevent_deep_display() {
            // selection may have moved
            tree.selection = 0;
            let best = tree.lines.iter().enumerate().skip(1).filter(|(_, l)| l.direct_match).max_by_key(|(_, l)| l.score).map(|(i, _)| i);
            if let Some(b) = best {
                tree.selection = b;
            }
        }
    }
    if show_fs {
        tree.fs_info = crate::file_info::fs_info(root);
    }
    Ok(tree)
}

impl BrowserState {
    pub fn new(root: PathBuf, options: TreeOptions, page_height: usize) -> std::io::Result<BrowserState> {
        let root = std::fs::canonicalize(&root).unwrap_or(root);
        let git_repo = git::discover(&root);
        let tree = build_tree(&root, options.without_pattern(), page_height, git_repo.as_ref(), false)?;
        let mut state = BrowserState {
            tree,
            filtered_tree: None,
            root,
            git_repo,
            mode_command: false,
        };
        if options.pattern.is_some() {
            state.apply_pattern(options.pattern.clone(), &options.pattern_raw, page_height, false);
        }
        Ok(state)
    }

    pub fn displayed_tree(&self) -> &Tree {
        self.filtered_tree.as_ref().unwrap_or(&self.tree)
    }
    pub fn displayed_tree_mut(&mut self) -> &mut Tree {
        self.filtered_tree.as_mut().unwrap_or(&mut self.tree)
    }

    pub fn apply_pattern(&mut self, pattern: Pattern, raw: &str, page_height: usize, total: bool) {
        if pattern.is_none() {
            // keep selection path if possible
            let sel_path = self.filtered_tree.as_ref().map(|t| t.selected_line().path.clone());
            self.filtered_tree = None;
            if let Some(p) = sel_path {
                self.tree.try_select_path(&p);
                self.tree.make_selection_visible(page_height);
            }
            return;
        }
        let mut options = self.tree.options.clone();
        options.pattern = pattern;
        options.pattern_raw = raw.to_string();
        match build_tree(&self.root, options, page_height, self.git_repo.as_ref(), total) {
            Ok(mut tree) => {
                tree.make_selection_visible(page_height);
                self.filtered_tree = Some(tree);
            }
            Err(_) => {}
        }
    }

    /// rebuild the trees (after an option change or a refresh)
    pub fn rebuild(&mut self, options: TreeOptions, page_height: usize) -> std::io::Result<()> {
        let sel_path = self.displayed_tree().selected_line().path.clone();
        let pattern = options.pattern.clone();
        let raw = options.pattern_raw.clone();
        let tree = build_tree(&self.root, options.without_pattern(), page_height, self.git_repo.as_ref(), false)?;
        self.tree = tree;
        self.filtered_tree = None;
        if pattern.is_some() {
            self.apply_pattern(pattern, &raw, page_height, false);
        }
        let t = self.displayed_tree_mut();
        t.try_select_path(&sel_path);
        t.make_selection_visible(page_height);
        Ok(())
    }
}
