    }
}

fn md_escape_code(s: &str) -> String {
    s.replace('`', "\\`")
}

impl App {
    pub fn new(ctx: AppContext, tree_options: TreeOptions) -> Result<App, AppError> {
        let screen = Screen::new(ctx.args.height);
        let page_height = (screen.height as usize).saturating_sub(2).max(1);
        let root = ctx.initial_root.clone();
        let browser = BrowserState::new(root, tree_options.clone(), page_height)?;
        let panel = Panel {
            states: vec![State::Browser(browser)],
            input: InputField::new(),
            status: None,
        };
        Ok(App {
            ctx,
            screen,
            panel,
            quitting: false,
            launch_at_end: Vec::new(),
            tree_options,
            last_pattern_raw: String::new(),
            out_cmds: Vec::new(),
        })
    }

    fn page_height(&self) -> usize {
        (self.screen.height as usize).saturating_sub(2).max(1)
    }

    fn state(&self) -> &State {
        self.panel.states.last().unwrap()
    }
    fn state_mut(&mut self) -> &mut State {
        self.panel.states.last_mut().unwrap()
    }
    fn browser(&self) -> Option<&BrowserState> {
        for s in self.panel.states.iter().rev() {
            if let State::Browser(b) = s {
                return Some(b);
            }
        }
        None
    }
    fn browser_mut(&mut self) -> Option<&mut BrowserState> {
        for s in self.panel.states.iter_mut().rev() {
            if let State::Browser(b) = s {
                return Some(b);
            }
        }
        None
    }

    fn pattern_builder(&self) -> PatternBuilder<'_> {
        PatternBuilder {
            search_modes: &self.ctx.conf.search_modes,
            content_max_size: self.ctx.content_max_size,
        }
    }

    /// the selected path (for verbs)
    fn selected_path(&self) -> PathBuf {
        match self.state() {
            State::Browser(b) => b.displayed_tree().selected_line().path.clone(),
            State::Help(_) => self.ctx.config_dir.join("conf.hjson"),
        }
    }
    fn selection_is_dir(&self) -> bool {
        match self.state() {
            State::Browser(b) => b.displayed_tree().selected_line().is_dir(),
            State::Help(_) => false,
        }
    }

    fn verb_applicable(&self, verb: &Verb) -> bool {
        let in_help = matches!(self.state(), State::Help(_));
        if let Some(panels) = &verb.panels {
            let kind = if in_help { "help" } else { "tree" };
            if !panels.iter().any(|p| p == kind) {
                return false;
            }
        }
        if let Some(apply_to) = &verb.apply_to {
            match self.state() {
                State::Browser(b) => {
                    let line = b.displayed_tree().selected_line();
                    if !line.is_of_kind(apply_to) {
                        return false;
                    }
                }
                State::Help(_) => {
                    if apply_to == "directory" {
                        return false;
                    }
                }
            }
        }
        if let Some(exts) = &verb.extensions {
            let path = self.selected_path();
            let ext = path.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
            if !exts.iter().any(|e| e.to_lowercase() == ext) {
                return false;
            }
        }
        // builtin cd needs a directory
        if verb.is_builtin && verb.name == "cd" && !self.selection_is_dir() {
            return false;
        }
        true
    }

    // ---------------- main loop ----------------

    pub fn run(&mut self, w: &mut impl Write, commands: Vec<String>) -> Result<Vec<Launchable>, AppError> {
        // execute the initial commands
        for cmd in commands {
            self.execute_sequence_command(w, &cmd)?;
            if self.quitting {
                break;
            }
        }
        if !self.quitting {
            self.display(w)?;
            w.flush()?;
            loop {
                if crossterm::event::poll(Duration::from_millis(500))? {
                    let ev = crossterm::event::read()?;
                    match ev {
                        Event::Key(k) => {
                            self.on_key(w, k)?;
                        }
                        Event::Resize(_, _) => {
                            self.screen.refresh_size();
                            self.on_resize();
                        }
                        Event::Mouse(m) => {
                            self.on_mouse(m.kind, m.column, m.row);
                        }
                        _ => {}
                    }
                    if self.quitting {
                        break;
                    }
                    self.display(w)?;
                    w.flush()?;
                }
            }
        }
        Ok(std::mem::take(&mut self.launch_at_end))
    }

    fn on_resize(&mut self) {
        let ph = self.page_height();
        if let Some(b) = self.browser_mut() {
            b.displayed_tree_mut().make_selection_visible(ph);
        }
        if let State::Help(h) = self.state_mut() {
            h.lines.clear();
        }
    }

    fn on_mouse(&mut self, kind: MouseEventKind, _col: u16, row: u16) {
        let ph = self.page_height();
        match kind {
            MouseEventKind::Down(_) => {
                if let State::Browser(b) = self.state_mut() {
                    let tree = b.displayed_tree_mut();
                    let row = row as usize;
                    if row == 0 {
                        tree.selection = 0;
                    } else if row < ph {
                        let idx = row + tree.scroll;
                        if idx < tree.lines.len() && tree.lines[idx].is_selectable() {
                            tree.selection = idx;
                        }
                    }
                }
            }
            MouseEventKind::ScrollDown => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_scroll(3, ph);
                } else if let State::Help(h) = self.state_mut() {
                    h.scroll += 3;
                }
            }
            MouseEventKind::ScrollUp => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_scroll(-3, ph);
                } else if let State::Help(h) = self.state_mut() {
                    h.scroll = h.scroll.saturating_sub(3);
                }
            }
            _ => {}
        }
    }

    // ---------------- display ----------------

    pub fn display(&mut self, w: &mut impl Write) -> std::io::Result<()> {
        let width = self.screen.width as usize;
        let height = self.screen.height as usize;
        let page_height = self.page_height();
        let skin = self.ctx.skin.clone();
        queue!(w, cursor::Hide)?;
        match self.panel.states.last_mut().unwrap() {
            State::Browser(b) => {
                let tree = b.displayed_tree();
                let dt = DisplayableTree {
                    tree,
                    skin: &skin,
                    area_x: 0,
                    area_y: 0,
                    width,
                    height: page_height,
                    in_app: true,
                    ext_colors: &self.ctx.conf.ext_colors,
                    show_scrollbar: !tree.options.trim_root,
                };
                dt.write(w)?;
            }
            State::Help(h) => {
                let area_width = width.min(120);
                let area_x = ((width - area_width) / 2) as u16;
                if h.lines.is_empty() || h.width != area_width {
                    let hctx = help::HelpContext {
                        conf: &self.ctx.conf,
                        verbs: &self.ctx.verbs.verbs,
                        config_dir: &self.ctx.config_dir,
                    };
                    let md = help::help_markdown(&hctx, &h.pattern);
                    let blocks = mad::parse(&md);
                    h.lines = mad::render(&blocks, &skin, area_width);
                    h.width = area_width;
                }
                let total = h.lines.len();
                let max_scroll = total.saturating_sub(page_height);
                if h.scroll > max_scroll {
                    h.scroll = max_scroll;
                }
                let default_style = skin.style("default");
                let bg = skin.style("help_paragraph");
                // clear the full width first when the area is narrower
                for y in 0..page_height {
                    screen::goto(w, 0, y as u16)?;
                    if area_x > 0 {
                        screen::write_spaces(w, &default_style, area_x as usize)?;
                    }
                    let li = y + h.scroll;
                    let mut used = 0;
                    if li < total {
                        let line = &h.lines[li];
                        for (st, s) in &line.spans {
                            write_styled(w, st, s)?;
                            used += screen::str_width(s);
                        }
                    }
                    if used < area_width {
                        screen::write_spaces(w, &bg, area_width - used)?;
                    }
                    if total > page_height {
                        // scrollbar in the last column of the area
                        screen::goto(w, area_x + area_width as u16 - 1, y as u16)?;
                        let thumb_len = ((page_height * page_height) as f64 / total as f64).ceil().max(1.0) as usize;
                        let thumb_start = if max_scroll == 0 {
                            0
                        } else {
                            ((h.scroll as f64 / max_scroll as f64) * (page_height - thumb_len.min(page_height)) as f64).round() as usize
                        };
                        let in_thumb = y >= thumb_start && y < thumb_start + thumb_len;
                        let st = if in_thumb {
                            skin.style("scrollbar_thumb")
                        } else {
                            skin.style("scrollbar_track")
                        };
                        write_styled(w, &st, "▐")?;
                    }
                    let right = width - area_x as usize - area_width;
                    if right > 0 {
                        screen::goto(w, (area_x as usize + area_width) as u16, y as u16)?;
                        screen::write_spaces(w, &default_style, right)?;
                    }
                }
            }
        }
        // status
        let status = self.compute_status();
        crate::status::write_status(w, &skin, &status, 0, (height - 2) as u16, width)?;
        // input and flags
        let flags = self.flags();
        let mut flags_width = 0;
        for (label, _value) in &flags {
            flags_width += if label.is_empty() { 0 } else { label.chars().count() + 2 } + 1 + 1;
        }
        let input_width = width.saturating_sub(flags_width + 1);
        self.panel.input.display(w, &skin, 0, (height - 1) as u16, input_width)?;
        screen::goto(w, input_width as u16, (height - 1) as u16)?;
        let label_style = skin.style("flag_label");
        let value_style = skin.style("flag_value");
        for (label, value) in &flags {
            if !label.is_empty() {
                write_styled(w, &label_style, &format!(" {}:", label))?;
            }
            write_styled(w, &value_style, value)?;
            write_styled(w, &label_style, " ")?;
        }
        queue!(w, crossterm::style::ResetColor)?;
        Ok(())
    }

    fn flags(&self) -> Vec<(String, String)> {
        match self.state() {
            State::Browser(b) => {
                let o = &b.displayed_tree().options;
                vec![
                    ("h".to_string(), if o.show_hidden { "y" } else { "n" }.to_string()),
                    ("gi".to_string(), if o.respect_git_ignore { "y" } else { "n" }.to_string()),
                ]
            }
            State::Help(_) => vec![("".to_string(), "y".to_string())],
        }
    }

    fn compute_status(&self) -> Status {
        if let Some(s) = &self.panel.status {
            return s.clone();
        }
        let input = self.panel.input.content();
        let parsed = pattern::parse_input(&input);
        if let Some(verb_raw) = &parsed.verb {
            return self.verb_status(verb_raw);
        }
        match self.state() {
            State::Help(_) => Status::from_message("Hit *esc* to get back, or a space to start a verb"),
            State::Browser(b) => {
                let tree = b.displayed_tree();
                let has_pattern = tree.options.pattern.is_some();
                if has_pattern && tree.lines.len() == 1 {
                    // no match
                    let r = &tree.build_report;
                    let mut parts: Vec<String> = Vec::new();
                    if r.hidden_count > 0 {
                        parts.push("Some files are hidden, use *alt-h* to display them".to_string());
                    }
                    if r.ignored_count > 0 {
                        parts.push("Some files are ignored, use *alt-i* to display them".to_string());
                    }
                    if parts.is_empty() {
                        return Status::from_error("No match");
                    }
                    return Status::from_error(parts.join(". "));
                }
                let line = tree.selected_line();
                let msg = if tree.selection == 0 {
                    if has_pattern {
                        "Hit *enter* to go up, *esc* to clear the filter, *?* for help, or a space then a verb"
                    } else {
                        "Hit *enter* to go up, *?* for help, or a few letters to search"
                    }
                } else if line.is_dir() {
                    if has_pattern {
                        "Hit *enter* to focus, *esc* to clear the filter, *?* for help, or a space then a verb"
                    } else {
                        "Hit *enter* to focus, *?* for help, or a space then a verb"
                    }
                } else if has_pattern {
                    "Hit *alt*-*Enter* to open and quit, *esc* to clear the filter, *?* for help, or a space then a verb"
                } else {
                    "Hit *alt*-*Enter* to open and quit, *?* for help, or a space then a verb"
                };
                Status::from_message(msg)
            }
        }
    }

    fn verb_status(&self, raw: &VerbInvocationRaw) -> Status {
        if raw.name.is_empty() {
            return Status::from_message("Type a verb then *enter* to execute it (*?* for the list of verbs)");
        }
        match self.ctx.verbs.search(&raw.name, |v| self.verb_applicable(v)) {
            VerbSearch::None => Status::from_error("No matching verb (*?* for the list of verbs)"),
            VerbSearch::Several(verbs) => {
                let mut names: Vec<String> = Vec::new();
                for v in verbs {
                    if v.name.starts_with(&raw.name) {
                        names.push(format!("*{}*", v.name));
                    }
                    if let Some(sc) = &v.shortcut {
                        if sc.starts_with(&raw.name) && sc != &v.name {
                            names.push(format!("*{}*", sc));
                        }
                    }
                }
                Status::from_message(format!("Possible verbs: {}", names.join(", ")))
            }
            VerbSearch::One(verb) => self.verb_description_status(verb, raw),
        }
    }

    fn verb_description_status(&self, verb: &Verb, raw: &VerbInvocationRaw) -> Status {
        // check args
        let args_ok = match &verb.args_pattern {
            Some(_) => raw.args.as_ref().map_or(false, |a| !a.trim().is_empty()),
            None => true,
        };
        if !args_ok {
            return Status::from_error(verb.invocation_display(&raw.name));
        }
        match &verb.execution {
            Execution::Internal { name, .. } => {
                let name = name.clone();
                match name.as_str() {
                    "focus" => {
                        let path = self.focus_target(raw.args.as_deref());
                        Status::from_message(format!("Hit *enter* to focus `{}`", path.display()))
                    }
                    "cd" => {
                        let path = self.selected_path();
                        let dir = if self.selection_is_dir() { path } else { path.parent().map(|p| p.to_path_buf()).unwrap_or(path) };
                        Status::from_message(format!("Hit *enter* to **cd**: `cd {}`", dir.display()))
                    }
                    _ => Status::from_message(format!("Hit *enter* to **{}**: {}", verb.name, verb.description)),
                }
            }
            Execution::External { parts } => {
                let cmd = self.build_external_command(verb, parts, raw.args.as_deref());
                match cmd {
                    Ok(parts) => {
                        let s = parts.join(" ");
                        Status::from_message(format!("Hit *enter* to **{}**: `{}`", verb.name, md_escape_code(&s)))
                    }
                    Err(e) => Status::from_error(e),
                }
            }
            Execution::Sequence { sequence, .. } => {
                Status::from_message(format!("Hit *enter* to **{}**: `{}`", verb.name, md_escape_code(sequence)))
            }
        }
    }

    fn focus_target(&self, arg: Option<&str>) -> PathBuf {
        match arg {
            Some(a) if !a.trim().is_empty() => {
                let p = self.resolve_path_arg(a.trim(), true);
                p
            }
            _ => {
                let path = self.selected_path();
                if self.selection_is_dir() {
                    path
                } else {
                    path.parent().map(|p| p.to_path_buf()).unwrap_or(path)
                }
            }
        }
    }

    /// resolve a path typed by the user: ~ expansion, relative to the closest directory
    fn resolve_path_arg(&self, s: &str, from_directory: bool) -> PathBuf {
        let s = s.trim();
        let expanded = if s == "~" {
            crate::conf::home_dir().to_string_lossy().to_string()
        } else if let Some(rest) = s.strip_prefix("~/") {
            crate::conf::home_dir().join(rest).to_string_lossy().to_string()
        } else {
            s.to_string()
        };
        let p = PathBuf::from(&expanded);
        if p.is_absolute() {
            return crate::tree::normalize_path(&p);
        }
        let base = if from_directory {
            let sel = self.selected_path();
            if self.selection_is_dir() {
                sel
            } else {
                sel.parent().map(|p| p.to_path_buf()).unwrap_or(sel)
            }
        } else {
            self.selected_path().parent().map(|p| p.to_path_buf()).unwrap_or_default()
        };
        crate::tree::normalize_path(&base.join(p))
    }

    // ---------------- external commands ----------------

    fn replacement(&self, group: &str, args: Option<&str>, verb: &Verb) -> Result<String, String> {
        let sel = self.selected_path();
        let (name, typ) = match group.find(':') {
            Some(i) => (&group[..i], Some(&group[i + 1..])),
            None => (group, None),
        };
        let root = match self.browser() {
            Some(b) => b.displayed_tree().root().to_path_buf(),
            None => self.ctx.initial_root.clone(),
        };
        let v = match name {
            "file" => sel.to_string_lossy().to_string(),
            "file-name" => sel.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
            "file-extension" => sel.extension().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
            "file-stem" => sel.file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
            "file-dot-extension" => sel.extension().map(|n| format!(".{}", n.to_string_lossy())).unwrap_or_default(),
            "parent" => sel.parent().map(|p| p.to_string_lossy().to_string()).unwrap_or_default(),
            "directory" => {
                if self.selection_is_dir() {
                    sel.to_string_lossy().to_string()
                } else {
                    sel.parent().map(|p| p.to_string_lossy().to_string()).unwrap_or_default()
                }
            }
            "root" => root.to_string_lossy().to_string(),
            "initial-root" => self.ctx.initial_root.to_string_lossy().to_string(),
            "line" => "0".to_string(),
            "git-root" | "git-name" | "file-git-relative" => {
                let repo = self.browser().and_then(|b| b.git_repo.as_ref());
                match (name, repo) {
                    ("git-root", Some(r)) => r.workdir.to_string_lossy().trim_end_matches('/').to_string(),
                    ("git-name", Some(r)) => r.workdir.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
                    ("file-git-relative", Some(r)) => sel.strip_prefix(&r.workdir).map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|_| sel.to_string_lossy().to_string()),
                    _ => sel.to_string_lossy().to_string(),
                }
            }
            "other-panel-file" | "other-panel-parent" | "other-panel-directory" => {
                return Err("no other panel".to_string());
            }
            "server-name" => self.ctx.args.listen.clone().unwrap_or_default(),
            _ => {
                // an argument from the invocation
                let arg_names = verb.arg_names();
                let args_str = args.unwrap_or("").trim();
                if arg_names.is_empty() {
                    return Err(format!("unknown group {}", name));
                }
                let value = if arg_names.len() == 1 {
                    args_str.to_string()
                } else {
                    // split args by spaces
                    let parts: Vec<&str> = args_str.split_whitespace().collect();
                    let idx = arg_names.iter().position(|(n, _)| n == name).unwrap_or(0);
                    parts.get(idx).map(|s| s.to_string()).unwrap_or_default()
                };
                if value.is_empty() {
                    return Err(format!("missing argument {}", name));
                }
                let typ = typ.or_else(|| arg_names.iter().find(|(n, _)| n == name).map(|(_, t)| t.as_str()).filter(|t| !t.is_empty()));
                match typ {
                    Some("path-from-parent") => self.resolve_path_arg(&value, false).to_string_lossy().to_string(),
                    Some("path-from-directory") => self.resolve_path_arg(&value, true).to_string_lossy().to_string(),
                    Some("path") => self.resolve_path_arg(&value, true).to_string_lossy().to_string(),
                    _ => value,
                }
            }
        };
        Ok(v)
    }

    fn build_external_command(&self, verb: &Verb, parts: &[String], args: Option<&str>) -> Result<Vec<String>, String> {
        let mut out = Vec::new();
        for part in parts {
            let mut s = String::new();
            let mut rest = part.as_str();
            while let Some(start) = rest.find('{') {
                s.push_str(&rest[..start]);
                match rest[start..].find('}') {
                    Some(end) => {
                        let group = &rest[start + 1..start + end];
                        s.push_str(&self.replacement(group, args, verb)?);
                        rest = &rest[start + end + 1..];
                    }
                    None => {
                        s.push_str(&rest[start..]);
                        rest = "";
                    }
                }
            }
            s.push_str(rest);
            out.push(s);
        }
        Ok(out)
    }

    // ---------------- events ----------------

    fn on_key(&mut self, w: &mut impl Write, k: KeyEvent) -> Result<(), AppError> {
        if k.kind == crossterm::event::KeyEventKind::Release {
            return Ok(());
        }
        let kc = KeyCombination::from_event(&k);
        self.panel.status = None;
        // plain chars go to the input
        let plain = kc.modifiers.is_empty() || kc.modifiers == KeyModifiers::SHIFT;
        if let KeyCode::Char(c) = kc.code {
            if plain {
                if c == '?' && self.panel.input.is_empty() && !matches!(self.state(), State::Help(_)) {
                    self.open_help();
                    return Ok(());
                }
                // in help, with empty input, some keys are handled directly? no
                self.panel.input.insert_char(c);
                self.on_input_change(w)?;
                return Ok(());
            }
        }
        // keys bound to verbs
        let bound: Option<(usize, bool)> = {
            let mut found = None;
            for (i, v) in self.ctx.verbs.verbs.iter().enumerate() {
                if v.keys.iter().any(|vk| *vk == kc) && self.verb_applicable(v) {
                    found = Some((i, v.auto_exec));
                    break;
                }
            }
            found
        };
        // special handling for enter and esc and tab even if bound
        match kc.code {
            KeyCode::Enter if kc.modifiers.is_empty() => {
                return self.on_enter(w);
            }
            KeyCode::Esc => {
                self.escape(w)?;
                return Ok(());
            }
            KeyCode::Tab if kc.modifiers.is_empty() => {
                self.on_tab(w)?;
                return Ok(());
            }
            KeyCode::Backspace if kc.modifiers.is_empty() => {
                if self.panel.input.del_char_left() {
                    self.on_input_change(w)?;
                }
                return Ok(());
            }
            KeyCode::Delete if kc.modifiers.is_empty() => {
                if self.panel.input.del_char_below() {
                    self.on_input_change(w)?;
                }
                return Ok(());
            }
            KeyCode::Left if kc.modifiers.is_empty() => {
                if !self.panel.input.is_empty() {
                    self.panel.input.move_left();
                } else {
                    self.execute_internal(w, "back", false, None)?;
                }
                return Ok(());
            }
            KeyCode::Right if kc.modifiers.is_empty() => {
                if !self.panel.input.is_empty() {
                    self.panel.input.move_right();
                } else {
                    // open the selection (like enter for dirs)
                    if self.selection_is_dir() {
                        self.execute_internal(w, "open_stay", false, None)?;
                    }
                }
                return Ok(());
            }
            KeyCode::Home if kc.modifiers.is_empty() => {
                self.panel.input.move_to_start();
                return Ok(());
            }
            KeyCode::End if kc.modifiers.is_empty() => {
                self.panel.input.move_to_end();
                return Ok(());
            }
            _ => {}
        }
        if let Some((idx, auto_exec)) = bound {
            let verb = self.ctx.verbs.verbs[idx].clone();
            if auto_exec || verb.needs_arg() {
                if verb.needs_arg() && !auto_exec {
                    // put the verb in the input
                    self.panel.input.set_content(&format!(":{} ", verb.name));
                    return Ok(());
                }
                self.execute_verb(w, &verb, None, false)?;
            } else {
                self.panel.input.set_content(&format!(":{}", verb.name));
            }
            return Ok(());
        }
        // ctrl-alt chars etc: ignore
        if let KeyCode::Char(c) = kc.code {
            if kc.modifiers == KeyModifiers::ALT || kc.modifiers == KeyModifiers::CONTROL {
                let _ = c;
            }
        }
        Ok(())
    }

    fn on_tab(&mut self, w: &mut impl Write) -> Result<(), AppError> {
        let input = self.panel.input.content();
        let parsed = pattern::parse_input(&input);
        if let Some(verb_raw) = &parsed.verb {
            if verb_raw.args.is_none() && !verb_raw.name.is_empty() {
                // complete the verb name
                let candidates: Vec<String> = self
                    .ctx
                    .verbs
                    .verbs
                    .iter()
                    .filter(|v| !v.hidden && !v.name.is_empty() && self.verb_applicable(v))
                    .flat_map(|v| {
                        let mut names = vec![v.name.clone()];
                        if let Some(s) = &v.shortcut {
                            names.push(s.clone());
                        }
                        names
                    })
                    .filter(|n| n.starts_with(&verb_raw.name))
                    .collect();
                if !candidates.is_empty() {
                    // cycle: the first candidate after the current name
                    let next = candidates
                        .iter()
                        .position(|c| *c == verb_raw.name)
                        .map(|i| candidates[(i + 1) % candidates.len()].clone())
                        .unwrap_or_else(|| candidates[0].clone());
                    let prefix_len = input.len() - input.trim_start_matches(|_| true).len();
                    let _ = prefix_len;
                    // rebuild input: pattern part + separator + bang + completed name
                    let sep_pos = parsed.pattern_raw.chars().count();
                    let chars: Vec<char> = input.chars().collect();
                    let mut new_input: String = chars[..=sep_pos.min(chars.len() - 1)].iter().collect();
                    if verb_raw.bang {
                        new_input.push('!');
                    }
                    new_input.push_str(&next);
                    self.panel.input.set_content(&new_input);
                }
                return Ok(());
            }
            // complete a path argument: not implemented, fall through
            return Ok(());
        }
        // next match
        let ph = self.page_height();
        if let State::Browser(b) = self.state_mut() {
            b.displayed_tree_mut().try_select_next_match(1, ph);
        }
        let _ = w;
        Ok(())
    }

    fn on_input_change(&mut self, w: &mut impl Write) -> Result<(), AppError> {
        let input = self.panel.input.content();
        let parsed = pattern::parse_input(&input);
        self.apply_parsed_pattern(w, &parsed)?;
        Ok(())
    }

    fn apply_parsed_pattern(&mut self, _w: &mut impl Write, parsed: &ParsedInput) -> Result<(), AppError> {
        // build the pattern
        let built = match &parsed.pattern_error {
            Some(e) => Err(e.clone()),
            None => self.pattern_builder().build(&parsed.pattern),
        };
        let pattern = match built {
            Ok(p) => p,
            Err(e) => {
                let msg = if e.starts_with("unknown search mode: ") {
                    format!("Invalid search mode: \"{}/\"", &e["unknown search mode: ".len()..])
                } else {
                    let last = e.lines().last().unwrap_or("").to_string();
                    format!("Invalid Regular Expression: {}", last)
                };
                self.panel.status = Some(Status::from_error(msg));
                return Ok(());
            }
        };
        let ph = self.page_height();
        let raw = parsed.pattern_raw.clone();
        match self.state_mut() {
            State::Browser(b) => {
                let current_raw = b.displayed_tree().options.pattern_raw.clone();
                let currently_filtered = b.filtered_tree.is_some();
                if pattern.is_none() || pattern.is_empty() {
                    if currently_filtered {
                        b.apply_pattern(Pattern::None, "", ph, false);
                    }
                } else if !currently_filtered || current_raw != raw {
                    b.apply_pattern(pattern, &raw, ph, false);
                }
            }
            State::Help(h) => {
                let new_raw = raw.clone();
                let old_raw = if h.pattern.is_none() { String::new() } else { self.last_pattern_raw.clone() };
                if new_raw != old_raw {
                    h.pattern = if pattern.is_empty() { Pattern::None } else { pattern };
                    h.lines.clear();
                    h.scroll = 0;
                }
                self.last_pattern_raw = new_raw;
            }
        }
        Ok(())
    }

    fn on_enter(&mut self, w: &mut impl Write) -> Result<(), AppError> {
        let input = self.panel.input.content();
        let parsed = pattern::parse_input(&input);
        if let Some(verb_raw) = parsed.verb.clone() {
            if verb_raw.name.is_empty() {
                return Ok(());
            }
            let found = match self.ctx.verbs.search(&verb_raw.name, |v| self.verb_applicable(v)) {
                VerbSearch::None => None,
                VerbSearch::One(v) => Some(v.clone()),
                VerbSearch::Several(_) => None,
            };
            match found {
                None => {
                    // is it ambiguous or not found?
                    let msg = match self.ctx.verbs.search(&verb_raw.name, |v| self.verb_applicable(v)) {
                        VerbSearch::Several(vs) => {
                            let names: Vec<String> = vs.iter().map(|v| format!("*{}*", v.name)).collect();
                            format!("Ambiguous verb: {}", names.join(", "))
                        }
                        _ => format!("verb not found: \"{}\"", verb_raw.name),
                    };
                    self.panel.status = Some(Status::from_error(msg));
                }
                Some(verb) => {
                    // check args
                    if verb.needs_arg() && verb_raw.args.as_ref().map_or(true, |a| a.trim().is_empty()) {
                        self.panel.status = Some(Status::from_error(verb.invocation_display(&verb_raw.name)));
                        return Ok(());
                    }
                    self.execute_verb(w, &verb, verb_raw.args.as_deref(), verb_raw.bang)?;
                }
            }
            return Ok(());
        }
        // no verb: open_stay
        match self.state() {
            State::Help(_) => {
                // enter opens the config file
                let path = self.selected_path();
                self.open_file(w, &path, false)?;
            }
            State::Browser(_) => {
                self.execute_internal(w, "open_stay", false, None)?;
            }
        }
        Ok(())
    }

    fn open_help(&mut self) {
        self.panel.input.clear();
        self.last_pattern_raw.clear();
        self.panel.states.push(State::Help(HelpState {
            scroll: 0,
            pattern: Pattern::None,
            lines: Vec::new(),
            width: 0,
        }));
    }

    /// escape: clear the input or go back
    fn escape(&mut self, w: &mut impl Write) -> Result<(), AppError> {
        if !self.panel.input.is_empty() {
            self.panel.input.clear();
            self.on_input_change(w)?;
            return Ok(());
        }
        self.back(w)
    }

    fn back(&mut self, _w: &mut impl Write) -> Result<(), AppError> {
        // if there's a pattern applied, clear it first
        if let State::Browser(b) = self.state_mut() {
            if b.filtered_tree.is_some() {
                let ph = self.page_height();
                if let State::Browser(b) = self.state_mut() {
                    b.apply_pattern(Pattern::None, "", ph, false);
                }
                self.panel.input.clear();
                return Ok(());
            }
        }
        if self.panel.states.len() > 1 {
            self.panel.states.pop();
            self.panel.input.clear();
            self.last_pattern_raw.clear();
            // re-sync the input pattern for the new state (empty)
        } else if self.ctx.conf.quit_on_last_cancel {
            self.quitting = true;
        }
        Ok(())
    }

    // ---------------- sequences ----------------

    pub fn execute_sequence_command(&mut self, w: &mut impl Write, cmd: &str) -> Result<(), AppError> {
        let parsed = pattern::parse_input(cmd);
        // set the input to the pattern part (replacing the current one)
        let mut content = parsed.pattern_raw.clone();
        if let Some(v) = &parsed.verb {
            // find the separator char
            let chars: Vec<char> = cmd.chars().collect();
            let sep_idx = parsed.pattern_raw.chars().count();
            if sep_idx < chars.len() {
                content.push(chars[sep_idx]);
            }
            if v.bang {
                content.push('!');
            }
            content.push_str(&v.name);
            if let Some(a) = &v.args {
                content.push(' ');
                content.push_str(a);
            }
        }
        self.panel.input.set_content(&content);
        self.panel.status = None;
        self.apply_parsed_pattern(w, &parsed)?;
        if parsed.verb.is_some() {
            self.on_enter(w)?;
        }
        Ok(())
    }

    // ---------------- verbs execution ----------------

    fn execute_verb(&mut self, w: &mut impl Write, verb: &Verb, args: Option<&str>, bang: bool) -> Result<(), AppError> {
        match &verb.execution {
            Execution::Internal { name, bang: vbang, arg } => {
                let name = name.clone();
                // arguments: from the verb definition or the invocation
                let arg: Option<String> = match (arg, args) {
                    (Some(a), Some(inv)) => {
                        // replace {group} in the internal arg with the invocation args
                        Some(self.build_external_command(verb, &[a.clone()], Some(inv)).map(|v| v.join(" ")).unwrap_or(a.clone()))
                    }
                    (Some(a), None) => Some(self.build_external_command(verb, &[a.clone()], None).map(|v| v.join(" ")).unwrap_or(a.clone())),
                    (None, Some(inv)) => Some(inv.to_string()),
                    (None, None) => None,
                };
                self.execute_internal(w, &name, bang || *vbang, arg.as_deref())?;
            }
            Execution::External { parts } => {
                let cmd = match self.build_external_command(verb, parts, args) {
                    Ok(c) => c,
                    Err(e) => {
                        self.panel.status = Some(Status::from_error(e));
                        return Ok(());
                    }
                };
                let working_dir = if verb.set_working_dir || verb.working_dir.is_some() {
                    let wd = match &verb.working_dir {
                        Some(wdp) => self.build_external_command(verb, &[wdp.clone()], args).ok().map(|v| PathBuf::from(v.join(" "))),
                        None => Some(PathBuf::from(self.replacement("directory", args, verb).unwrap_or_default())),
                    };
                    wd.filter(|p| p.is_dir())
                } else {
                    None
                };
                if verb.leave_broot {
                    if verb.from_shell {
                        if self.ctx.args.outcmd.is_none() {
                            self.panel.status = Some(Status::from_error(
                                "this verb needs broot to be launched as `br`. Try `broot --install` if necessary.",
                            ));
                            return Ok(());
                        }
                        self.out_cmds.push(shell_join(&cmd));
                        self.quitting = true;
                    } else {
                        self.launch_at_end.push(Launchable::Exec { parts: cmd, working_dir });
                        self.quitting = true;
                    }
                } else {
                    // execute now
                    self.run_external_now(w, &cmd, working_dir.as_deref(), verb.switch_terminal)?;
                    self.panel.input.clear();
                    self.refresh(w)?;
                }
            }
            Execution::Sequence { sequence, separator } => {
                let sep = separator.clone().unwrap_or_else(|| self.ctx.cmd_separator.clone());
                let seq = self.build_external_command(verb, &[sequence.clone()], args).map(|v| v.join(" ")).unwrap_or(sequence.clone());
                let cmds: Vec<String> = seq.split(&sep).map(|s| s.to_string()).collect();
                for c in cmds {
                    self.execute_sequence_command(w, &c)?;
                    if self.quitting {
                        break;
                    }
                }
            }
        }
        Ok(())
    }

    fn run_external_now(&mut self, w: &mut impl Write, cmd: &[String], working_dir: Option<&Path>, switch_terminal: bool) -> Result<(), AppError> {
        if cmd.is_empty() {
            return Ok(());
        }
        if switch_terminal {
            queue!(w, terminal::LeaveAlternateScreen, cursor::Show)?;
            w.flush()?;
            terminal::disable_raw_mode()?;
        }
        let mut command = std::process::Command::new(&cmd[0]);
        command.args(&cmd[1..]);
        if let Some(wd) = working_dir {
            command.current_dir(wd);
        }
        let result = command.status();
        if switch_terminal {
            terminal::enable_raw_mode()?;
            queue!(w, terminal::EnterAlternateScreen, cursor::Hide)?;
            w.flush()?;
        }
        if let Err(e) = result {
            self.panel.status = Some(Status::from_error(format!("Error while executing {}: {}", cmd[0], e)));
        }
        Ok(())
    }

    fn refresh(&mut self, _w: &mut impl Write) -> Result<(), AppError> {
        let ph = self.page_height();
        let opts = self.tree_options.clone();
        if let Some(b) = self.browser_mut() {
            let mut o = b.displayed_tree().options.clone();
            o.show_hidden = opts.show_hidden;
            let _ = o;
            let options = b.displayed_tree().options.clone();
            b.rebuild(options, ph)?;
        }
        Ok(())
    }

    fn current_options(&self) -> TreeOptions {
        match self.browser() {
            Some(b) => b.displayed_tree().options.clone(),
            None => self.tree_options.clone(),
        }
    }

    fn set_options(&mut self, w: &mut impl Write, options: TreeOptions) -> Result<(), AppError> {
        let ph = self.page_height();
        self.tree_options = options.without_pattern();
        if let Some(b) = self.browser_mut() {
            b.rebuild(options, ph)?;
        }
        let _ = w;
        Ok(())
    }

    fn open_file(&mut self, w: &mut impl Write, path: &Path, leave: bool) -> Result<(), AppError> {
        let cmd = vec!["xdg-open".to_string(), path.to_string_lossy().to_string()];
        if leave {
            self.launch_at_end.push(Launchable::Exec { parts: cmd, working_dir: None });
            self.quitting = true;
        } else {
            // run detached
            let _ = std::process::Command::new("xdg-open")
                .arg(path)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn();
            let _ = w;
        }
        Ok(())
    }

    fn focus_path(&mut self, path: PathBuf, keep_pattern: bool) -> Result<(), AppError> {
        let ph = self.page_height();
        let mut options = self.current_options();
        let input = self.panel.input.content();
        if keep_pattern {
            let parsed = pattern::parse_input(&input);
            let pattern = self.pattern_builder().build(&parsed.pattern).unwrap_or(Pattern::None);
            options.pattern = pattern;
            options.pattern_raw = parsed.pattern_raw.clone();
            self.panel.input.set_content(&parsed.pattern_raw);
        } else {
            options.pattern = Pattern::None;
            options.pattern_raw.clear();
            self.panel.input.clear();
        }
        if !path.is_dir() {
            self.panel.status = Some(Status::from_error(format!("{} is not a directory", path.display())));
            return Ok(());
        }
        let state = BrowserState::new(path, options, ph)?;
        // we don't keep help states
        while matches!(self.state(), State::Help(_)) && self.panel.states.len() > 1 {
            self.panel.states.pop();
        }
        self.panel.states.push(State::Browser(state));
        if self.ctx.conf.update_work_dir {
            if let Some(b) = self.browser() {
                let _ = std::env::set_current_dir(&b.root);
            }
        }
        Ok(())
    }

    fn write_outcmd_cd(&mut self, dir: &Path) -> Result<(), AppError> {
        if self.ctx.args.outcmd.is_none() {
            self.panel.status = Some(Status::from_error(
                "this verb needs broot to be launched as `br`. Try `broot --install` if necessary.",
            ));
            return Ok(());
        }
        self.out_cmds.push(format!("cd {}", shell_quote(&dir.to_string_lossy())));
        self.quitting = true;
        Ok(())
    }

    fn execute_internal(&mut self, w: &mut impl Write, name: &str, bang: bool, arg: Option<&str>) -> Result<(), AppError> {
        let ph = self.page_height();
        let _ = bang;
        match name {
            "quit" => {
                self.quitting = true;
            }
            "escape" => {
                self.escape(w)?;
            }
            "back" => {
                self.back(w)?;
            }
            "help" => {
                if !matches!(self.state(), State::Help(_)) {
                    self.open_help();
                }
            }
            "open_stay" | "open_stay_filter" => {
                let path = self.selected_path();
                let is_dir = self.selection_is_dir();
                if let State::Help(_) = self.state() {
                    self.open_file(w, &path, false)?;
                    return Ok(());
                }
                if let Some(b) = self.browser() {
                    if b.displayed_tree().selection == 0 {
                        // go up
                        let root = b.root.clone();
                        if let Some(parent) = root.parent() {
                            let parent = parent.to_path_buf();
                            self.focus_path(parent, name == "open_stay_filter")?;
                            // select the previous root
                            if let Some(b) = self.browser_mut() {
                                b.displayed_tree_mut().try_select_path(&root);
                                b.displayed_tree_mut().make_selection_visible(ph);
                            }
                        }
                        return Ok(());
                    }
                }
                if is_dir {
                    self.focus_path(path, name == "open_stay_filter")?;
                } else {
                    self.open_file(w, &path, false)?;
                }
            }
            "open_leave" => {
                let path = self.selected_path();
                if self.selection_is_dir() {
                    self.write_outcmd_cd(&path)?;
                } else {
                    self.open_file(w, &path, true)?;
                }
            }
            "cd" => {
                let path = self.selected_path();
                let dir = if self.selection_is_dir() { path } else { path.parent().map(|p| p.to_path_buf()).unwrap_or(path) };
                self.write_outcmd_cd(&dir)?;
            }
            "focus" => {
                let target = self.focus_target(arg);
                if !target.is_dir() {
                    if target.exists() {
                        // focus the parent and select the file
                        if let Some(parent) = target.parent() {
                            let parent = parent.to_path_buf();
                            self.focus_path(parent, true)?;
                            if let Some(b) = self.browser_mut() {
                                b.displayed_tree_mut().try_select_path(&target);
                                b.displayed_tree_mut().make_selection_visible(ph);
                            }
                        }
                    } else {
                        self.panel.status = Some(Status::from_error(format!("Unknown path: {}", target.display())));
                    }
                } else {
                    self.focus_path(target, true)?;
                }
            }
            "parent" => {
                let path = self.selected_path();
                if let Some(parent) = path.parent() {
                    let parent = parent.to_path_buf();
                    self.focus_path(parent, false)?;
                    if let Some(b) = self.browser_mut() {
                        b.displayed_tree_mut().try_select_path(&path);
                        b.displayed_tree_mut().make_selection_visible(ph);
                    }
                }
            }
            "up_tree" | "root_up" => {
                if let Some(b) = self.browser() {
                    let root = b.root.clone();
                    if let Some(parent) = root.parent() {
                        let parent = parent.to_path_buf();
                        self.focus_path(parent, true)?;
                        if let Some(b) = self.browser_mut() {
                            b.displayed_tree_mut().try_select_path(&root);
                            b.displayed_tree_mut().make_selection_visible(ph);
                        }
                    }
                }
            }
            "root_down" => {
                // focus the selected dir if it's a dir, else its parent chain
                let path = self.selected_path();
                if self.selection_is_dir() {
                    self.focus_path(path, true)?;
                }
            }
            "print_path" => {
                let path = self.selected_path();
                self.launch_at_end.push(Launchable::Print(format!("{}\n", path.display())));
                self.quitting = true;
            }
            "print_relative_path" => {
                let path = self.selected_path();
                let cwd = std::env::current_dir().unwrap_or_default();
                let rel = relative_path(&cwd, &path);
                self.launch_at_end.push(Launchable::Print(format!("{}\n", rel)));
                self.quitting = true;
            }
            "print_tree" => {
                let s = self.tree_to_string()?;
                self.launch_at_end.push(Launchable::Print(s));
                self.quitting = true;
            }
            "line_down" | "line_down_no_cycle" | "line_up" | "line_up_no_cycle" => {
                let count: i32 = arg.and_then(|a| a.trim().parse().ok()).unwrap_or(1);
                let dir = if name.starts_with("line_down") { 1 } else { -1 };
                let cycle = !name.ends_with("no_cycle");
                match self.state_mut() {
                    State::Browser(b) => b.displayed_tree_mut().move_selection(dir * count, ph, cycle),
                    State::Help(h) => {
                        if dir > 0 {
                            h.scroll += count as usize;
                        } else {
                            h.scroll = h.scroll.saturating_sub(count as usize);
                        }
                    }
                }
            }
            "page_down" | "page_up" => {
                let dir: i32 = if name == "page_down" { 1 } else { -1 };
                match self.state_mut() {
                    State::Browser(b) => {
                        let tree = b.displayed_tree_mut();
                        let page = ph.saturating_sub(1).max(1) as i32;
                        tree.try_scroll(dir * page, ph);
                    }
                    State::Help(h) => {
                        let page = ph.saturating_sub(1).max(1);
                        if dir > 0 {
                            h.scroll += page;
                        } else {
                            h.scroll = h.scroll.saturating_sub(page);
                        }
                    }
                }
            }
            "select_first" => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().select_first();
                } else if let State::Help(h) = self.state_mut() {
                    h.scroll = 0;
                }
            }
            "select_last" => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().select_last(ph);
                } else if let State::Help(h) = self.state_mut() {
                    h.scroll = usize::MAX / 2;
                }
            }
            "next_match" => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_select_next_match(1, ph);
                }
            }
            "previous_match" => {
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_select_next_match(-1, ph);
                }
            }
            "next_dir" | "previous_dir" => {
                let dir = if name == "next_dir" { 1 } else { -1 };
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_select_next_dir(dir, ph);
                }
            }
            "next_same_depth" | "previous_same_depth" => {
                let dir = if name == "next_same_depth" { 1 } else { -1 };
                if let State::Browser(b) = self.state_mut() {
                    b.displayed_tree_mut().try_select_same_depth(dir, ph);
                }
            }
            "select" | "show" => {
                if let Some(a) = arg {
                    let target = self.resolve_path_arg(a, true);
                    if let State::Browser(b) = self.state_mut() {
                        let t = b.displayed_tree_mut();
                        if !t.try_select_path(&target) {
                            if name == "show" {
                                // focus the parent... keep simple
                            }
                        }
                        t.make_selection_visible(ph);
                    }
                }
            }
            "refresh" => {
                self.refresh(w)?;
            }
            "toggle_hidden" => {
                let mut o = self.current_options();
                o.show_hidden = !o.show_hidden;
                self.set_options(w, o)?;
            }
            "toggle_ignore" => {
                let mut o = self.current_options();
                o.respect_git_ignore = !o.respect_git_ignore;
                self.set_options(w, o)?;
            }
            "toggle_sizes" => {
                let mut o = self.current_options();
                o.show_sizes = !o.show_sizes;
                self.set_options(w, o)?;
            }
            "toggle_dates" => {
                let mut o = self.current_options();
                o.show_dates = !o.show_dates;
                self.set_options(w, o)?;
            }
            "toggle_counts" => {
                let mut o = self.current_options();
                o.show_counts = !o.show_counts;
                self.set_options(w, o)?;
            }
            "toggle_perm" => {
                let mut o = self.current_options();
                o.show_permissions = !o.show_permissions;
                self.set_options(w, o)?;
            }
            "toggle_files" => {
                let mut o = self.current_options();
                o.only_folders = !o.only_folders;
                self.set_options(w, o)?;
            }
            "toggle_git_file_info" => {
                let mut o = self.current_options();
                o.show_git_file_info = !o.show_git_file_info;
                self.set_options(w, o)?;
            }
            "toggle_git_status" => {
                let mut o = self.current_options();
                o.filter_by_git_status = !o.filter_by_git_status;
                self.set_options(w, o)?;
            }
            "toggle_root_fs" => {
                let mut o = self.current_options();
                o.show_root_fs = !o.show_root_fs;
                self.set_options(w, o)?;
            }
            "toggle_device_id" => {
                let mut o = self.current_options();
                o.show_device_id = !o.show_device_id;
                self.set_options(w, o)?;
            }
            "toggle_trim_root" => {
                let mut o = self.current_options();
                o.trim_root = !o.trim_root;
                self.set_options(w, o)?;
            }
            "toggle_tree" => {
                let mut o = self.current_options();
                o.show_tree = !o.show_tree;
                self.set_options(w, o)?;
            }
            "sort_by_count" | "sort_by_date" | "sort_by_size" | "sort_by_type" | "sort_by_type_dirs_first" | "sort_by_type_dirs_last" | "no_sort" => {
                let mut o = self.current_options();
                let target = match name {
                    "sort_by_count" => Sort::Count,
                    "sort_by_date" => Sort::Date,
                    "sort_by_size" => Sort::Size,
                    "sort_by_type" | "sort_by_type_dirs_first" => Sort::TypeDirsFirst,
                    "sort_by_type_dirs_last" => Sort::TypeDirsLast,
                    _ => Sort::None,
                };
                o.sort = if o.sort == target && name != "no_sort" { Sort::None } else { target };
                if target == Sort::Size && o.sort == Sort::Size {
                    o.show_sizes = true;
                }
                if target == Sort::Date && o.sort == Sort::Date {
                    o.show_dates = true;
                }
                if target == Sort::Count && o.sort == Sort::Count {
                    o.show_counts = true;
                }
                self.set_options(w, o)?;
            }
            "set_max_depth" => {
                if let Some(d) = arg.and_then(|a| a.trim().parse::<usize>().ok()) {
                    let mut o = self.current_options();
                    o.max_depth = Some(d);
                    self.set_options(w, o)?;
                }
            }
            "unset_max_depth" => {
                let mut o = self.current_options();
                o.max_depth = None;
                self.set_options(w, o)?;
            }
            "apply_flags" => {
                if let Some(flags) = arg {
                    let mut o = self.current_options();
                    match o.apply_flags(flags.trim()) {
                        Ok(()) => self.set_options(w, o)?,
                        Err(e) => self.panel.status = Some(Status::from_error(e)),
                    }
                }
            }
            "search_again" | "total_search" => {
                let ph = self.page_height();
                let input = self.panel.input.content();
                let parsed = pattern::parse_input(&input);
                if parsed.pattern.is_none() && name == "search_again" {
                    // put back the last pattern
                    let last = self.last_pattern_raw.clone();
                    if !last.is_empty() {
                        self.panel.input.set_content(&last);
                        self.on_input_change(w)?;
                    }
                } else if let Ok(pattern) = self.pattern_builder().build(&parsed.pattern) {
                    if let Some(b) = self.browser_mut() {
                        b.apply_pattern(pattern, &parsed.pattern_raw, ph, true);
                    }
                }
            }
            "input_clear" => self.panel.input.clear(),
            "input_del_char_left" => {
                self.panel.input.del_char_left();
                self.on_input_change(w)?;
            }
            "input_del_char_below" => {
                self.panel.input.del_char_below();
                self.on_input_change(w)?;
            }
            "input_del_word_left" => {
                self.panel.input.del_word_left();
                self.on_input_change(w)?;
            }
            "input_del_word_right" => {
                self.panel.input.del_word_right();
                self.on_input_change(w)?;
            }
            "input_go_to_end" => self.panel.input.move_to_end(),
            "input_go_to_start" => self.panel.input.move_to_start(),
            "input_go_left" => {
                self.panel.input.move_left();
            }
            "input_go_right" => {
                self.panel.input.move_right();
            }
            "input_go_word_left" => self.panel.input.move_word_left(),
            "input_go_word_right" => self.panel.input.move_word_right(),
            "mode_input" | "mode_command" => {}
            "write_output" => {
                if let (Some(path), Some(a)) = (&self.ctx.args.verb_output, arg) {
                    use std::io::Write as _;
                    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
                        let _ = writeln!(f, "{}", a);
                    }
                }
            }
            "clear_output" => {
                if let Some(path) = &self.ctx.args.verb_output {
                    let _ = std::fs::write(path, "");
                }
            }
            "trash" => {
                let path = self.selected_path();
                self.panel.status = Some(Status::from_error(format!("trash not available for {}", path.display())));
            }
            "copy_path" => {
                self.panel.status = Some(Status::from_error("Clipboard not available"));
            }
            "copy_line" => {
                self.panel.status = Some(Status::from_error("Clipboard not available"));
            }
            "start_end_panel" | "panel_left" | "panel_left_no_open" | "panel_right" | "panel_right_no_open"
            | "open_preview" | "close_preview" | "toggle_preview" | "preview_image" | "preview_text"
            | "preview_binary" | "preview_tty" | "close_panel_ok" | "close_panel_cancel" | "close_panel"
            | "toggle_second_tree" => {
                if name.starts_with("close_panel") {
                    // with a single panel: nothing (broot shows an error)
                    self.panel.status = Some(Status::from_error("Can't close the only panel"));
                } else {
                    self.panel.status = Some(Status::from_error(format!("{}: not available in this build", name)));
                }
            }
            "toggle_watch" => {
                self.panel.status = Some(Status::from_error("watching not available"));
            }
            "filesystems" | "open_trash" | "restore_trashed_file" | "delete_trashed_file" | "purge_trash"
            | "focus_staging_area_no_open" | "clear_stage" | "stage" | "unstage" | "stage_all_directories"
            | "stage_all_files" | "toggle_stage" | "open_staging_area" | "close_staging_area"
            | "toggle_staging_area" | "set_syntax_theme" | "set_panel_width" | "default_layout"
            | "move_panel_divider" => {
                self.panel.status = Some(Status::from_error(format!("{}: not available in this build", name)));
            }
            _ => {
                self.panel.status = Some(Status::from_error(format!("verb not found: \"{}\"", name)));
            }
        }
        if self.quitting {
            return Ok(());
        }
        // after a successful internal (not an error), the input is cleared when it contained a verb
        if self.panel.status.is_none() {
            let input = self.panel.input.content();
            let parsed = pattern::parse_input(&input);
            if parsed.verb.is_some() {
                self.panel.input.set_content(&parsed.pattern_raw);
            }
        }
        Ok(())
    }

    /// the displayed tree as a string (for print_tree)
    fn tree_to_string(&self) -> Result<String, AppError> {
        let mut buf: Vec<u8> = Vec::new();
        if let Some(b) = self.browser() {
            let tree = b.displayed_tree();
            let height = tree.lines.len().min(self.page_height() + 1).max(1);
            // print the visible lines (first the root, then from scroll)
            let dt = DisplayableTree {
                tree,
                skin: &self.ctx.skin,
                area_x: 0,
                area_y: 0,
                width: self.screen.width as usize,
                height: if tree.lines.len() > self.page_height() { self.page_height() + 1 } else { height },
                in_app: false,
                ext_colors: &self.ctx.conf.ext_colors,
                show_scrollbar: false,
            };
            dt.write(&mut buf)?;
        }
        Ok(String::from_utf8_lossy(&buf).to_string())
    }
}

pub fn shell_quote(s: &str) -> String {
    if s.is_empty() {
        return "''".to_string();
    }
    if s.chars().all(|c| c.is_ascii_alphanumeric() || "/._-+=:,@%~".contains(c)) {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', "'\\''"))
    }
}

pub fn shell_join(parts: &[String]) -> String {
    parts.iter().map(|p| shell_quote(p)).collect::<Vec<_>>().join(" ")
}

pub fn relative_path(base: &Path, path: &Path) -> String {
    let base: Vec<_> = base.components().collect();
    let target: Vec<_> = path.components().collect();
    let mut i = 0;
    while i < base.len() && i < target.len() && base[i] == target[i] {
        i += 1;
    }
    let mut parts: Vec<String> = Vec::new();
    for _ in i..base.len() {
        parts.push("..".to_string());
    }
    for c in &target[i..] {
        parts.push(c.as_os_str().to_string_lossy().to_string());
    }
    if parts.is_empty() {
        ".".to_string()
    } else {
        parts.join("/")
    }
}
