//! installation of the br shell function

use crate::conf;
use crate::termprint;
use std::io::Write;
use std::path::{Path, PathBuf};

const BASH_FUNC: &str = include_str!("../resources/shell/br.bash");
const FISH_FUNC: &str = include_str!("../resources/shell/br.fish");
const NUSHELL_FUNC: &str = include_str!("../resources/shell/br.nushell");
const POWERSHELL_FUNC: &str = include_str!("../resources/shell/br.powershell");

pub fn shell_function(shell: &str) -> Option<&'static str> {
    match shell {
        "bash" | "zsh" => Some(BASH_FUNC),
        "fish" => Some(FISH_FUNC),
        "nushell" | "nu" => Some(NUSHELL_FUNC),
        "powershell" | "pwsh" => Some(POWERSHELL_FUNC),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InstallState {
    Undefined,
    Refused,
    Installed,
}

const REFUSED_FILE_CONTENT: &str = "\nThis file tells broot you refused the installation of the companion shell function.\nIf you want to install it run\n    broot -- install\n";
const INSTALLED_FILE_CONTENT: &str = "\nThis file tells broot the installation of the br function was done.\nIf there's a problem and you want to install it again run\n    broot -- install\n";

pub fn launcher_dir(config_dir: &Path) -> PathBuf {
    config_dir.join("launcher")
}

pub fn get_state(config_dir: &Path) -> InstallState {
    let ld = launcher_dir(config_dir);
    if ld.join("installed-v4").exists() {
        InstallState::Installed
    } else if ld.join("refused").exists() {
        InstallState::Refused
    } else {
        InstallState::Undefined
    }
}

pub fn set_state(w: &mut impl Write, config_dir: &Path, state: InstallState) -> std::io::Result<()> {
    let ld = launcher_dir(config_dir);
    for (name, keep) in [
        ("refused", state == InstallState::Refused),
        ("installed-v4", state == InstallState::Installed),
    ] {
        let p = ld.join(name);
        if p.exists() && !keep {
            termprint::print_inline(w, &format!("Removing `{}`.\n", p.display()));
            std::fs::remove_file(&p)?;
        }
    }
    match state {
        InstallState::Refused => {
            std::fs::create_dir_all(&ld)?;
            std::fs::write(ld.join("refused"), REFUSED_FILE_CONTENT)?;
        }
        InstallState::Installed => {
            std::fs::create_dir_all(&ld)?;
            std::fs::write(ld.join("installed-v4"), INSTALLED_FILE_CONTENT)?;
        }
        InstallState::Undefined => {}
    }
    Ok(())
}

const MD_INSTALL_REQUEST: &str = r#"
**Broot** should be launched using a shell function.
This function most notably makes it possible to `cd`
from inside broot
(see *https://dystroy.org/broot/install-br/* for explanations).

Can I install it now? [**Y**/n]
"#;

const MD_INSTALL_REFUSED: &str = r#"
You refused the installation (for now).
You can still used `broot` but some features won't be available.
If you want the `br` shell function, you may either
* do `broot --install`
* install the various pieces yourself
(see *https://dystroy.org/broot/install-br/* for details).
"#;

const MD_INSTALL_DONE: &str = r#"
The **br** function has been successfully installed.
You may have to restart your shell or source your shell init files.
Afterwards, you should start broot with `br` in order to use its full power.
"#;

const MD_NO_SOURCING_FILE_BASH: &str = r#"
I found no sourcing file for the bash/zsh family.
If you're using bash or zsh, then installation isn't complete:
the br function initialization script won't be sourced unless you source it yourself.
"#;

fn remove_if_exists(w: &mut impl Write, path: &Path) -> std::io::Result<()> {
    if path.symlink_metadata().is_ok() {
        termprint::print_inline(w, &format!("Removing `{}`.\n", path.display()));
        if path.is_dir() && !path.symlink_metadata()?.file_type().is_symlink() {
            std::fs::remove_dir_all(path)?;
        } else {
            std::fs::remove_file(path)?;
        }
    }
    Ok(())
}

/// install the br function for all detected shells. Returns true if at least one shell was fully installed.
pub fn install(w: &mut impl Write, config_dir: &Path, clean: bool) -> std::io::Result<()> {
    let home = conf::home_dir();
    let data_dir = conf::data_dir();
    let ld = launcher_dir(config_dir);
    if clean {
        remove_if_exists(w, &ld.join("installed-v4"))?;
        remove_if_exists(w, &ld.join("refused"))?;
    }
    let mut done_all = true;
    // bash & zsh family
    {
        let script_path = data_dir.join("launcher").join("bash").join("1");
        if clean {
            remove_if_exists(w, &script_path)?;
        }
        if !script_path.exists() {
            termprint::print_inline(w, &format!("Writing *br* shell function in `{}`.\n", script_path.display()));
            std::fs::create_dir_all(script_path.parent().unwrap())?;
            std::fs::write(&script_path, BASH_FUNC)?;
        }
        let link_path = ld.join("bash").join("br");
        if clean {
            remove_if_exists(w, &link_path)?;
        }
        if link_path.symlink_metadata().is_err() {
            termprint::print_inline(w, &format!("Creating link from `{}` to `{}`.\n", link_path.display(), script_path.display()));
            std::fs::create_dir_all(link_path.parent().unwrap())?;
            std::os::unix::fs::symlink(&script_path, &link_path)?;
        }
        let source_line = format!("source {}", link_path.display());
        let mut found_sourcing = false;
        for (rc_name, reload) in [(".bashrc", format!("source {}", home.join(".bashrc").display())), (".zshrc", "exec zsh".to_string())] {
            let rc = home.join(rc_name);
            if rc.exists() {
                found_sourcing = true;
                let content = std::fs::read_to_string(&rc).unwrap_or_default();
                if content.contains(&source_line) {
                    termprint::print_inline(w, &format!("`{}` already patched, no change made.\n", rc.display()));
                } else {
                    let mut f = std::fs::OpenOptions::new().append(true).open(&rc)?;
                    write!(f, "\n{}\n", source_line)?;
                    termprint::print_inline(
                        w,
                        &format!(
                            "`{}` successfully patched, you can make the function immediately available with `{}`\n",
                            rc.display(),
                            reload
                        ),
                    );
                }
            }
        }
        if !found_sourcing {
            termprint::print_text(w, MD_NO_SOURCING_FILE_BASH);
            done_all = false;
        }
    }
    // fish
    {
        let fish_dir = home.join(".config").join("fish");
        if fish_dir.exists() {
            let script_path = data_dir.join("launcher").join("fish").join("br.fish");
            if clean {
                remove_if_exists(w, &script_path)?;
            }
            if !script_path.exists() {
                termprint::print_inline(w, &format!("Writing *br* shell function in `{}`.\n", script_path.display()));
                std::fs::create_dir_all(script_path.parent().unwrap())?;
                std::fs::write(&script_path, FISH_FUNC)?;
            }
            let link_path = fish_dir.join("functions").join("br.fish");
            if clean {
                remove_if_exists(w, &link_path)?;
            }
            if link_path.symlink_metadata().is_err() {
                termprint::print_inline(w, &format!("Creating link from `{}` to `{}`.\n", link_path.display(), script_path.display()));
                std::fs::create_dir_all(link_path.parent().unwrap())?;
                std::os::unix::fs::symlink(&script_path, &link_path)?;
            }
        }
    }
    // nushell
    {
        let nu_dir = home.join(".config").join("nushell");
        if nu_dir.exists() {
            let script_path = data_dir.join("launcher").join("nushell").join("br");
            if clean {
                remove_if_exists(w, &script_path)?;
            }
            if !script_path.exists() {
                termprint::print_inline(w, &format!("Writing *br* shell function in `{}`.\n", script_path.display()));
                std::fs::create_dir_all(script_path.parent().unwrap())?;
                std::fs::write(&script_path, NUSHELL_FUNC)?;
            }
            let link_path = ld.join("nushell").join("br");
            if clean {
                remove_if_exists(w, &link_path)?;
            }
            if link_path.symlink_metadata().is_err() {
                termprint::print_inline(w, &format!("Creating link from `{}` to `{}`.\n", link_path.display(), script_path.display()));
                std::fs::create_dir_all(link_path.parent().unwrap())?;
                std::os::unix::fs::symlink(&script_path, &link_path)?;
            }
            let rc = nu_dir.join("config.nu");
            if rc.exists() {
                let source_line = format!("use {} *", link_path.display());
                let content = std::fs::read_to_string(&rc).unwrap_or_default();
                if content.contains(&source_line) {
                    termprint::print_inline(w, &format!("`{}` already patched, no change made.\n", rc.display()));
                } else {
                    let mut f = std::fs::OpenOptions::new().append(true).open(&rc)?;
                    write!(f, "\n{}\n", source_line)?;
                    termprint::print_inline(
                        w,
                        &format!(
                            "`{}` successfully patched, you can make the function immediately available with `{}`\n",
                            rc.display(),
                            "source ~/.config/nushell/config.nu"
                        ),
                    );
                }
            }
        }
    }
    std::fs::create_dir_all(&ld)?;
    std::fs::write(ld.join("installed-v4"), INSTALLED_FILE_CONTENT)?;
    if done_all {
        termprint::print_text(w, MD_INSTALL_DONE);
    }
    Ok(())
}

/// check the installation on launch; returns true if the program must quit
pub fn check_on_launch(w: &mut impl Write, config_dir: &Path) -> std::io::Result<bool> {
    if std::env::var("BR_INSTALL").map(|v| v.eq_ignore_ascii_case("no")).unwrap_or(false) {
        return Ok(false);
    }
    match get_state(config_dir) {
        InstallState::Undefined => {
            termprint::print_text(w, MD_INSTALL_REQUEST);
            w.flush()?;
            let mut answer = String::new();
            let _ = std::io::stdin().read_line(&mut answer);
            let answer = answer.trim().to_lowercase();
            if answer == "n" || answer == "no" {
                set_state(w, config_dir, InstallState::Refused)?;
                termprint::print_text(w, MD_INSTALL_REFUSED);
                Ok(false)
            } else {
                install(w, config_dir, false)?;
                Ok(true)
            }
        }
        _ => Ok(false),
    }
}
