        ("-T", "--no-trim-root", "", "Don't trim the root level, show a scrollbar"),
        ("", "--outcmd", "<path>", "Where to write the produced cmd (if any)"),
        ("", "--verb-output", "<verb-output>", "Optional path for verbs using `:write_output`"),
        ("-c", "--cmd", "<cmd>", "Semicolon separated commands to execute"),
        ("", "--color", "<color>", "Whether to have styles and colors"),
        ("", "", "", " Possible values: [`auto`, `yes`, `no`]"),
        ("", "", "", " Default: `auto`"),
        ("", "--height", "<height>", "Height (if you don't want to fill the screen or for file export)"),
        ("", "--install", "", "Install or reinstall the br shell function"),
        ("", "--set-install-state", "<state>", "Manually set installation state"),
        ("", "", "", " Possible values: [`undefined`, `refused`, `installed`]"),
        ("", "--print-shell-function", "<shell>", "Print to stdout the br function for a given shell"),
        ("", "--listen", "<socket>", "A socket to listen to for commands"),
        ("", "--listen-auto", "", "create a random socket to listen to for commands"),
        ("", "--get-root", "", "Ask for the current root of the remote broot"),
        ("", "--write-default-conf", "<path>", "Write default conf files in given directory"),
        ("", "--send", "<socket>", "A socket to send commands to"),
    ];
    for (short, long, value, desc) in rows {
        let short_cell = if short.is_empty() && long.is_empty() {
            String::new()
        } else if short.is_empty() {
            " ".to_string()
        } else if value.is_empty() {
            format!("{} ", short)
        } else {
            format!("{} *{}*", short, value)
        };
        let long_cell = if long.is_empty() {
            String::new()
        } else if value.is_empty() {
            format!("{} ", long)
        } else {
            format!("{} *{}*", long, value)
        };
        md.push_str(&format!("|{}|{}|{}\n", short_cell, long_cell, desc));
    }
    md.push_str("|-\n");
    md
}

pub fn cli_skin() -> Skin {
    let mut skin = Skin::no_color();
    let _ = skin.apply("help_paragraph", "none none");
    let _ = skin.apply("help_bold", "none none bold");
    let _ = skin.apply("help_italic", "none none italic");
    let _ = skin.apply("help_code", "ansi(249) ansi(235)");
    let _ = skin.apply("help_headers", "none none");
    let _ = skin.apply("help_table_border", "ansi(239) none");
    let _ = skin.apply("help_bullet", "ansi(240) none");
    skin
}

pub fn print_help(w: &mut impl Write, bin_name: &str) -> std::io::Result<()> {
    let width = termprint::term_width();
    let md = help_markdown(bin_name);
    let blocks = mad::parse(&md);
    let skin = cli_skin();
    let lines = mad::render_no_pad(&blocks, &skin, width);
    for line in lines {
        for (st, s) in &line.spans {
            crate::screen::write_styled(w, st, s)?;
        }
        writeln!(w)?;
    }
    writeln!(w)?;
    Ok(())
}
