use app::{App, AppContext, Launchable};
use crossterm::{cursor, event, execute, queue, terminal};
use std::io::Write;
use std::path::PathBuf;
use tree::{Sort, TreeOptions};

fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim().to_lowercase();
    let num_end = s.find(|c: char| !c.is_ascii_digit() && c != '.').unwrap_or(s.len());
    let num: f64 = s[..num_end].parse().ok()?;
    let unit = s[num_end..].trim();
    let mult: f64 = match unit {
        "" | "b" => 1.0,
        "k" | "kb" => 1000.0,
        "m" | "mb" => 1_000_000.0,
        "g" | "gb" => 1_000_000_000.0,
        "t" | "tb" => 1_000_000_000_000.0,
        "kib" => 1024.0,
        "mib" => 1024.0 * 1024.0,
        "gib" => 1024.0 * 1024.0 * 1024.0,
        _ => return None,
    };
    Some((num * mult) as u64)
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let bin_name = argv
        .first()
        .and_then(|s| std::path::Path::new(s).file_name().map(|f| f.to_string_lossy().to_string()))
        .unwrap_or_else(|| "broot".to_string());
    let args = match cli::parse(&argv) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{}", e.message);
            std::process::exit(2);
        }
    };
    let code = run(args, &bin_name);
    std::process::exit(code);
}

fn run(args: cli::Args, bin_name: &str) -> i32 {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    if args.help {
        let _ = cli_help::print_help(&mut out, bin_name);
        return 0;
    }
    if args.version {
        let _ = writeln!(out, "broot {}", help::VERSION);
        return 0;
    }
    if let Some(shell) = &args.print_shell_function {
        match install::shell_function(shell) {
            Some(f) => {
                let _ = write!(out, "{}\n", f);
                return 0;
            }
            None => {
                let _ = writeln!(out, "Unknown shell: {}", shell);
                return 1;
            }
        }
    }
    if let Some(dir) = &args.write_default_conf {
        for (name, content) in conf::DEFAULT_CONF_FILES {
            let path = dir.join(name);
            if path.exists() {
                continue;
            }
            if let Some(parent) = path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Err(e) = std::fs::write(&path, content) {
                eprintln!("IO Error : {}", e);
                return 1;
            }
        }
        return 0;
    }
    let config_dir = conf::config_dir();
    if let Some(state) = &args.set_install_state {
        let st = match state.as_str() {
            "refused" => install::InstallState::Refused,
            "installed" => install::InstallState::Installed,
            _ => install::InstallState::Undefined,
        };
        if let Err(e) = install::set_state(&mut out, &config_dir, st) {
            eprintln!("IO Error : {}", e);
            return 1;
        }
        return 0;
    }
    if args.install {
        termprint::print_inline(&mut out, "You requested a clean (re)install.\n");
        if let Err(e) = install::install(&mut out, &config_dir, true) {
            eprintln!("IO Error : {}", e);
            return 1;
        }
        return 0;
    }
    // normal launch: install check
    match install::check_on_launch(&mut out, &config_dir) {
        Ok(true) => return 0,
        Ok(false) => {}
        Err(e) => {
            eprintln!("IO Error : {}", e);
            return 1;
        }
    }
    // configuration
    let conf_paths: Vec<PathBuf> = match &args.conf {
        Some(c) => c.split(';').filter(|s| !s.is_empty()).map(PathBuf::from).collect(),
        None => {
            let main = config_dir.join("conf.hjson");
            if !main.exists() {
                if let Err(e) = conf::write_default_conf_files(&config_dir) {
                    eprintln!("IO Error : {}", e);
                    return 1;
                }
                termprint::print_inline(
                    &mut out,
                    &format!(
                        "New Configuration files written in **\"{}\"**.\n",
                        config_dir.display()
                    ),
                );
                let _ = writeln!(out, "You should have a look at them: their comments will help you configure broot.");
                let _ = writeln!(out, "You should especially set up your favourite editor in verbs.hjson.");
            }
            vec![main]
        }
    };
    let _ = out.flush();
    let conf = conf::Conf::read(&conf_paths);
    for e in &conf.errors {
        eprintln!("{}", e);
    }
    if conf.errors.iter().any(|e| e.starts_with("Invalid configuration file")) {
        return 1;
    }
    // tree options
    let mut options = TreeOptions::default();
    options.show_selection_mark = conf.show_selection_mark;
    if let Some(flags) = &conf.default_flags {
        let _ = options.apply_flags(flags);
    }
    if let Some(fmt) = &conf.date_time_format {
        options.date_time_format = fmt.clone();
    }
    if let Some(cols) = &conf.cols_order {
        let parsed: Vec<tree::Col> = cols.iter().filter_map(|c| tree::Col::from_name(c)).collect();
        if !parsed.is_empty() {
            let mut all = parsed.clone();
            for c in tree::DEFAULT_COLS {
                if !all.contains(&c) {
                    // keep name last
                    if c == tree::Col::Name {
                        all.push(c);
                    } else {
                        let pos = all.iter().position(|x| *x == tree::Col::Name).unwrap_or(all.len());
                        all.insert(pos, c);
                    }
                }
            }
            options.cols_order = all;
        }
    }
    for sp in &conf.special_paths {
        if let Some(g) = tree::GlobPattern::new(&sp.pattern) {
            let mode = |s: &Option<String>| match s.as_deref().map(|s| s.to_lowercase()) {
                Some(ref v) if v == "always" || v == "enter" || v == "show" => tree::SpecialHandlingMode::Always,
                Some(ref v) if v == "never" || v == "no-enter" || v == "hide" => tree::SpecialHandlingMode::Never,
                _ => tree::SpecialHandlingMode::Default,
            };
            options.special_paths.push(tree::SpecialPath {
                pattern: g,
                show: mode(&sp.show),
                list: mode(&sp.list),
                sum: mode(&sp.sum),
            });
        }
    }
    // launch args override
    if args.dates { options.show_dates = true; }
    if args.no_dates { options.show_dates = false; }
    if args.only_folders { options.only_folders = true; }
    if args.no_only_folders { options.only_folders = false; }
    if args.show_root_fs { options.show_root_fs = true; }
    if let Some(d) = args.max_depth { options.max_depth = Some(d); }
    if args.show_git_info { options.show_git_file_info = true; }
    if args.no_show_git_info { options.show_git_file_info = false; }
    if args.git_status { options.filter_by_git_status = true; }
    if args.hidden { options.show_hidden = true; }
    if args.no_hidden { options.show_hidden = false; }
    if args.git_ignored { options.respect_git_ignore = false; }
    if args.no_git_ignored { options.respect_git_ignore = true; }
    if args.permissions { options.show_permissions = true; }
    if args.no_permissions { options.show_permissions = false; }
    if args.sizes { options.show_sizes = true; }
    if args.no_sizes { options.show_sizes = false; }
    if args.sort_by_count { options.sort = Sort::Count; options.show_counts = true; }
    if args.sort_by_date { options.sort = Sort::Date; options.show_dates = true; }
    if args.sort_by_size { options.sort = Sort::Size; options.show_sizes = true; }
    if args.sort_by_type || args.sort_by_type_dirs_first { options.sort = Sort::TypeDirsFirst; }
    if args.sort_by_type_dirs_last { options.sort = Sort::TypeDirsLast; }
    if args.no_sort { options.sort = Sort::None; }
    if args.no_tree { options.show_tree = false; }
    if args.tree { options.show_tree = true; }
    if args.whale_spotting {
        options.show_hidden = true;
        options.respect_git_ignore = false;
        options.sort = Sort::Size;
        options.show_sizes = true;
        options.show_root_fs = true;
    }
    if args.no_whale_spotting {
        options.show_hidden = false;
        options.respect_git_ignore = true;
        options.sort = Sort::None;
        options.show_sizes = false;
    }
    if args.trim_root { options.trim_root = true; }
    if args.no_trim_root { options.trim_root = false; }

    // root
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/"));
    let mut root = match &args.root {
        Some(r) => {
            if r.is_absolute() {
                r.clone()
            } else {
                cwd.join(r)
            }
        }
        None => cwd.clone(),
    };
    let mut select_file: Option<PathBuf> = None;
    match std::fs::metadata(&root) {
        Ok(md) => {
            if !md.is_dir() {
                select_file = Some(root.clone());
                root = root.parent().map(|p| p.to_path_buf()).unwrap_or(root);
            }
        }
        Err(e) => {
            eprintln!("IO Error : {}", e);
            return 1;
        }
    }
    let root = std::fs::canonicalize(&root).unwrap_or(root);

    // color
    let color = match args.color.as_deref() {
        Some("no") => false,
        Some("yes") => true,
        _ => true,
    };
    let skin = if color { conf.skin.clone() } else { skin::Skin::no_color() };
    let verbs = verb::VerbStore::new(&conf.verbs);
    let content_max_size = conf
        .content_search_max_file_size
        .as_deref()
        .and_then(parse_size)
        .unwrap_or(10_000_000);
    let cmd_separator = std::env::var("BROOT_CMD_SEPARATOR").unwrap_or_else(|_| ";".to_string());
    let commands: Vec<String> = match &args.cmd {
        Some(c) => c.split(cmd_separator.as_str()).map(|s| s.to_string()).filter(|s| !s.is_empty()).collect(),
        None => Vec::new(),
    };
    let ctx = AppContext {
        conf,
        verbs,
        skin,
        args: args.clone(),
        initial_root: root.clone(),
        config_dir: config_dir.clone(),
        content_max_size,
        cmd_separator,
    };

    // terminal
    let mut stderr = std::io::stderr();
    if !is_tty(0) && !is_tty(1) && !is_tty(2) {
        let _ = write!(
            stderr,
            "\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049lTermimad Error : IO error: No such device or address (os error 6)\n"
        );
        return 1;
    }
    if let Err(e) = terminal::enable_raw_mode() {
        eprintln!("Termimad Error : IO error: {}", e);
        return 1;
    }
    let _ = execute!(stderr, terminal::EnterAlternateScreen, cursor::Hide, event::EnableMouseCapture);
    let result = (|| -> Result<(App, Vec<Launchable>), app::AppError> {
        let mut app = App::new(ctx, options)?;
        if let Some(f) = &select_file {
            if let Some(b) = app.panel.states.last_mut() {
                if let app::State::Browser(b) = b {
                    b.displayed_tree_mut().try_select_path(f);
                }
            }
        }
        let launchables = app.run(&mut stderr, commands)?;
        Ok((app, launchables))
    })();
    let _ = execute!(stderr, event::DisableMouseCapture, cursor::Show, terminal::LeaveAlternateScreen);
    let _ = terminal::disable_raw_mode();
    match result {
        Err(e) => {
            eprintln!("{}", e.0);
            1
        }
        Ok((app, launchables)) => {
            // out commands
            if let Some(path) = &args.outcmd {
                if !app.out_cmds.is_empty() {
                    let content = app.out_cmds.join("\n");
                    if let Err(e) = std::fs::write(path, content) {
                        eprintln!("IO Error : {}", e);
                        return 1;
                    }
                }
            }
            for l in launchables {
                match l {
                    Launchable::Print(s) => {
                        let _ = out.write_all(s.as_bytes());
                        let _ = out.flush();
                    }
                    Launchable::Exec { parts, working_dir } => {
                        if parts.is_empty() {
                            continue;
                        }
                        let mut c = std::process::Command::new(&parts[0]);
                        c.args(&parts[1..]);
                        if let Some(wd) = working_dir {
                            c.current_dir(wd);
                        }
                        match c.status() {
                            Ok(_) => {}
                            Err(e) => {
                                eprintln!("Error while executing {}: {}", parts[0], e);
                                return 1;
                            }
                        }
                    }
                }
            }
            let _ = queue!(out, crossterm::style::ResetColor);
            0
        }
    }
}
