#[derive(Debug, Clone)]
struct Cell {
    c: char,
    style: MdStyle,
    ellipsis: bool,
}

fn flatten(compounds: &[Compound]) -> Vec<Cell> {
    let mut cells = Vec::new();
    for c in compounds {
        for ch in c.text.chars() {
            cells.push(Cell { c: ch, style: c.style, ellipsis: false });
        }
    }
    cells
}

fn unflatten(cells: &[Cell]) -> Vec<Compound> {
    let mut out: Vec<Compound> = Vec::new();
    for cell in cells {
        let style = if cell.ellipsis { MdStyle::Normal } else { cell.style };
        let is_ell = cell.ellipsis;
        match out.last_mut() {
            Some(last) if last.style == style && !is_ell && !last.text.ends_with('…') => last.text.push(cell.c),
            _ => out.push(Compound { text: cell.c.to_string(), style }),
        }
    }
    out
}

/// the number of chars which can be saved by compressing the words of the message
pub fn compressibility(message: &str) -> (usize, usize) {
    let compounds = parse_md_line(message);
    let cells = flatten(&compounds);
    let mut total = 0;
    let mut nb = 0;
    let mut start = 0;
    while start < cells.len() {
        while start < cells.len() && cells[start].c == ' ' {
            start += 1;
        }
        let mut end = start;
        while end < cells.len() && cells[end].c != ' ' {
            end += 1;
        }
        if end - start >= 6 {
            total += end - start - 3;
            nb += 1;
        }
        start = end;
    }
    (total, nb)
}

/// make the compounds fit in the given width by removing chars in the middle of long words
/// then cutting the end with an ellipsis
pub fn fit_compounds(compounds: &mut Vec<Compound>, width: usize) {
    let mut excess = compounds_width(compounds) as isize - width as isize;
    if excess <= 0 {
        return;
    }
    let mut cells = flatten(compounds);
    // phase 1: compress long words (longest first)
    loop {
        if excess <= 0 {
            break;
        }
        let mut best: Option<(usize, usize)> = None; // (start, len)
        let mut start = 0;
        while start < cells.len() {
            while start < cells.len() && cells[start].c == ' ' {
                start += 1;
            }
            let mut end = start;
            while end < cells.len() && cells[end].c != ' ' {
                end += 1;
            }
            let len = end - start;
            if len >= 4 && !cells[start..end].iter().any(|c| c.ellipsis) {
                if best.map_or(true, |(_, bl)| len > bl) {
                    best = Some((start, len));
                }
            }
            start = end;
        }
        let (start, len) = match best {
            Some(b) => b,
            None => break,
        };
        let max_save = (len - 3) as isize;
        let save = excess.min(max_save);
        let remove = save as usize + 1;
        let keep = len - remove;
        let left = keep / 2;
        let style = cells[start + left].style;
        cells.splice(start + left..start + left + remove, std::iter::once(Cell { c: '…', style, ellipsis: true }));
        excess -= save;
    }
    if excess > 0 {
        // phase 2: cut the end
        let target = width.saturating_sub(1);
        let mut acc = 0;
        let mut cut = cells.len();
        for (i, c) in cells.iter().enumerate() {
            let w = screen::char_width(c.c);
            if acc + w > target {
                cut = i;
                break;
            }
            acc += w;
        }
        cells.truncate(cut);
        let style = cells.last().map(|c| c.style).unwrap_or(MdStyle::Normal);
        cells.push(Cell { c: '…', style, ellipsis: true });
    }
    *compounds = unflatten(&cells);
}

