new='''    let avail = table_width_max;
    let total = |ws: &Vec<usize>| ws.iter().sum::<usize>() + nb_cols + 1;
    if total(&widths) > avail {
        // floors: the mean width of the column cells (header excluded), at least 4
        let nb_rows = cell_compounds.len().saturating_sub(1).max(1);
        let floors: Vec<usize> = (0..nb_cols)
            .map(|ci| {
                let sum: usize = cell_compounds.iter().skip(1).map(|row| crate::status::compounds_width(&row[ci])).sum();
                let mean = (sum as f64 / nb_rows as f64).ceil() as usize;
                mean.max(4).min(widths[ci])
            })
            .collect();
        // round 1: columns in descending natural width are reduced down to their floor
        let mut order: Vec<usize> = (0..nb_cols).collect();
        order.sort_by_key(|&ci| std::cmp::Reverse(widths[ci]));
        for &ci in &order {
            let excess = total(&widths).saturating_sub(avail);
            if excess == 0 {
                break;
            }
            let reducible = widths[ci].saturating_sub(floors[ci]);
            widths[ci] -= reducible.min(excess);
        }
        // round 2: the widest columns are reduced further
        while total(&widths) > avail {
            let (idx, _) = widths.iter().enumerate().max_by_key(|(i, w)| (**w, std::cmp::Reverse(*i))).unwrap();
            if widths[idx] <= 3 {
                break;
            }
            widths[idx] -= 1;
        }
    }
