            Ok(bytes) => {
                let probe = &bytes[..bytes.len().min(4096)];
                if probe.contains(&0) || std::str::from_utf8(probe).is_err() && probe.iter().filter(|b| **b >= 0x80).count() > probe.len() / 3 {
                    (hex_lines(&bytes), true)
                } else {
                    let text = String::from_utf8_lossy(&bytes).to_string();
                    let mut lines: Vec<String> = text.split('\n').map(|l| l.trim_end_matches('\r').replace('\t', "    ")).collect();
                    if lines.last().map_or(false, |l| l.is_empty()) {
                        lines.pop();
                    }
                    (lines, false)
                }
            }
            Err(_) => (Vec::new(), false),
        };
        let selection = if lines.is_empty() { None } else { Some(0) };
        PreviewState {
            path: path.to_path_buf(),
            lines,
            binary,
            scroll: 0,
            selection,
            pattern: Pattern::None,
            filtered: None,
        }
    }

    pub fn set_pattern(&mut self, pattern: Pattern) {
        if pattern.is_none() || pattern.is_empty() {
            self.pattern = Pattern::None;
            self.filtered = None;
            return;
        }
        let mut v = Vec::new();
        for (i, l) in self.lines.iter().enumerate() {
            let cand = crate::pattern::Candidate { name: l, subpath: l, path: &self.path, regular_file: false };
            if pattern.score_of(&cand).is_some() {
                v.push(i);
            }
        }
        self.pattern = pattern;
        self.selection = v.first().copied();
        self.filtered = Some(v);
        self.scroll = 0;
    }

    /// the displayed line indexes
    fn displayed(&self) -> Vec<usize> {
        match &self.filtered {
            Some(f) => f.clone(),
            None => (0..self.lines.len()).collect(),
        }
    }

    pub fn move_selection(&mut self, dy: i32, page_height: usize) {
        let displayed = self.displayed();
        if displayed.is_empty() {
            return;
        }
        let cur = self
            .selection
            .and_then(|s| displayed.iter().position(|i| *i == s))
            .unwrap_or(0) as i32;
        let n = displayed.len() as i32;
        let new = (cur + dy).rem_euclid(n) as usize;
        self.selection = Some(displayed[new]);
        self.make_selection_visible(page_height);
    }

    pub fn scroll_by(&mut self, dy: i32, page_height: usize) {
        let n = self.displayed().len();
        let max_scroll = n.saturating_sub(page_height.saturating_sub(1));
        self.scroll = (self.scroll as i32 + dy).clamp(0, max_scroll as i32) as usize;
    }

    fn make_selection_visible(&mut self, page_height: usize) {
        let displayed = self.displayed();
        let content_rows = page_height.saturating_sub(1).max(1);
        if let Some(sel) = self.selection {
            if let Some(pos) = displayed.iter().position(|i| *i == sel) {
                if pos < self.scroll {
                    self.scroll = pos;
                } else if pos >= self.scroll + content_rows {
                    self.scroll = pos + 1 - content_rows;
                }
            }
        }
    }

    pub fn display<W: Write>(
        &self,
        w: &mut W,
        skin: &Skin,
        x: u16,
        y: u16,
        width: usize,
        height: usize,
    ) -> std::io::Result<()> {
        let title_style = skin.style("preview_title");
        let default_style = skin.style("default");
        let preview_style = skin.style("preview");
        let num_style = skin.style("preview_line_number");
        let selected_bg = skin.style("selected_line").bg;
        let match_style = skin.style("preview_match");
