        let name = self.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        let count_s = format!("lines: {}", self.lines.len());
        let avail_title = width.saturating_sub(count_s.len());
        let (fitted, fw) = screen::fit_str(&name, avail_title);
        write_styled(w, &title_style, &fitted)?;
        if fw < avail_title {
            screen::write_spaces(w, &title_style, avail_title - fw)?;
        }
        write_styled(w, &default_style, &count_s)?;
        let displayed = self.displayed();
        let show_numbers = width >= 56 && !self.binary;
        let num_width = if show_numbers { self.lines.len().to_string().len() + 2 } else { 1 };
        for row in 1..height {
            screen::goto(w, x, y + row as u16)?;
            let idx = self.scroll + row - 1;
            if idx < displayed.len() {
                let li = displayed[idx];
                let selected = self.selection == Some(li);
                let mut line_style = preview_style.clone();
                if selected {
                    line_style.bg = selected_bg;
                }
                if show_numbers {
                    let s = format!(" {:>w$} ", li + 1, w = num_width - 2);
                    write_styled(w, &num_style, &s)?;
                } else {
                    write_styled(w, &line_style, " ")?;
                }
                write_styled(w, &line_style, if selected { "▶" } else { " " })?;
                let content_width = width.saturating_sub(num_width + 1);
                let (fitted, fw) = screen::fit_str(&self.lines[li], content_width);
                if self.pattern.is_some() {
                    // highlight the matching chars
                    let positions = self
                        .pattern
                        .search_string(&fitted, crate::pattern::SearchObject::Name)
                        .map(|m| m.pos)
                        .unwrap_or_default();
                    let mut cur: Option<bool> = None;
                    let mut buf = String::new();
                    for (i, c) in fitted.chars().enumerate() {
                        let m = positions.contains(&i);
                        if cur.is_some() && cur != Some(m) {
                            let st: &Style = if cur == Some(true) { &match_style } else { &line_style };
                            let mut st2 = st.clone();
                            if st2.bg.is_none() {
                                st2.bg = line_style.bg;
                            }
                            write_styled(w, &st2, &buf)?;
                            buf.clear();
                        }
                        cur = Some(m);
                        buf.push(c);
                    }
                    if !buf.is_empty() {
                        let st: &Style = if cur == Some(true) { &match_style } else { &line_style };
                        let mut st2 = st.clone();
                        if st2.bg.is_none() {
                            st2.bg = line_style.bg;
                        }
                        write_styled(w, &st2, &buf)?;
                    }
                } else {
                    write_styled(w, &line_style, &fitted)?;
                }
                if fw < content_width {
                    screen::write_spaces(w, &line_style, content_width - fw)?;
                }
            } else {
                screen::write_spaces(w, &preview_style, width)?;
            }
        }
        Ok(())
    }
}

fn hex_lines(bytes: &[u8]) -> Vec<String> {
    let mut lines = Vec::new();
    for (i, chunk) in bytes.chunks(16).enumerate() {
        let mut s = format!("{:08x} ", i * 16);
        for (j, b) in chunk.iter().enumerate() {
            if j == 8 {
                s.push(' ');
            }
            s.push_str(&format!("{:02x} ", b));
        }
        for _ in chunk.len()..16 {
            s.push_str("   ");
        }
        s.push(' ');
        for b in chunk {
            s.push(if b.is_ascii_graphic() || *b == b' ' { *b as char } else { '.' });
        }
        lines.push(s);
        if lines.len() > 100_000 {
            break;
        }
    }
    lines
}
