        for pi in 0..nb_panels {
            let (ax, aw) = areas[pi];
            let focused = pi == self.active;
            let skin = self.ctx.skin.with_focus(focused);
            self.display_panel_state(w, pi, &skin, ax, aw, page_height)?;
        }
        // status: the one of the active panel
        let skin = self.ctx.skin.clone();
        let status = self.compute_status();
        crate::status::write_status(w, &skin, &status, 0, (height - 2) as u16, width)?;
        // inputs and flags
        for pi in 0..nb_panels {
            let (ax, aw) = areas[pi];
            let focused = pi == self.active;
            let pskin = self.ctx.skin.with_focus(focused);
            let flags = if focused { self.flags() } else { Vec::new() };
            let mut flags_width = 0;
            for (label, _value) in &flags {
                flags_width += if label.is_empty() { 0 } else { label.chars().count() + 2 } + 1 + 1;
            }
            let input_width = aw.saturating_sub(flags_width + 1);
            let mut input = self.panels[pi].input.clone();
            input.focused = focused;
            input.display(w, &pskin, ax, (height - 1) as u16, input_width)?;
            screen::goto(w, ax + input_width as u16, (height - 1) as u16)?;
            let label_style = pskin.style("flag_label");
            let value_style = pskin.style("flag_value");
            for (label, value) in &flags {
                if !label.is_empty() {
                    write_styled(w, &label_style, &format!(" {}:", label))?;
                }
                write_styled(w, &value_style, value)?;
                write_styled(w, &label_style, " ")?;
            }
            if focused {
                // the last column of the area is left untouched
            } else {
                screen::write_spaces(w, &pskin.style("default"), aw.saturating_sub(input_width))?;
            }
        }
        queue!(w, crossterm::style::ResetColor)?;
        Ok(())
    }

    fn display_panel_state(
        &mut self,
        w: &mut impl Write,
        pi: usize,
        skin: &Skin,
        ax: u16,
        aw: usize,
        page_height: usize,
    ) -> std::io::Result<()> {
        let width = aw;
        let ext_colors = self.ctx.conf.ext_colors.clone();
        match self.panels[pi].states.last_mut().unwrap() {
            State::Browser(b) => {
                let tree = b.displayed_tree();
                let dt = DisplayableTree {
                    tree,
                    skin,
                    area_x: ax,
                    area_y: 0,
                    width,
                    height: page_height,
                    in_app: true,
                    ext_colors: &ext_colors,
                    show_scrollbar: !tree.options.trim_root,
                };
                dt.write(w)?;
            }
            State::Preview(p) => {
                p.display(w, skin, ax, 0, width, page_height)?;
            }
            State::Help(h) => {
                let area_width = width.min(120);
                let area_x = ax + ((width - area_width) / 2) as u16;
                if h.lines.is_empty() || h.width != area_width {
                    let hctx = help::HelpContext {
                        conf: &self.ctx.conf,
                        verbs: &self.ctx.verbs.verbs,
                        config_dir: &self.ctx.config_dir,
                    };
                    let md = help::help_markdown(&hctx, &h.pattern);
                    let blocks = mad::parse(&md);
                    let table_width = area_width.saturating_sub(1);
                    let lines = mad::render(&blocks, skin, area_width, table_width);
                    if lines.len() > page_height {
                        h.lines = mad::render(&blocks, skin, area_width.saturating_sub(1), table_width);
                    } else {
                        h.lines = lines;
                    }
                    h.width = area_width;
                }
                let total = h.lines.len();
                let max_scroll = total.saturating_sub(page_height);
                if h.scroll > max_scroll {
                    h.scroll = max_scroll;
                }
                let default_style = skin.style("default");
                let bg = skin.style("help_paragraph");
                for y in 0..page_height {
                    screen::goto(w, ax, y as u16)?;
                    if area_x > ax {
                        screen::write_spaces(w, &default_style, (area_x - ax) as usize)?;
                    }
                    let li = y + h.scroll;
                    let mut used = 0;
                    if li < total {
                        let line = &h.lines[li];
                        for (st, s) in &line.spans {
                            write_styled(w, st, s)?;
                            used += screen::str_width(s);
                        }
                    }
                    if used < area_width {
                        screen::write_spaces(w, &bg, area_width - used)?;
                    }
                    if total > page_height {
                        screen::goto(w, area_x + area_width as u16 - 1, y as u16)?;
                        let thumb_len = ((page_height * page_height) as f64 / total as f64).ceil().max(1.0) as usize;
                        let thumb_start = if max_scroll == 0 {
                            0
                        } else {
                            ((h.scroll as f64 / max_scroll as f64) * (page_height - thumb_len.min(page_height)) as f64).round() as usize
                        };
                        let in_thumb = y >= thumb_start && y < thumb_start + thumb_len;
                        let st = if in_thumb {
                            skin.style("scrollbar_thumb")
                        } else {
                            skin.style("scrollbar_track")
                        };
                        write_styled(w, &st, "▐")?;
                    }
                    let right = (ax as usize + width).saturating_sub(area_x as usize + area_width);
                    if right > 0 {
                        screen::goto(w, (area_x as usize + area_width) as u16, y as u16)?;
                        screen::write_spaces(w, &default_style, right)?;
                    }
                }
            }
        }
        Ok(())
    }

