#[derive(Debug, Clone)]
pub struct ContentMatch {
    pub line: String,        // the line containing the match (from the previous control char)
    pub needle_start: usize, // char index in line
    pub needle_end: usize,
}

impl ContentPattern {
    pub fn score_of(&self, path: &Path) -> Option<i32> {
        let found = self.get_match(path)?;
        let _ = found;
        Some(1)
    }
    pub fn is_empty(&self) -> bool {
        match &self.matcher {
            ContentMatcher::Exact(s) => s.is_empty(),
            ContentMatcher::Regex(_) => false,
        }
    }
    /// find the first match in the file (if the file is a reasonable text file)
    pub fn get_match(&self, path: &Path) -> Option<ContentMatch> {
        let md = std::fs::metadata(path).ok()?;
        if !md.is_file() || md.len() > self.max_file_size {
            return None;
        }
        let bytes = std::fs::read(path).ok()?;
        // consider it binary if there's a NUL in the first bytes
        let probe = &bytes[..bytes.len().min(1024)];
        if probe.contains(&0) {
            return None;
        }
        match &self.matcher {
            ContentMatcher::Exact(needle) => {
                if needle.is_empty() {
                    return None;
                }
                let nb = needle.as_bytes();
                let idx = find_bytes(&bytes, nb)?;
                Some(extract_around(&bytes, idx, idx + nb.len()))
            }
            ContentMatcher::Regex(rex) => {
                let text = String::from_utf8_lossy(&bytes);
                let m = rex.find(&text)?;
                let tb = text.as_bytes();
                Some(extract_around(tb, m.start(), m.end()))
            }
        }
    }
}

fn find_bytes(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || hay.len() < needle.len() {
        return None;
    }
    hay.windows(needle.len()).position(|w| w == needle)
}

fn extract_around(bytes: &[u8], start: usize, end: usize) -> ContentMatch {
    // the extract is the part of the line containing the match, starting after the
    // previous control char
    let mut ls = start;
    while ls > 0 && bytes[ls - 1] >= 32 && bytes[ls - 1] != 127 && start - ls < 200 {
        ls -= 1;
    }
    let mut le = end;
    while le < bytes.len() && bytes[le] >= 32 && bytes[le] != 127 && le - end < 400 {
        le += 1;
    }
    let line = String::from_utf8_lossy(&bytes[ls..le]).to_string();
    let needle_start = String::from_utf8_lossy(&bytes[ls..start]).chars().count();
    let needle_end = needle_start + String::from_utf8_lossy(&bytes[start..end]).chars().count();
    ContentMatch { line, needle_start, needle_end }
}

