    /// write the content extract of a content search match
    fn write_content_extract<W: Write, F: Fn(Style) -> Style>(
        &self,
        w: &mut W,
        line: &TreeLine,
        with_bg: &F,
        avail: usize,
        mut used: usize,
    ) -> std::io::Result<usize> {
        let pattern = &self.tree.options.pattern;
        if !(line.direct_match && !line.is_dir()) {
            return Ok(used);
        }
        let cp = match pattern.content_pattern() {
            Some(cp) => cp,
            None => return Ok(used),
        };
        let m = match cp.get_match(&line.path) {
            Some(m) => m,
            None => return Ok(used),
        };
        let extract_style = with_bg(self.skin.style("content_extract"));
        let match_style = with_bg(self.skin.style("content_match"));
        let remaining = avail.saturating_sub(used);
        if remaining <= 2 {
            return Ok(used);
        }
        write_styled(w, &extract_style, "  ")?;
        used += 2;
        let ea = remaining - 2;
        let needle_len = m.needle_end - m.needle_start;
        let max_before = (ea / 2).saturating_sub(needle_len);
        let start = m.needle_start.saturating_sub(max_before);
        let chars: Vec<char> = m.line.chars().collect();
        let mut col = 0;
        let mut parts: Vec<(usize, usize, bool)> = Vec::new();
        if start < m.needle_start {
            parts.push((start, m.needle_start, false));
        }
        parts.push((m.needle_start, m.needle_end, true));
        if m.needle_end < chars.len() {
            parts.push((m.needle_end, chars.len(), false));
        }
        'outer: for (from, to, is_match) in parts {
            let mut buf = String::new();
            for &c in &chars[from.min(chars.len())..to.min(chars.len())] {
                let cw = screen::char_width(c);
                if col + cw > ea {
                    write_styled(w, if is_match { &match_style } else { &extract_style }, &buf)?;
                    break 'outer;
                }
                buf.push(c);
                col += cw;
            }
            write_styled(w, if is_match { &match_style } else { &extract_style }, &buf)?;
        }
        Ok(avail.min(used + col))
    }
}

